很多时候会发现好多，异常流量，处理这些异常流量，通常是封禁IP
`# deny_ip_o.sh 文件内容 #!/bin/bash max=500 #我们设定的最大值，当访问量大于这个值得时候，封锁 logdir=/opt/nginx/logs/access.log #nginx 访问日志文件路径 confdir=/opt/nginx/logs/nginx_deny.log #检测文件 test -e &amp;lt;span class=&#34;katex math inline&#34;&gt;{confdir} || touch&amp;lt;/span&gt;{confdir} port=443 drop_Ip=&#34;&#34; #循环遍历日志文件取出访问量大于 500 的 ip for drop_Ip in &amp;lt;span class=&#34;katex math inline&#34;&gt;(tail -n500000&amp;lt;/span&gt;logdir | awk &#39;{print &amp;lt;span class=&#34;katex math inline&#34;&gt;1}&#39; | sort | uniq -c | sort -rn | awk &#39;{if (&amp;lt;/span&gt;1&gt;500) print &amp;lt;span class=&#34;katex math inline&#34;&gt;2}&#39;) do echo &#34;&amp;lt;/span&gt;{drop_Ip}---&amp;lt;span class=&#34;katex math inline&#34;&gt;{drop_ip}&#34; grep -q &#34;&amp;lt;/span&gt;{drop_Ip}&#34; &amp;lt;span class=&#34;katex math inline&#34;&gt;{confdir} &amp;&amp; eg=1 || eg=0; if ((&amp;lt;/span&gt;{eg}==0 ));then iptables -I INPUT -p tcp --dport &amp;lt;span class=&#34;katex math inline&#34;&gt;{port} -s&amp;lt;/span&gt;{drop_Ip} -j DROP echo &#34;&gt;&gt;&gt;&gt;&gt; `date &#39;+%Y-%m-%d %H%M%S&#39;` - 发现攻击源地址 -&gt; &amp;lt;span class=&#34;katex math inline&#34;&gt;{drop_Ip} &#34; &gt;&gt; /opt/nginx/logs/nginx_deny.log #记录 log fi done #################################################################### #!/bin/bash #_日志位置 _log_Path=&#34;/data0/nginx/weblogs/&#34; #_日志文件名称 _log_FileName=&#34;access_blog.kinggoo.com.log&#34; #_要被屏蔽的ip访问端口，默认80 _port=&#34;80&#34; _nginx_deny=&#34;/opt/webserver/nginx/conf/deny.conf&#34; _nginx_bin=&#34;/opt/webserver/nginx/sbin/nginx&#34; _logfilepath=&amp;lt;/span&gt;{_log_Path}&amp;lt;span class=&#34;katex math inline&#34;&gt;{_log_FileName} #初始化被禁ip变量 _drop_Ip=&#34;&#34; #检测文件 test -e&amp;lt;/span&gt;{_nginx_deny} || touch &amp;lt;span class=&#34;katex math inline&#34;&gt;{_nginx_deny} for _drop_Ip in&amp;lt;/span&gt;( tail -n50000 &#34;&amp;lt;span class=&#34;katex math inline&#34;&gt;{_logfilepath}&#34; |awk &#39;{print&amp;lt;/span&gt;1,&amp;lt;span class=&#34;katex math inline&#34;&gt;12}&#39; |grep -i -v -E &#34;google|yahoo|baidu|msnbot|FeedSky|sogou|WordPress&#34; |awk &#39;{print&amp;lt;/span&gt;1}&#39;|sort|uniq -c|sort -rn |awk &#39;{if(&amp;lt;span class=&#34;katex math inline&#34;&gt;1&gt;1000)print &#34;&#34;&amp;lt;/span&gt;2&#34;&#34;}&#39; ); do grep -q &#34;&amp;lt;span class=&#34;katex math inline&#34;&gt;{_drop_Ip}&#34;&amp;lt;/span&gt;{_nginx_deny} &amp;&amp; eg=1 || eg=0 ; if (( &amp;lt;span class=&#34;katex math inline&#34;&gt;{eg}==0 ));then echo &#34;deny&amp;lt;/span&gt;{_drop_Ip};&#34; &gt;&gt; &amp;lt;span class=&#34;katex math inline&#34;&gt;{_nginx_deny}&amp;lt;/span&gt;{_nginx_bin} -s reload iptables -I INPUT -p tcp -dport &amp;lt;span class=&#34;katex math inline&#34;&gt;{_port} -s&amp;lt;/span&gt;{_drop_Ip} -j DROP echo &#34;&gt;&gt;&gt;&gt;&gt; `date &#39;+%Y-%m-%d %H%M%S&#39;` - 发现攻击源地址 -&gt; &amp;lt;span class=&#34;katex math inline&#34;&gt;{_drop_Ip} &#34; &gt;&gt; /tmp/nginx_deny.log; echo &#34;iptables -I INPUT -p tcp --dport&amp;lt;/span&gt;{_port} -s &amp;lt;span class=&#34;katex math inline&#34;&gt;{_drop_Ip} -j DROP&#34; &gt;&gt; /tmp/nginx_deny.log fi done 使用 nginx 封锁 ... -封锁 IP #!/bin/bash max=500 #我们设定的最大值，当访问量大于这个值得时候，封锁 confdir=/usr/local/data/nginx/conf/blockip.conf #nginx 封锁配置文件路径 logdir=/usr/local/data/nginx/logs/access_huke88.log #nginx 访问日志文件路径 #检测文件 test -e&amp;lt;/span&gt;{confdir} || touch &amp;lt;span class=&#34;katex math inline&#34;&gt;{confdir} drop_ip=&#34;&#34; #循环遍历日志文件取出访问量大于 500 的 ip for drop_ip in&amp;lt;/span&gt;(cat &amp;lt;span class=&#34;katex math inline&#34;&gt;logdir | awk &#39;{print&amp;lt;/span&gt;1}&#39; | sort | uniq -c | sort -rn | awk &#39;{if (&amp;lt;span class=&#34;katex math inline&#34;&gt;1&gt;500) print&amp;lt;/span&gt;2}&#39;) do grep -q &#34;&amp;lt;span class=&#34;katex math inline&#34;&gt;{drop_Ip}&#34;&amp;lt;/span&gt;{confdir} &amp;&amp; eg=1 || eg=0; if (( &amp;lt;span class=&#34;katex math inline&#34;&gt;{eg}==0 ));then echo &#34;deny&amp;lt;/span&gt;{drop_Ip};&#34;&gt;&gt;&amp;lt;span class=&#34;katex math inline&#34;&gt;confdir #把“ deny IP ；”语句写入封锁配置文件中 echo &#34;&gt;&gt;&gt;&gt;&gt; `date &#39;+%Y-%m-%d %H%M%S&#39;` - 发现攻击源地址 -&gt;&amp;lt;/span&gt;{drop_Ip} &#34; &gt;&gt; /usr/local/data/nginx/logs/nginx_deny.log #记录 log fi done service nginx reload -解锁 IP #！/bin/bash sed -i &#39;s/^/#&amp;/g&#39; /usr/local/nginx/conf/blockip.conf #把 nginx 封锁配置文件中的内容注释掉 service nginx reload #重置 nginx 服务，这样就做到了解锁 IP 使用 iptables 封锁 ... -封锁 IP 脚本 #!/bin/bash max=500 #我们设定的最大值，当访问量大于这个值得时候，封锁 logdir=/usr/local/data/nginx/logs/access_huke88.log #nginx 访问日志文件路径 confdir=/usr/local/data/nginx/conf/blockip.conf #nginx 封锁配置文件路径 #检测文件 test -e &amp;lt;span class=&#34;katex math inline&#34;&gt;{confdir} || touch&amp;lt;/span&gt;{confdir} port=80 drop_ip=&#34;&#34; #循环遍历日志文件取出访问量大于 500 的 ip for drop_ip in &amp;lt;span class=&#34;katex math inline&#34;&gt;(cat&amp;lt;/span&gt;logdir | awk &#39;{print &amp;lt;span class=&#34;katex math inline&#34;&gt;1}&#39; | sort | uniq -c | sort -rn | awk &#39;{if (&amp;lt;/span&gt;1&gt;500) print &amp;lt;span class=&#34;katex math inline&#34;&gt;2}&#39;) do grep -q &#34;&amp;lt;/span&gt;{drop_Ip}&#34; &amp;lt;span class=&#34;katex math inline&#34;&gt;{confdir} &amp;&amp; eg=1 || eg=0; if ((&amp;lt;/span&gt;{eg}==0 ));then iptables -I INPUT -p tcp --dport &amp;lt;span class=&#34;katex math inline&#34;&gt;{port} -s&amp;lt;/span&gt;{drop_Ip} -j DROP echo &#34;&gt;&gt;&gt;&gt;&gt; `date &#39;+%Y-%m-%d %H%M%S&#39;` - 发现攻击源地址 -&gt; &amp;lt;span class=&#34;katex math inline&#34;&gt;{drop_Ip} &#34; &gt;&gt; /usr/local/data/nginx/logs/nginx_deny.log #记录 log fi done ... 加入计划任务每五分钟执行一次 chmod +x /home/scripts/deny_ip.sh #####nginx 封 ip###### */5 * * * * /bin/sh /home/scripts/deny_ip.sh &gt;/dev/null 2&gt;&amp;1 ### 添加定时任务 */5 * * * * /bin/sh /opt/nginx/logs/deny_ip_o.sh &gt;/dev/null 2&gt;&amp;1 tail -n 500000 access.log | awk &#39;{print&amp;lt;/span&gt;1,&amp;lt;span class=&#34;katex math inline&#34;&gt;13,&amp;lt;/span&gt;8}&#39;|awk &#39;{print &amp;lt;span class=&#34;katex math inline&#34;&gt;1}&#39;|sort|uniq -c |sort -rn | awk &#39;{if(&amp;lt;/span&gt;1&gt;100)print &#34;deny &#34;&amp;lt;span class=&#34;katex math inline&#34;&gt;1,&amp;lt;/span&gt;2&#34;;&#34;}&#39; tail -n 500000000 access.log | awk &#39;{print &amp;lt;span class=&#34;katex math inline&#34;&gt;1,&amp;lt;/span&gt;13,&amp;lt;span class=&#34;katex math inline&#34;&gt;8}&#39;|awk &#39;{print&amp;lt;/span&gt;1}&#39;|sort|uniq -c |sort -rn | awk &#39;{if(&amp;lt;span class=&#34;katex math inline&#34;&gt;1&gt;100)print &#34;deny &#34;&amp;lt;/span&gt;2&#34;;&#34;}&#39; &gt; blockip.conf tail -n 500000 access.log | awk &#39;{print &amp;lt;span class=&#34;katex math inline&#34;&gt;1,&amp;lt;/span&gt;13,&amp;lt;span class=&#34;katex math inline&#34;&gt;8}&#39;|awk &#39;{print&amp;lt;/span&gt;1}&#39;|sort|uniq -c |sort -rn | awk &#39;{if(&amp;lt;span class=&#34;katex math inline&#34;&gt;1&gt;100)print &#34;deny &#34;&amp;lt;/span&gt;2&#34;;&#34;}&#39; &gt;&gt; blockip.conf #if (&amp;lt;span class=&#34;katex math inline&#34;&gt;http_referer ~* &#34;top1top1.top&#34;) { # rewrite ^/ http://top.top1top1.top/CallHelper/client/main.jsp; #} if (&amp;lt;/span&gt;http_referer ~* &#34;top1top1.top&#34;) { return 404; } if (&amp;lt;span class=&#34;katex math inline&#34;&gt;http_referer ~* &#34;shandiandxshop.xyz&#34;){ rewrite ^/ http://tt.shandiandxshop.xyz/CallHelper/client/index.jsp; } https:&amp;#47;&amp;#47;blog.csdn.net/qq_41018743/article/details/105491785 http://www.siwei.me/blog/posts/linux-nginx-ip-ip #################################################################### #!/bin/bash num=100	# 每秒某个ip的访问上限 list=`netstat -an |grep ^tcp.*:80|egrep -v &#39;LISTEN|127.0.0.1&#39;|awk -F&#34;&amp;#91; ]+|&amp;#91;:]&#34; &#39;{print&amp;lt;/span&gt;6}&#39;|sort|uniq -c|sort -rn|awk &#39;{if (&amp;lt;span class=&#34;katex math inline&#34;&gt;1&gt;&amp;lt;/span&gt;num){print &amp;lt;span class=&#34;katex math inline&#34;&gt;2}}&#39;` for i in&amp;lt;/span&gt;list do iptables -I INPUT -s &amp;lt;span class=&#34;katex math inline&#34;&gt;i --dport 80 -j DROP echo &#34;&gt;&gt;&gt;&gt;&gt; `date &#39;+%Y-%m-%d %H%M%S&#39;` - 发现攻击源地址 -&gt;&amp;lt;/span&gt;{&amp;lt;span class=&#34;katex math inline&#34;&gt;i} &#34; &gt;&gt; /opt/nginx/logs/nginx_deny80.log #记录 log done ##################################################################### #!/bin/bash num=100 list=`netstat -an |grep ^tcp.*:80|egrep -v &#39;LISTEN|127.0.0.1&#39;|awk -F&#34;&amp;#91; ]+|&amp;#91;:]&#34; &#39;{print&amp;lt;/span&gt;6}&#39;|sort|uniq -c|sort -rn|awk &#39;{if (&amp;lt;span class=&#34;katex math inline&#34;&gt;1&gt;&amp;lt;/span&gt;num){print &amp;lt;span class=&#34;katex math inline&#34;&gt;2}}&#39;` for i in&amp;lt;/span&gt;list do iptables -I INPUT -p tcp --dport 80 -s &amp;lt;span class=&#34;katex math inline&#34;&gt;{i} -j DROP echo &#34;&gt;&gt;&gt;&gt;&gt; `date &#39;+%Y-%m-%d %H%M%S&#39;` - 发现攻击源地址 -&gt;&amp;lt;/span&gt;{i} &#34; &gt;&gt; /opt/nginx/logs/nginx_deny80.log done ####################################################################### #!/bin/bash max=500 #我们设定的最大值，当访问量大于这个值得时候，封锁 logdir=/opt/nginx/logs/access.log #nginx 访问日志文件路径 confdir=/opt/nginx/logs/nginx_deny.log #检测文件 test -e &amp;lt;span class=&#34;katex math inline&#34;&gt;{confdir} || touch&amp;lt;/span&gt;{confdir} port=80 drop_ip=&#34;&#34; #循环遍历日志文件取出访问量大于 500 的 ip for drop_ip in &amp;lt;span class=&#34;katex math inline&#34;&gt;(tail -n5000000&amp;lt;/span&gt;logdir | awk &#39;{print &amp;lt;span class=&#34;katex math inline&#34;&gt;1}&#39; | sort | uniq -c | sort -rn | awk &#39;{if (&amp;lt;/span&gt;1&gt;500) print &amp;lt;span class=&#34;katex math inline&#34;&gt;2}&#39;) do grep -q &#34;&amp;lt;/span&gt;{drop_Ip}&#34; &amp;lt;span class=&#34;katex math inline&#34;&gt;{confdir} &amp;&amp; eg=1 || eg=0; if ((&amp;lt;/span&gt;{eg}==0 ));then iptables -I INPUT -p tcp --dport &amp;lt;span class=&#34;katex math inline&#34;&gt;{port} -s&amp;lt;/span&gt;{drop_Ip} -j DROP echo &#34;&gt;&gt;&gt;&gt;&gt; `date &#39;+%Y-%m-%d %H%M%S&#39;` - 发现攻击源地址 -&gt; &amp;lt;span class=&#34;katex math inline&#34;&gt;{drop_Ip} &#34; &gt;&gt; /opt/nginx/logs/nginx_deny.log #记录 log fi done #################################################################### #!/usr/bin/env bash echo &#34;&#34; echo &#34; ========================================================= &#34; echo &#34; \ Nginx日志安全分析脚本 V1.0 / &#34; echo &#34; ========================================================= &#34; echo &#34; # 支持Nginx日志分析，攻击告警分析等 &#34; echo &#34; # author：al0ne &#34; echo &#34; # https://github.com/al0ne &#34; echo -e &#34;
&#34; #此脚本是参考nmgxy/klionsec修改而来,重新添加了一些特征，只用来临时救急，还是推荐到ELK或者Splunk中分析 #功能 ###统计Top 20 地址 ###SQL注入分析 ###SQL注入 FROM查询统计 ###扫描器/常用黑客工具 ###漏洞利用检测 ###敏感路径访问 ###文件包含攻击 ###HTTP Tunnel ###Webshell ###寻找响应长度的url Top 20 ###寻找罕见的脚本文件访问 ###寻找302跳转的脚本文件 #如果存在多个access文件或者有多个access.x.gz 建议先zcat access*.gz &gt;&gt; access.log文件中 #设置分析结果存储目录,结尾不能加/ outfile=/tmp/logs #如果目录以存在则清空，未存在则新建目录 if &amp;#91; -d&amp;lt;/span&gt;outfile ]; then rm -rf &amp;lt;span class=&#34;katex math inline&#34;&gt;outfile/* else mkdir -p&amp;lt;/span&gt;outfile fi #设置nginx日志目录，结尾必须加/ access_dir=/var/log/nginx/ #设置文件名，如果文件名为access那么匹配的是access*文件 access_log=access #判断日志文件是否存在 num=&amp;lt;span class=&#34;katex math inline&#34;&gt;(ls&amp;lt;/span&gt;{access_dir}&amp;lt;span class=&#34;katex math inline&#34;&gt;{access_log}* | wc -l) &gt;/dev/null 2&gt;&amp;1 if &amp;#91;&amp;lt;/span&gt;num -eq 0 ]; then echo &#39;日志文件不存在&#39; exit 1 fi echo -e &#34;
&#34; # 验证操作系统是debian系还是centos OS=&#39;None&#39; if &amp;#91; -e &#34;/etc/os-release&#34; ]; then source /etc/os-release case &amp;lt;span class=&#34;katex math inline&#34;&gt;{ID} in &#34;debian&#34; | &#34;ubuntu&#34; | &#34;devuan&#34;) OS=&#39;Debian&#39; ;; &#34;centos&#34; | &#34;rhel fedora&#34; | &#34;rhel&#34;) OS=&#39;Centos&#39; ;; *) ;; esac fi if &amp;#91;&amp;lt;/span&gt;OS = &#39;None&#39; ]; then if command -v apt-get &gt;/dev/null 2&gt;&amp;1; then OS=&#39;Debian&#39; elif command -v yum &gt;/dev/null 2&gt;&amp;1; then OS=&#39;Centos&#39; else echo -e &#34;
不支持这个系统
&#34; echo -e &#34;已退出&#34; exit 1 fi fi # 检测ag软件有没有安装 if ag -V &gt;/dev/null 2&gt;&amp;1; then echo -e &#34;\e&amp;#91;00;32msilversearcher-ag已安装 \e&amp;#91;00m&#34; else if &amp;#91; &amp;lt;span class=&#34;katex math inline&#34;&gt;OS = &#39;Centos&#39; ]; then yum -y install the_silver_searcher &gt;/dev/null 2&gt;&amp;1 else apt-get -y install silversearcher-ag &gt;/dev/null 2&gt;&amp;1 fi fi #如果检测别的日志请手动替换偏移，例如awk的&amp;lt;/span&gt;7代表url，&amp;lt;span class=&#34;katex math inline&#34;&gt;9代表状态码，&amp;lt;/span&gt;10代表长度,本脚本是以nginx日志为基础 echo &#34;分析结果日志：&amp;lt;span class=&#34;katex math inline&#34;&gt;{outfile}&#34; echo &#34;Nginx日志目录：&amp;lt;/span&gt;{access_dir}&#34; echo &#34;Nginx文件名：&amp;lt;span class=&#34;katex math inline&#34;&gt;{access_log}&#34; echo -e &#34;
&#34; echo -e &#34;\e&amp;#91;00;31m&amp;#91;+]TOP 20 IP 地址\e&amp;#91;00m&#34; ag -a -o --nofilename &#39;\d+\.\d+\.\d+\.\d+&#39;&amp;lt;/span&gt;{access_dir}&amp;lt;span class=&#34;katex math inline&#34;&gt;{access_log}* | sort | uniq -c | sort -nr | head -n 20 | tee -a&amp;lt;/span&gt;{outfile}/top20.log echo -e &#34;
