&#34; ###################################################################### #!/bin/bash echo &#34;##########################################################################&#34; echo &#34;# nginx日志分析小工具,author:william,https://github.com/xiucaiwu #&#34; echo &#34;# 本工具暂时不支持跨天日志分析,Nginx日志格式为默认格式 #&#34; echo &#34;# 请输入要分析的时段(为空则分析全部日志): #&#34; echo &#34;# 分析今天3点10分到5点的数据:03:10-05:00 &#34;-&#34;前后没有空格 #&#34; echo &#34;# 分析2018年8月20号3点到5点的数据:2018-08-20 03:00-05:00 #&#34; echo &#34;##########################################################################&#34; # 默认存放切割后的Nginx日志目录 default_parse_ngx_dir_path=&#39;/opt/log/nginx&#39; # 生成的切割后的Nginx日志路径 parse_ngx_path=&#34;&#34; # 默认Nginx日志路径 #default_ngx_path=&#34;/usr/local/nginx/logs/host.access.145.`date &#34;+%Y%m%d&#34;`.log&#34; default_ngx_path=&#34;/root/wwwlog/access.log&#34; # 记录用户手动输入Nginx日志路径的字符串长度 ngx_path_len=0 # 记录用户手动输入切割后的Nginx日志目录字符串长度 ngx_dir_path_len=0 # 一个空数组 array=() # 一个字符串分割另一个字符串 function str_split(){ # 分割字符串 delimiter=&amp;lt;span class=&#34;katex math inline&#34;&gt;1 # 目标字符串 string=&amp;lt;/span&gt;2 # 注意后面有个空格 array=(&amp;lt;span class=&#34;katex math inline&#34;&gt;{string//&amp;lt;/span&gt;delimiter/ }) # return 只能返回int型数值 #	return &amp;lt;span class=&#34;katex math inline&#34;&gt;arr } read -p &#34;请输入nginx日志文件路径:&#34; ngx_path ngx_path_len=`echo&amp;lt;/span&gt;ngx_path | wc -L` if &amp;#91; `echo &amp;lt;span class=&#34;katex math inline&#34;&gt;ngx_path | wc -L` == 0 ];then ngx_path=&amp;lt;/span&gt;default_ngx_path fi if &amp;#91; ! -f &amp;lt;span class=&#34;katex math inline&#34;&gt;ngx_path ];then echo &#34;日志不存在&#34; #	exit fi read -p &#34;请输入存放分析后的nginx日志文件夹路径,默认为/opt/log/nginx:&#34; ngx_parse_dir_path if &amp;#91; `echo&amp;lt;/span&gt;ngx_dir_path | wc -L` == 0 ];then ngx_parse_dir_path=&amp;lt;span class=&#34;katex math inline&#34;&gt;default_parse_ngx_dir_path fi if &amp;#91; ! -d&amp;lt;/span&gt;ngx_parse_dir_path ];then echo &amp;lt;span class=&#34;katex math inline&#34;&gt;ngx