&gt; &gt; 执行结果： &gt; &gt;![image-20200819175320871](https://tva1.sinaimg.cn/large/007S8ZIlly1ghw9qofz2fj30uu0o6mys.jpg) ### 简单封装版 {#toc_6} &gt; ### SseEmitter {#toc_7} &gt; &gt; SseEmitter是SpringMVC(4.2+)提供的一种技术,它是基于**Http协议**的，相比WebSocket，它更轻量，但是它只能从服务端向客户端**单向**发送信息。在SpringBoot中我们无需引用其他jar就可以使用 &gt; &gt; * 创建`AtomicInteger`用于记录连接数 &gt; * 创建`ConcurrentHashMap`用于存放连接信息 &gt; * 建立连接：创建并返回一个带有超时时间的`SseEmitter`给前端。超时间设为0表示永不过期 &gt; * 设置连接结束的回调方法`completionCallBack` &gt; * 设置连接超时的回调方法`timeoutCallBack` &gt; * 设置连接异常的回调方法`errorCallBack` &gt; * 创建推送信息的方法`SseEmitter.send()` &gt; * 创建移除连接的方法 &gt; &gt; 服务器端 &gt; &gt; ``` `import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; @RestController @RequestMapping(&#34;/sse&#34;) @CrossOrigin public class SseEmitterController { /** * 用于创建连接 */ @GetMapping(&#34;/connect/{userId}&#34;) public SseEmitter connect(@PathVariable String userId) { return SseEmitterServer.connect(userId); } @GetMapping(&#34;/push/{message}&#34;) public ResponseEntity&amp;lt;String&amp;gt; push(@PathVariable(name = &#34;message&#34;) String message) { SseEmitterServer.batchSendMessage(message); return ResponseEntity.ok(&#34;WebSocket 推送消息给所有人&#34;); } } ` ` import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.http.MediaType; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
import java.io.IOException; import java.util.ArrayList; import java.util.List; import java.util.Map; import java.util.concurrent.ConcurrentHashMap; import java.util.concurrent.atomic.AtomicInteger; import java.util.function.Consumer;
public class SseEmitterServer {
private static final Logger logger = LoggerFactory.getLogger(SseEmitterServer.class); /** * 当前连接数 */ private static AtomicInteger count = new AtomicInteger(0); /** * 使用map对象，便于根据userId来获取对应的SseEmitter，或者放redis里面 */ private static Map&amp;lt;String, SseEmitter&amp;gt; sseEmitterMap = new ConcurrentHashMap&amp;lt;&amp;gt;(); /** * 创建用户连接并返回 SseEmitter * * @param userId 用户ID * @return SseEmitter */ public static SseEmitter connect(String userId) { if (sseEmitterMap.containsKey(userId)){//在连接的时候，如果存在就移除原来连接，生产新的连接 removeUser(userId); } // 设置超时时间，0表示不过期。默认30秒，超过时间未完成会抛出异常：AsyncRequestTimeoutException SseEmitter sseEmitter = new SseEmitter(0L); // 注册回调 sseEmitter.onCompletion(completionCallBack(userId)); sseEmitter.onError(errorCallBack(userId)); sseEmitter.onTimeout(timeoutCallBack(userId)); sseEmitterMap.put(userId, sseEmitter); // 数量+1 count.getAndIncrement(); logger.info(&quot;创建新的sse连接，当前用户：{}&quot;, userId); return sseEmitter; } /** * 给指定用户发送信息 */ public static void sendMessage(String userId, String message) { if (sseEmitterMap.containsKey(userId)) { try { // sseEmitterMap.get(userId).send(message, MediaType.APPLICATION_JSON); sseEmitterMap.get(userId).send(message); } catch (IOException e) { logger.error(&quot;用户[{}]推送异常:{}&quot;, userId, e.getMessage()); removeUser(userId); } } } /** * 群发消息 */ public static void batchSendMessage(String wsInfo, List&amp;lt;String&amp;gt; ids) { ids.forEach(userId -&amp;gt; sendMessage(wsInfo, userId)); } /** * 群发所有人 */ public static void batchSendMessage(String wsInfo) { sseEmitterMap.forEach((k, v) -&amp;gt; { try { v.send(wsInfo, MediaType.APPLICATION_JSON); } catch (IOException e) { logger.error(&quot;用户[{}]推送异常:{}&quot;, k, e.getMessage()); removeUser(k); } }); } /** * 移除用户连接 */ public static void removeUser(String userId) { sseEmitterMap.remove(userId); // 数量-1 count.getAndDecrement(); logger.info(&quot;移除用户：{}&quot;, userId); } /** * 获取当前连接信息 */ public static List&amp;lt;String&amp;gt; getIds() { return new ArrayList&amp;lt;&amp;gt;(sseEmitterMap.keySet()); } /** * 获取当前连接数量 */ public static int getUserCount() { return count.intValue(); } private static Runnable completionCallBack(String userId) { return () -&amp;gt; { logger.info(&quot;结束连接：{}&quot;, userId); removeUser(userId); }; } private static Runnable timeoutCallBack(String userId) { return () -&amp;gt; { logger.info(&quot;连接超时：{}&quot;, userId); removeUser(userId); }; } private static Consumer&amp;lt;Throwable&amp;gt; errorCallBack(String userId) { return throwable -&amp;gt; { logger.info(&quot;连接异常：{}&quot;, userId); removeUser(userId); }; } }
`
&gt; &gt; 前端二： &gt; &gt; ``` `&amp;lt;!DOCTYPE html&amp;gt; &amp;lt;html lang=&#34;en&#34;&amp;gt; &amp;lt;head&amp;gt; &amp;lt;meta charset=&#34;UTF-8&#34;&amp;gt; &amp;lt;title&amp;gt;SseEmitter&amp;lt;/title&amp;gt; &amp;lt;/head&amp;gt; &amp;lt;body&amp;gt; &amp;lt;button onclick=&#34;closeSse()&#34;&amp;gt;关闭连接&amp;lt;/button&amp;gt; &amp;lt;div id=&#34;message&#34;&amp;gt;&amp;lt;/div&amp;gt; &amp;lt;/body&amp;gt; &amp;lt;script&amp;gt; let source = null; // 用时间戳模拟登录用户 const userId = new Date().getTime(); if (!!window.EventSource) { // 建立连接 source = new EventSource(&amp;#39;http://127.0.0.1:8844/sse/connect/&amp;#39; + userId); /** * 连接一旦建立，就会触发open事件 * 另一种写法：source.onopen = function (event) {} */ source.addEventListener(&amp;#39;open&amp;#39;, function (e) { setMessageInnerHTML(&#34;建立连接。。。&#34;); }, false); /** * 客户端收到服务器发来的数据 * 另一种写法：source.onmessage = function (event) {} */ source.addEventListener(&amp;#39;message&amp;#39;, function (e) { setMessageInnerHTML(e.data); }); /** * 如果发生通信错误（比如连接中断），就会触发error事件 * 或者： * 另一种写法：source.onerror = function (event) {} */ source.addEventListener(&amp;#39;error&amp;#39;, function (e) { if (e.readyState === EventSource.CLOSED) { setMessageInnerHTML(&#34;连接关闭&#34;); } else { console.log(e); } }, false); } else { setMessageInnerHTML(&#34;你的浏览器不支持SSE&#34;); } // 监听窗口关闭事件，主动去关闭sse连接，如果服务端设置永不过期，浏览器关闭后手动清理服务端数据 window.onbeforeunload = function () { closeSse(); }; // 关闭Sse连接 function closeSse() { source.close(); const httpRequest = new XMLHttpRequest(); httpRequest.open(&amp;#39;GET&amp;#39;, &amp;#39;http://127.0.0.1:8844/sse/close/&amp;#39; + userId, true); httpRequest.send(); console.log(&#34;close&#34;); } // 将消息显示在网页上 function setMessageInnerHTML(innerHTML) { document.getElementById(&amp;#39;message&amp;#39;).innerHTML += innerHTML + &amp;#39;&amp;lt;br/&amp;gt;&amp;#39;; } &amp;lt;/script&amp;gt; &amp;lt;/html&amp;gt; ` Demo实现二(Node) Node 服务器实例（如果自己想实现SSE服务端参考这个，主要是实现协议）
SSE要求服务器与浏览器保持连接，对于不同的服务器软件来说，所消耗的资源也不一样的。Node则是所有连接都使用同一个线程，因此消耗的资源会小很多，但是这个要求每个连接不能包含很耗时的操作（比如磁盘IO的读写）
