&gt; &gt; 前端代码 &gt; &gt; ``` `&amp;lt;!DOCTYPE html&amp;gt; &amp;lt;html&amp;gt; &amp;lt;head&amp;gt; &amp;lt;meta charset=&#34;utf-8&#34;&amp;gt; &amp;lt;meta name=&#34;viewport&#34; content=&#34;width=device-width&#34;&amp;gt; &amp;lt;title&amp;gt;JS Bin&amp;lt;/title&amp;gt; &amp;lt;/head&amp;gt; &amp;lt;body&amp;gt; &amp;lt;div id=&#34;example&#34;&amp;gt;&amp;lt;/div&amp;gt; &amp;lt;script&amp;gt; var source = new EventSource(&amp;#39;http://127.0.0.1:8844/stream&amp;#39;); var div = document.getElementById(&amp;#39;example&amp;#39;); source.onopen = function (event) { div.innerHTML += &amp;#39;&amp;lt;p&amp;gt;Connection open ...&amp;lt;/p&amp;gt;&amp;#39;; }; source.onerror = function (event) { div.innerHTML += &amp;#39;&amp;lt;p&amp;gt;Connection close.&amp;lt;/p&amp;gt;&amp;#39;; }; source.addEventListener(&amp;#39;connecttime&amp;#39;, function (event) { div.innerHTML += (&amp;#39;&amp;lt;p&amp;gt;Start time: &amp;#39; + event.data + &amp;#39;&amp;lt;/p&amp;gt;&amp;#39;); }, false); source.onmessage = function (event) { div.innerHTML += (&amp;#39;&amp;lt;p&amp;gt;Ping: &amp;#39; + event.data + &amp;#39;&amp;lt;/p&amp;gt;&amp;#39;); }; &amp;lt;/script&amp;gt; &amp;lt;/body&amp;gt; &amp;lt;/html&amp;gt; ` Demo实现三(PHP) Php实现SSE
