`express是一个基于node.js平台的，快速，开放，极简的web开发框架。 一、安装 express npm install express --save 二、简单使用 express //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); //匹配GET请求路径设置回调函数 app.get(&#39;/hello&#39;, function (req, res) { res.end(&#39;hello&#39;); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); 通过访问 localhost:8888/hello 我们就可以看到内容输出了。 当然 express 还支持其他的一些请求方法，比如 app.post()，app.put()，app.delete()，app.head() 等。 //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); //匹配POST请求 app.post(&#39;/hello&#39;, function (req, res) { res.end(&#39;post hello&#39;); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); 如果我们想要匹配所有的请求路径，可以使用通配符 * 号。 //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); app.get(&#39;/hello&#39;, function (req, res) { res.end(&#39;hello&#39;); }); //*号匹配所有路径 app.get(&#39;*&#39;, function (req, res) { res.end(&#39;not found&#39;); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); express 还提供了 all() 方法，可以匹配所有请求方法。 //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); //匹配所有请求方法 app.all(&#39;/hello&#39;, function (req, res) { res.end(&#39;all hello&#39;); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); 三、express 中间件的概念 express中间件就是处理http请求的函数，用来完成一些特定的操作，比如登陆检查，权限控制等等。 1、一个中间件处理完请求和响应，可以把数据传递给下一个中间件。 2、在回调函数中使用 next()，就可以让请求继续向下传递。 3、通过不同路径，分别执行不同的中间件。 我们可以使用 use() ，在路由数组中添加一个中间件。注意我们设置的路由路径最终会存放在一个数组里，由上到下的把路径加入这个数组中。 //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); //如果没有设置路径，则会匹配全部 app.use(function (req, res, next) { console.log(&#39;匹配全部路径&#39;); //注意这里如果不调用next()，则请求并不会向下传递。 next(); }); app.use(&#39;/hello&#39;, function (req, res, next) { console.log(&#39;use hello&#39;); next(); }); app.get(&#39;/hello&#39;, function (req, res, next) { console.log(&#39;get hello&#39;); next(); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); next() 函数可以传入一个参数，表示错误信息，默认将执行错误中间件。 //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); app.get(&#39;/hello&#39;, function (req, res, next) { console.log(&#39;get hello&#39;); next(&#39;error!!!&#39;); }); //注意错误处理中间件的参数是4个 app.use(function (err, req, res, next) { console.log(err); res.end(err); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); 四、express中的request对象 在express中对原生的req请求对象进行了扩展，添加了一些属性和方法。 //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); app.get(&#39;/hello&#39;, function (req, res, next) { //主机名 res.write(&#39;req.hostname : &#39; + req.hostname + &#39;
&#39;); //请求URL的路径 res.write(&#39;req.path : &#39; + req.path + &#39;
