&#39;); //请求的远程IP地址 res.write(&#39;req.ip : &#39; + req.ip + &#39;
&#39;); //请求方法 res.write(&#39;req.method : &#39; + req.method + &#39;
&#39;); res.end(); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); 通过 req.params 获取路径里的参数 //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); app.get(&#39;/list/:key/:page/:size&#39;, function (req, res, next) { //注意，设置了多少参数，地址就需要传入多少参数 res.end(JSON.stringify(req.params)); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); 五、express中的response对象 express中也对原生的res对象进行了扩展，添加了一些属性和方法。 const path = require(&#39;path&#39;); //引入express const express = require(&#39;express&#39;); //创建一个应用 let app = express(); app.get(&#39;/send/str&#39;, function (req, res, next) { //send方法会自动判断数据类型，并进行相应的head信息设置 //如果参数是字符串，则Content-Type为 text/html res.send(&#39;hello, world&#39;); }); app.get(&#39;/send/arr&#39;, function (req, res, next) { //如果参数是一个数组，则返回json res.send(&amp;#91;1, 2, 3]); }); app.get(&#39;/send/obj&#39;, function (req, res, next) { //如果参数是一个对象，则返回json res.send({name: &#39;xiaoxu&#39;, age: 24}); }); app.get(&#39;/send/number&#39;, function (req, res, next) { //如果是一个数字，则返回相应状态码短语 res.send(404); }); app.get(&#39;/download&#39;, function (req, res, next) { //提示下载文件 res.download(&#39;./1.txt&#39;); }); app.get(&#39;/json&#39;, function (req, res, next) { //响应json对象 res.json({name: &#39;xiaoxu&#39;}); }); app.get(&#39;/jsonp&#39;, function (req, res, next) { //客户端请求时，需要带上callback=test res.jsonp(&#39;hello&#39;); }); app.get(&#39;/redirect&#39;, function (req, res, next) { //重定向到一个地址 res.redirect(&#39;http://www.baidu.com&#39;); }); app.get(&#39;/sendfile&#39;, function (req, res, next) { //发送一个文件 res.sendFile(path.resolve(&#39;./1.txt&#39;)); }); app.get(&#39;/sendstatus&#39;, function (req, res, next) { //发送一个状态码 res.sendStatus(302); }); //监听端口 app.listen(8888, function () { console.log(&#39;port : 8888&#39;); }); 六、ejs模板的使用 支持express的模板有很多种，这里我们使用ejs作为模板引擎。 安装ejs: npm install ejs 使用ejs模板 const path = require(&#39;path&#39;); const express = require(&#39;express&#39;); //创建一个应用 let app = express(); //设置模板引擎 app.set(&#39;view engine&#39;, &#39;ejs&#39;); //设置模板目录 app.set(&#39;views&#39;, path.join(__dirname, &#39;views&#39;)); //监听 app.listen(8888); 如果我们希望，ejs能够渲染html页面，可以使用如下 const path = require(&#39;path&#39;); const express = require(&#39;express&#39;); let app = express(); //设置视图引擎为html引擎 app.set(&#39;view engine&#39;, &#39;html&#39;); //设置视图的路径 app.set(&#39;views&#39;, path.join(__dirname, &#39;views&#39;)); //配置html引擎 app.engine(&#39;html&#39;, require(&#39;ejs&#39;).__express); app.listen(8888); 渲染视图，输出内容。 const path = require(&#39;path&#39;); const express = require(&#39;express&#39;); let app = express(); app.set(&#39;view engine&#39;, &#39;html&#39;); app.set(&#39;views&#39;, path.join(__dirname, &#39;views&#39;)); app.engine(&#39;html&#39;, require(&#39;ejs&#39;).__express); app.get(&#39;/hello&#39;, function (req, res, next) { //参数一表示模板的名称，会在当前项目目录下的views目录查找 //参数二表示传入模板中的数据 res.render(&#39;hello&#39;, { name: &#39;xiaoxu&#39;, age: 24 }); }); app.listen(8888); hello.html的代码： &amp;lt;!doctype html&gt; &amp;lt;html lang=&#34;zh-CN&#34;&gt; &amp;lt;head&gt; &amp;lt;meta charset=&#34;UTF-8&#34;&gt; &amp;lt;title&gt;Document&amp;lt;/title&gt; &amp;lt;/head&gt; &amp;lt;body&gt; &amp;lt;%= name %&gt; &amp;lt;%= age %&gt; &amp;lt;/body&gt; &amp;lt;/html&gt; 七、静态文件服务器 有些时候我们需要在页面上加载css，js，img等静态资源，指定存放静态资源的目录，浏览器发出非html文件请求时，服务器会到这个目录下找对应的资源。 const path = require(&#39;path&#39;); const express = require(&#39;express&#39;); let app = express(); app.set(&#39;view engine&#39;, &#39;html&#39;); app.set(&#39;views&#39;, path.join(__dirname, &#39;views&#39;)); app.engine(&#39;html&#39;, require(&#39;ejs&#39;).__express); //注意express.static这个中间件是express内置的 app.use(express.static(path.join(__dirname, &#39;public&#39;))); app.get(&#39;/hello&#39;, function (req, res, next) { //参数一表示模板的名称，会在当前项目目录下的views目录查找 //参数二表示传入模板中的数据 res.render(&#39;hello&#39;, { name: &#39;xiaoxu&#39;, age: 24 }); }); app.listen(8888); 八、使用body-parser中间件解析post过来的数据 安装body-parser npm install body-parser 使用body-parser const path = require(&#39;path&#39;); const express = require(&#39;express&#39;); const bodyParser = require(&#39;body-parser&#39;); let app = express(); app.set(&#39;view engine&#39;, &#39;html&#39;); app.set(&#39;views&#39;, path.join(__dirname, &#39;views&#39;)); app.engine(&#39;html&#39;, require(&#39;ejs&#39;).__express); //解析 application/json app.use(bodyParser.json()); //解析 application/x-www-form-urlencoded app.use(bodyParser.urlencoded({extended:false})); app.post(&#39;/form&#39;, function (req, res) { console.log(req.body); }); app.listen(8888);`

