### 配置Shiro {#toc_2} &gt; 创建一个ShiroConfig进行配置 &gt; &gt; ``` `import org.apache.shiro.mgt.SecurityManager; import org.apache.shiro.spring.security.interceptor.AuthorizationAttributeSourceAdvisor; import org.apache.shiro.spring.web.ShiroFilterFactoryBean; import org.apache.shiro.web.mgt.DefaultWebSecurityManager; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.aop.framework.autoproxy.DefaultAdvisorAutoProxyCreator; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import java.util.LinkedHashMap; import java.util.Map; @Configuration public class ShiroConfig { private Logger logger = LoggerFactory.getLogger(ShiroConfig.class); @Bean public ShiroFilterFactoryBean shiroFilter(SecurityManager securityManager){ logger.info(&#34;ShiroConfig initalized&#34;); // 初始化ShiroFilterFactoryBean ShiroFilterFactoryBean shiroFilterFactoryBean = new ShiroFilterFactoryBean(); //必须设置SecurityManager shiroFilterFactoryBean.setSecurityManager(securityManager); //拦截器 Map&amp;lt;String,String&amp;gt; filterChainDefinitionMap = new LinkedHashMap&amp;lt;&amp;gt;(); //退出 filterChainDefinitionMap.put(&#34;/logout&#34;,&#34;logout&#34;); // 过滤链定义，从上向下顺序执行，一般将/** 放到最下面 filterChainDefinitionMap.put(&#34;/admin/**&#34;,&#34;authc&#34;); filterChainDefinitionMap.put(&#34;/**&#34;,&#34;anon&#34;); // 如果不设置默认会自动寻找Web工程更目录下的“login.jsp”页面 shiroFilterFactoryBean.setLoginUrl(&#34;/login&#34;); // 登录成功后要跳转的连接 shiroFilterFactoryBean.setSuccessUrl(&#34;/success&#34;); // 未授权界面 shiroFilterFactoryBean.setUnauthorizedUrl(&#34;/403&#34;); shiroFilterFactoryBean.setFilterChainDefinitionMap(filterChainDefinitionMap); return shiroFilterFactoryBean; } @Bean public SecurityManager securityManager(){ System.out.println(&#34;securityManager is run&#34;); SecurityManager securityManager = new DefaultWebSecurityManager(); ((DefaultWebSecurityManager) securityManager).setRealm(new MyRealm()); return securityManager; } @Bean public AuthorizationAttributeSourceAdvisor authorizationAttributeSourceAdvisor(SecurityManager securityManager){ System.out.println(&#34;authorizationAttributeSourceAdvisor is run&#34;); AuthorizationAttributeSourceAdvisor authorizationAttributeSourceAdvisor = new AuthorizationAttributeSourceAdvisor(); authorizationAttributeSourceAdvisor.setSecurityManager(securityManager); return authorizationAttributeSourceAdvisor; } @Bean public DefaultAdvisorAutoProxyCreator defaultAdvisorAutoProxyCreator(){ System.out.println(&#34;defaultAdvisorAutoProxyCreator is run&#34;); DefaultAdvisorAutoProxyCreator defaultAdvisorAutoProxyCreator = new DefaultAdvisorAutoProxyCreator(); defaultAdvisorAutoProxyCreator.setProxyTargetClass(true); return defaultAdvisorAutoProxyCreator; } } ` `import org.apache.shiro.authc.*; import org.apache.shiro.authz.AuthorizationInfo; import org.apache.shiro.authz.SimpleAuthorizationInfo; import org.apache.shiro.realm.AuthorizingRealm; import org.apache.shiro.subject.PrincipalCollection; import org.slf4j.Logger; import org.slf4j.LoggerFactory;
import javax.annotation.PostConstruct;
public class MyRealm extends AuthorizingRealm { private Logger logger = LoggerFactory.getLogger(MyRealm.class); @Override protected AuthorizationInfo doGetAuthorizationInfo(PrincipalCollection principalCollection) {//权限认证，即登录过后，每个身份不一定，对应的所能看的页面也不一样。 //认证 并且获取角色及权限 logger.info(&rdquo;#################执行Shiro权限认证#######################&rdquo;); String userName = (String) principalCollection.getPrimaryPrincipal(); if (userName.equals(&ldquo;admin&rdquo;)){ SimpleAuthorizationInfo info = new SimpleAuthorizationInfo(); info.addStringPermission(&ldquo;admin:&rdquo;); info.addStringPermission(&ldquo;index:&rdquo;); info.addRole(&ldquo;admin&rdquo;); return info; }else if (userName != null&amp;&amp; userName.length()&gt;0){ SimpleAuthorizationInfo info = new SimpleAuthorizationInfo(); info.addStringPermission(&ldquo;index:*&rdquo;); info.addRole(&ldquo;index&rdquo;); return info; }else{ return null; }
} @Override protected AuthenticationInfo doGetAuthenticationInfo(AuthenticationToken authenticationToken) throws AuthenticationException { logger.info(&quot;#################执行doGetAuthenticationInfo认证#######################&quot;); UsernamePasswordToken token = (UsernamePasswordToken) authenticationToken; logger.info(&quot;user==&amp;gt;&quot;+token.getUsername()); if (&quot;admin&quot;.equals(token.getUsername())){ return new SimpleAuthenticationInfo(token.getUsername(),&quot;123456&quot;,token.getUsername()); }else if (token.getUsername() != null&amp;&amp; token.getUsername().length()&amp;gt;0){ return new SimpleAuthenticationInfo(token.getUsername(),&quot;111111&quot;,token.getUsername()); }else{ return null; } } @PostConstruct public void initCredentialsMatcher(){ setCredentialsMatcher(new CredentialsMatcher()); } } `
&gt; &gt; ``` `import org.apache.shiro.authc.AuthenticationInfo; import org.apache.shiro.authc.AuthenticationToken; import org.apache.shiro.authc.UsernamePasswordToken; import org.apache.shiro.authc.credential.SimpleCredentialsMatcher; import org.slf4j.Logger; import org.slf4j.LoggerFactory; public class CredentialsMatcher extends SimpleCredentialsMatcher { private Logger logger = LoggerFactory.getLogger(CredentialsMatcher.class); @Override public boolean doCredentialsMatch(AuthenticationToken token, AuthenticationInfo info) { System.out.println(&#34;doCredentialsMatch is run!!!&#34;); UsernamePasswordToken authToken = (UsernamePasswordToken) token; if (&#34;admin&#34;.equals(authToken.getUsername())){ return getCredentials(info).equals(&#34;123456&#34;); }else if( authToken.getUsername()!=null &amp;&amp; authToken.getUsername().length()&amp;gt;0){ return getCredentials(info).equals(&#34;111111&#34;); }else { return false; } } } ` 通过这些我们配置完成Shiro
