@Controller @RequestMapping(&rdquo;&quot;) public class IndexController {
@GetMapping @ResponseBody public String defaultMethod(){ return &quot;ok&quot;; } @GetMapping(&quot;index&quot;) @ResponseBody public String index(){ return &quot;index is run ! please continue&quot;; } @GetMapping(&quot;login&quot;) public String login(){ return &quot;login&quot;; } @GetMapping(&quot;admin&quot;) @ResponseBody public String adminindex(){ System.out.println(&quot;admin IS run !&quot;); Subject subject = SecurityUtils.getSubject(); subject.checkPermission(&quot;admin:*&quot;); boolean has = subject.isPermitted(&quot;admin:*&quot;); System.out.println(&quot;是否有权限：&quot;+has); return &quot;admin index is in&quot;; } @GetMapping(&quot;loginrequest&quot;) @ResponseBody public String loginRequest(String userName,String password){ System.out.println(&quot;loginrequest IS run !&quot;); if (userName.equals(&quot;admin&quot;)&amp;&amp;password.equals(&quot;123456&quot;)){ UsernamePasswordToken token =new UsernamePasswordToken(); token.setUsername(userName); token.setPassword(password.toCharArray()); System.out.println(&quot;登录成功!!!&quot;); Subject subject = SecurityUtils.getSubject(); subject.login(token); }else if (userName!=null&amp;&amp;userName.length()&amp;gt;0){ UsernamePasswordToken token =new UsernamePasswordToken(); token.setUsername(userName); token.setPassword(password.toCharArray()); Subject subject = SecurityUtils.getSubject(); subject.login(token); }else{ System.out.println(&quot;登录失败!!!&quot;); } return &quot; index is in&quot;; } } `
