import it.sauronsoftware.base64.Base64;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.Security;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import org.bouncycastle.jce.provider.BouncyCastleProvider;
/**
java实现AES256加密解密 依赖说明： bcprov-jdk15-133.jar：PKCS7Padding javabase64-1.3.1.jar：base64 local_policy.jar 和 US_export_policy.jar需添加到%JAVE_HOME%\jre\lib\security中（lib中版本适合jdk1.7）
*/ public class AES256 {
public static byte[] encrypt(String content, String password) {
try {
//”AES”：请求的密钥算法的标准名称
KeyGenerator kgen = KeyGenerator.getInstance(“AES”);
//256：密钥生成参数；securerandom：密钥生成器的随机源
SecureRandom securerandom = new SecureRandom(tohash256Deal(password));
kgen.init(256, securerandom);
//生成秘密（对称）密钥
SecretKey secretKey = kgen.generateKey();
//返回基本编码格式的密钥
byte[] enCodeFormat = secretKey.getEncoded();
//根据给定的字节数组构造一个密钥。enCodeFormat：密钥内容；”AES”：与给定的密钥内容相关联的密钥算法的名称
SecretKeySpec key = new SecretKeySpec(enCodeFormat, “AES”);
//将提供程序添加到下一个可用位置
Security.addProvider(new BouncyCastleProvider());
//创建一个实现指定转换的 Cipher对象，该转换由指定的提供程序提供。
//”AES/ECB/PKCS7Padding”：转换的名称；”BC”：提供程序的名称
Cipher cipher = Cipher.getInstance(“AES/ECB/PKCS7Padding”, “BC”);
cipher.init(Cipher.ENCRYPT_MODE, key);
byte[] byteContent = content.getBytes(“utf-8”);
byte[] cryptograph = cipher.doFinal(byteContent);
return Base64.encode(cryptograph);
} catch (Exception e) {
e.printStackTrace();
}
return null;
}
public static String decrypt(byte[] cryptograph, String password) {
try {
KeyGenerator kgen = KeyGenerator.getInstance(“AES”);
SecureRandom securerandom = new SecureRandom(tohash256Deal(password));
kgen.init(256, securerandom);
SecretKey secretKey = kgen.generateKey();
byte[] enCodeFormat = secretKey.getEncoded();
SecretKeySpec key = new SecretKeySpec(enCodeFormat, “AES”);
Security.addProvider(new BouncyCastleProvider());
Cipher cipher = Cipher.getInstance(“AES/ECB/PKCS7Padding”, “BC”);
cipher.init(Cipher.DECRYPT_MODE, key);
byte[] content = cipher.doFinal(Base64.decode(cryptograph));
return new String(content);
} catch (Exception e) {
e.printStackTrace();
}
return null;
}
private static String parseByte2HexStr(byte buf[]) {
StringBuffer sb = new StringBuffer();
for (int i = 0; i &lt; buf.length; i++) {
String hex = Integer.toHexString(buf[i] &amp; 0xFF);
if (hex.length() == 1) {
hex = ‘0’ + hex;
}
sb.append(hex.toUpperCase());
}
return sb.toString();
}
/private static byte[] parseHexStr2Byte(String hexStr) {
if (hexStr.length() &lt; 1)
return null;
byte[] result = new byte[hexStr.length()/2];
for (int i = 0;i&lt; hexStr.length()/2; i++) {
int high = Integer.parseInt(hexStr.substring(i*2, i*2+1), 16);
int low = Integer.parseInt(hexStr.substring(i*2+1, i*2+2), 16);
result[i] = (byte) (high * 16 + low);
}
return result;
}/
private static byte[] tohash256Deal(String datastr) {
try {
MessageDigest digester=MessageDigest.getInstance(“SHA-256”);
digester.update(datastr.getBytes());
byte[] hex=digester.digest();
return hex;
} catch (NoSuchAlgorithmException e) {
throw new RuntimeException(e.getMessage());
}
}
public static void main(String[] args) {
String content = “0f607264fc6318a92b9e13c65db7cd3c”;
String password = “zsyy”;
System.out.println(“明文：” + content);
System.out.println(“key：” + password);
byte[] encryptResult = AES256.encrypt(content, password);
System.out.println(“密文：” + AES256.parseByte2HexStr(encryptResult));
String decryptResult = AES256.decrypt(encryptResult, password);
System.out.println(“解密：” + decryptResult);
}
}

Retortfit2
Retrofit是由Square公司出品的针对于Android和Java的类型安全的Http客户端，网络服务基于OkHttp 。 个人觉得更为准确的说法是，Retrofit是OkHttp的一个包装工具类，可以更加方便的调用Restful API。
Retrofit2 默认提供的Converter
Gson: com.squareup.retrofit2:converter-gson
Jackson: com.squareup.retrofit2:converter-jackson
Moshi: com.squareup.retrofit2:converter-moshi
Protobuf: com.squareup.retrofit2:converter-protobuf
Wire: com.squareup.retrofit2:converter-wire
Simple XML: com.squareup.retrofit2:converter-simplexml
Scalars (primitives, boxed, and String): com.squareup.retrofit2:converter-scalars
下面就来讲解如何扩展Converter
首先创建FastJsonConverterFactory 类，并继承Converter.Factory，重写其中的responseBodyConverter方法与requestBodyConverter方法。
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;
import okhttp3.RequestBody;
import okhttp3.ResponseBody;
import retrofit2.Converter;
import retrofit2.Retrofit;
public class FastJsonConverterFactory extends Converter.Factory{
public static FastJsonConverterFactory create() {
return new FastJsonConverterFactory();
}
/**
需要重写父类中responseBodyConverter，该方法用来转换服务器返回数据
*/
@Override
public Converter&lt;ResponseBody, ?&gt; responseBodyConverter(Type type, Annotation[] annotations, Retrofit retrofit) {
return new FastJsonResponseBodyConverter&lt;&gt;(type);
} /**
需要重写父类中responseBodyConverter，该方法用来转换发送给服务器的数据
*/
@Override
public Converter&lt;?, RequestBody&gt; requestBodyConverter(Type type, Annotation[] parameterAnnotations, Annotation[] methodAnnotations, Retrofit retrofit) {
return new FastJsonRequestBodyConverter&lt;&gt;();
} }
创建FastJsonResponseBodyConverter 类
import okhttp3.ResponseBody;
import okio.BufferedSource;
import okio.Okio;
import retrofit2.Converter;
public class FastJsonResponseBodyConverter implements Converter&lt;ResponseBody, T&gt; {
private final Type type;
public FastJsonResponseBodyConverter(Type type) {
this.type = type;
}
/*
转换方法
*/
@Override
public T convert(ResponseBody value) throws IOException {
BufferedSource bufferedSource = Okio.buffer(value.source());
String tempStr = bufferedSource.readUtf8();
bufferedSource.close();
return JSON.parseObject(tempStr, type); }
}
创建FastJsonRequestBodyConverter
import com.alibaba.fastjson.JSON;
import java.io.IOException;
import okhttp3.MediaType;
import okhttp3.RequestBody;
import retrofit2.Converter;
public class FastJsonRequestBodyConverter implements Converter&lt;T, RequestBody&gt; {
private static final MediaType MEDIA_TYPE = MediaType.parse(“application/json; charset=UTF-8”);
@Override
public RequestBody convert(T value) throws IOException {
return RequestBody.create(MEDIA_TYPE, JSON.toJSONBytes(value));
}
}
使用方法
retrofit = new Retrofit.Builder()
.baseUrl(BASE_URL)
.client(CustomerOkHttpClient.getClient())
.addCallAdapterFactory(RxJavaCallAdapterFactory.create())
//在此处声明使用FastJsonConverter做为转换器
.addConverterFactory(FastJsonConverterFactory.create())
.build()
