an&gt; &lt;span class=&#34;line&#34;&gt;36&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;37&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;38&lt;/span&gt; &lt;/td&gt; &lt;td class=&quot;code hljs java&quot;&gt; &lt;div class=&quot;top-box hide&quot;&gt; &lt;div class=&quot;alert-info&quot;&gt; &lt;/div&gt; &lt;/div&gt; ``` package com.sherlockshi.badgedtablayoutpractise;
