private void initFragments() { mPageTitleList.add(&ldquo;Tab1&rdquo;); mPageTitleList.add(&ldquo;Tab2&rdquo;); mPageTitleList.add(&ldquo;Tab3&rdquo;);
mBadgeCountList.add(6); mBadgeCountList.add(16); mBadgeCountList.add(166);
for (int i = ; i &lt; mPageTitleList.size(); i++) { mFragmentList.add(PageFragment.getInstance(mPageTitleList.get(i))); } }
private void initView() { mTabLayout = (TabLayout) findViewById(R.id.tab_layout); mViewPager = (ViewPager) findViewById(R.id.view_pager);
mPagerAdapter = new SimpleFragmentPagerAdapter(getSupportFragmentManager(), mFragmentList, mPageTitleList); mViewPager.setAdapter(mPagerAdapter); mTabLayout.setupWithViewPager(mViewPager);
initBadgeViews(); setUpTabBadge(); } }
&lt;/td&gt; &lt;/tr&gt; &lt;/table&gt;&lt;/figure&gt; # 四、设置角标 {#四、设置角标} ## 1. 添加角标Badge {#1-添加角标Badge} 添加角标的关键代码只需要一行：&lt;figure class=&#34;highlight java&#34;&gt; &lt;table&gt; &lt;tr&gt; &lt;td class=&#34;gutter&#34;&gt; ``` &lt;span class=&#34;line&#34;&gt;1&lt;/span&gt; &lt;/td&gt; &lt;td class=&quot;code hljs css&quot;&gt; &lt;div class=&quot;top-box hide&quot;&gt; &lt;div class=&quot;alert-info&quot;&gt; &lt;/div&gt; &lt;/div&gt; ``` mBadgeViews.get(i).setTargetView(((ViewGroup) mTabLayout.getChildAt()).getChildAt(i));
&lt;/td&gt; &lt;/tr&gt; &lt;/table&gt;&lt;/figure&gt; 完整代码只需要在设置完TabLayout和ViewPager后，遍历每一个Tab，为Tab添加角标：&lt;figure class=&#34;highlight java&#34;&gt; &lt;table&gt; &lt;tr&gt; &lt;td class=&#34;gutter&#34;&gt; ``` &lt;span class=&#34;line&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;2&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;3&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;4&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;5&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;6&lt;/span&gt; &lt;/td&gt; &lt;td class=&quot;code hljs cs&quot;&gt; &lt;div class=&quot;top-box hide&quot;&gt; &lt;div class=&quot;alert-info&quot;&gt; &lt;/div&gt; &lt;/div&gt; ``` private void setUpTabBadge() { for (int i = ; i &lt; mFragmentList.size(); i++) { mBadgeViews.get(i).setTargetView(((ViewGroup) mTabLayout.getChildAt()).getChildAt(i)); mBadgeViews.get(i).setText(formatBadgeNumber(mBadgeCountList.get(i))); } }
&lt;/td&gt; &lt;/tr&gt; &lt;/table&gt;&lt;/figure&gt; ## 2. 更新角标 {#2-更新角标} 在需要更新角标的地方，只要调用以下方法就可实现：&lt;figure class=&#34;highlight java&#34;&gt; &lt;table&gt; &lt;tr&gt; &lt;td class=&#34;gutter&#34;&gt; ``` &lt;span class=&#34;line&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;2&lt;/span&gt; &lt;/td&gt; &lt;td class=&quot;code hljs bash&quot;&gt; &lt;div class=&quot;top-box hide&quot;&gt; &lt;div class=&quot;alert-info&quot;&gt; &lt;/div&gt; &lt;/div&gt; ``` mBadgeCountList.set(1, count++); setUpTabBadge();
&lt;/td&gt; &lt;/tr&gt; &lt;/table&gt;&lt;/figure&gt; 以上，就可以轻松地为TabLayout添加角标，并处理角标的更新了。 # 五、问题 {#五、问题} ## 1. 重复选中的状态 {#1-重复选中的状态} 但是如果需要更新角标，那么在`更新角标后`，再点击另一个Tab，会出现`上一个Tab`和`当前Tab`都是选中状态（如下图的Tab1和Tab2）： ![](http://7xlpfl.com1.z0.glb.clouddn.com/sherlockshi/2016-11-03-Snip20161103_6.png) ## 2. 角标位置不可控 {#2-角标位置不可控} 而且如上图所示，角标的位置不好控制，有的离文字很近，有的离得很远，无法精确控制。 # 六、最实用的TabLayout加角标方法 {#六、最实用的TabLayout加角标方法} ## 1. 添加getTabItemView()方法 {#1-添加getTabItemView-方法} 在重写的FragmentPagerAdapter中添加自定义Tab布局方法：&lt;figure class=&#34;highlight java&#34;&gt; &lt;table&gt; &lt;tr&gt; &lt;td class=&#34;gutter&#34;&gt; &lt;div class=&#34;top-box hide&#34;&gt; &lt;div class=&#34;alert-info&#34;&gt; &lt;/div&gt; &lt;/div&gt; ``` &lt;span class=&#34;line&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;2&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;3&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;4&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;5&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;6&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;7&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;8&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;9&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;10&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;11&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;12&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;13&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;14&lt;/span&gt; &lt;span class=&#34;line&#34;&gt;15&lt;/span&gt; &lt;/td&gt; &lt;td class=&quot;code hljs cs&quot;&gt; &lt;div class=&quot;top-box hide&quot;&gt; &lt;div class=&quot;alert-info&quot;&gt; &lt;/div&gt; &lt;/div&gt; ``` public View getTabItemView(int position) { View view = LayoutInflater.from(mContext).inflate(R.layout.tab_layout_item, null); TextView textView = (TextView) view.findViewById(R.id.textview); textView.setText(mPageTitleList.get(position));
View target = view.findViewById(R.id.badgeview_target);
BadgeView badgeView = new BadgeView(mContext); badgeView.setTargetView(target); badgeView.setBadgeMargin(, 6, 10, ); badgeView.setTextSize(10); badgeView.setText(formatBadgeNumber(mBadgeCountList.get(position)));
