keyword&#34;&gt;if&amp;lt;/span&gt; (!pathIsValid(context, apkPath)) { &amp;lt;span class=&#34;hljs-keyword&#34;&gt;return&amp;lt;/span&gt;; } SP sp = SP.getInstance(context); String paths = sp.getString(SP_KEY_HOT_PATCH, &amp;lt;span class=&#34;hljs-keyword&#34;&gt;null&amp;lt;/span&gt;); &amp;lt;span class=&#34;hljs-keyword&#34;&gt;if&amp;lt;/span&gt; (!TextUtils.isEmpty(paths)) { String allPath = &amp;lt;span class=&#34;hljs-keyword&#34;&gt;new&amp;lt;/span&gt; StringBuilder(apkPath).append(&amp;lt;span class=&#34;hljs-string&#34;&gt;&#34;,&#34;&amp;lt;/span&gt;).append(apkPath).toString(); sp.commit(SP_KEY_HOT_PATCH, allPath); } &amp;lt;span class=&#34;hljs-keyword&#34;&gt;else&amp;lt;/span&gt; { sp.commit(SP_KEY_HOT_PATCH, apkPath); } } &amp;lt;span class=&#34;hljs-function&#34;&gt;&amp;lt;span class=&#34;hljs-keyword&#34;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;static&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;clearHotPatchPaths&amp;lt;/span&gt;&amp;lt;span class=&#34;hljs-params&#34;&gt;(Context context)&amp;lt;/span&gt; &amp;lt;/span&gt;{ SP sp = SP.getInstance(context); sp.commit(SP_KEY_HOT_PATCH, &amp;lt;span class=&#34;hljs-string&#34;&gt;&#34;&#34;&amp;lt;/span&gt;); } }` ## Patch Apk部分： &lt;blockquote&gt; dexpose支持方法粒度的patch，可以实现整个方法的替换或方法前、后执行修复代码。 以下实例为方法替换实例，其它只需实现相应的回调接口即可。
&lt;/blockquote&gt; ### 方法替换实例： - 新建Android工程，引入patchloader.jar、dexposedbridge.jar； - 创建Patch修复类实现IPatch接口； ``` ` &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;public&lt;/span&gt; &lt;span class=&ldquo;hljs-class&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;class&lt;/span&gt; &lt;span class=&ldquo;hljs-title&rdquo;&gt;HotPatch&lt;/span&gt; &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;implements&lt;/span&gt; &lt;span class=&ldquo;hljs-title&rdquo;&gt;IPatch&lt;/span&gt; &lt;/span&gt;{
&lt;span class=&ldquo;hljs-annotation&rdquo;&gt;@Override&lt;/span&gt; &lt;span class=&ldquo;hljs-function&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;public&lt;/span&gt; &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;void&lt;/span&gt; &lt;span class=&ldquo;hljs-title&rdquo;&gt;handlePatch&lt;/span&gt;&lt;span class=&ldquo;hljs-params&rdquo;&gt;(&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;final&lt;/span&gt; PatchParam arg0)&lt;/span&gt; &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;throws&lt;/span&gt; Throwable &lt;/span&gt;{ Class&lt;?&gt; cls = &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;null&lt;/span&gt;; &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;try&lt;/span&gt; { cls= arg0.context.getClassLoader() .loadClass(&lt;span class=&ldquo;hljs-string&rdquo;&gt;&ldquo;com.zaozuo.app.MainActivity&rdquo;&lt;/span&gt;); } &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;catch&lt;/span&gt; (ClassNotFoundException e) { e.printStackTrace(); &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;return&lt;/span&gt;; } DexposedBridge.findAndHookMethod(cls, &lt;span class=&ldquo;hljs-string&rdquo;&gt;&ldquo;bindData&rdquo;&lt;/span&gt;, &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;new&lt;/span&gt; XC_MethodReplacement() { &lt;span class=&ldquo;hljs-annotation&rdquo;&gt;@Override&lt;/span&gt; &lt;span class=&ldquo;hljs-function&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;protected&lt;/span&gt; Object &lt;span class=&ldquo;hljs-title&rdquo;&gt;replaceHookedMethod&lt;/span&gt;&lt;span class=&ldquo;hljs-params&rdquo;&gt;(MethodHookParam param)&lt;/span&gt; &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;throws&lt;/span&gt; Throwable &lt;/span&gt;{ Activity mainActivity = (Activity) param.thisObject; Toast.makeText(mainActivity, &lt;span class=&ldquo;hljs-string&rdquo;&gt;&ldquo;test show hotPatch.&quot;&lt;/span&gt;,Toast.LENGTH_LONG).show(); &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;return&lt;/span&gt; &lt;span class=&ldquo;hljs-keyword&rdquo;&gt;null&lt;/span&gt;; } }); }
}`
