quot;hljs-keyword&quot;&gt;return&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;new&amp;lt;/span&gt; PointF(x, y); } &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;float&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;getMoveX&amp;lt;/span&gt;() { &amp;lt;span class=&quot;hljs-keyword&quot;&gt;return&amp;lt;/span&gt; mExtenalPointer.x; } &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;float&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;getMoveY&amp;lt;/span&gt;() { &amp;lt;span class=&quot;hljs-keyword&quot;&gt;return&amp;lt;/span&gt; mExtenalPointer.y; } &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-class&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;interface&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;OnMoveGestureListener&amp;lt;/span&gt; {&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;boolean&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;onMoveBegin&amp;lt;/span&gt;(MoveGestureDetector detector); &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;boolean&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;onMove&amp;lt;/span&gt;(MoveGestureDetector detector); &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;onMoveEnd&amp;lt;/span&gt;(MoveGestureDetector detector); } &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;static&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-class&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;class&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;SimpleMoveGestureDetector&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;implements&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;OnMoveGestureListener&amp;lt;/span&gt; {&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-annotation&quot;&gt;@Override&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;boolean&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;onMoveBegin&amp;lt;/span&gt;(MoveGestureDetector detector) { &amp;lt;span class=&quot;hljs-keyword&quot;&gt;return&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;true&amp;lt;/span&gt;; } &amp;lt;span class=&quot;hljs-annotation&quot;&gt;@Override&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;boolean&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;onMove&amp;lt;/span&gt;(MoveGestureDetector detector) { &amp;lt;span class=&quot;hljs-keyword&quot;&gt;return&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;false&amp;lt;/span&gt;; } &amp;lt;span class=&quot;hljs-annotation&quot;&gt;@Override&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-keyword&quot;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&quot;hljs-title&quot;&gt;onMoveEnd&amp;lt;/span&gt;(MoveGestureDetector detector) { } } }`
* BaseGestureDetector ``` `package com.zhy.blogcodes.largeImage.view; import android.content.Context; import android.view.MotionEvent; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;abstract&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;class&amp;lt;/span&gt; BaseGestureDetector { &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; boolean mGestureInProgress; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; MotionEvent mPreMotionEvent; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; MotionEvent mCurrentMotionEvent; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; Context mContext; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;BaseGestureDetector&amp;lt;/span&gt;(Context context) { mContext = context; } &amp;lt;span class=&#34;hljs-keyword&#34;&gt;public&amp;lt;/span&gt; boolean &amp;lt;span class=&#34;hljs-title&#34;&gt;onToucEvent&amp;lt;/span&gt;(MotionEvent &amp;lt;span class=&#34;hljs-keyword&#34;&gt;event&amp;lt;/span&gt;) { &amp;lt;span class=&#34;hljs-keyword&#34;&gt;if&amp;lt;/span&gt; (!mGestureInProgress) { handleStartProgressEvent(&amp;lt;span class=&#34;hljs-keyword&#34;&gt;event&amp;lt;/span&gt;); } &amp;lt;span class=&#34;hljs-keyword&#34;&gt;else&amp;lt;/span&gt; { handleInProgressEvent(&amp;lt;span class=&#34;hljs-keyword&#34;&gt;event&amp;lt;/span&gt;); } &amp;lt;span class=&#34;hljs-keyword&#34;&gt;return&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;true&amp;lt;/span&gt;; } &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;abstract&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;handleInProgressEvent&amp;lt;/span&gt;(MotionEvent &amp;lt;span class=&#34;hljs-keyword&#34;&gt;event&amp;lt;/span&gt;); &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;abstract&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;handleStartProgressEvent&amp;lt;/span&gt;(MotionEvent &amp;lt;span class=&#34;hljs-keyword&#34;&gt;event&amp;lt;/span&gt;); &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;abstract&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;updateStateByEvent&amp;lt;/span&gt;(MotionEvent &amp;lt;span class=&#34;hljs-keyword&#34;&gt;event&amp;lt;/span&gt;); &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;resetState&amp;lt;/span&gt;() { &amp;lt;span class=&#34;hljs-keyword&#34;&gt;if&amp;lt;/span&gt; (mPreMotionEvent != &amp;lt;span class=&#34;hljs-keyword&#34;&gt;null&amp;lt;/span&gt;) { mPreMotionEvent.recycle(); mPreMotionEvent = &amp;lt;span class=&#34;hljs-keyword&#34;&gt;null&amp;lt;/span&gt;; } &amp;lt;span class=&#34;hljs-keyword&#34;&gt;if&amp;lt;/span&gt; (mCurrentMotionEvent != &amp;lt;span class=&#34;hljs-keyword&#34;&gt;null&amp;lt;/span&gt;) { mCurrentMotionEvent.recycle(); mCurrentMotionEvent = &amp;lt;span class=&#34;hljs-keyword&#34;&gt;null&amp;lt;/span&gt;; } mGestureInProgress = &amp;lt;span class=&#34;hljs-keyword&#34;&gt;false&amp;lt;/span&gt;; } }` 你可能会说，一个move手势搞这么多代码，太麻烦了。的确是的，move手势的检测非常简单，那么之所以这么写呢，主要是为了可以复用，比如现在有一堆的`XXXGestureDetector`，当我们需要监听什么手势，就直接拿个detector来检测多方便。我相信大家肯定也郁闷过Google，为什么只有`ScaleGestureDetector`而没有`RotateGestureDetector`呢。 根据上述，大家应该理解了为什么要这么做，当时不强制，每个人都有个性。 &gt; 不过值得一提的是：上面这个手势检测的写法，不是我想的，而是一个开源的项目&lt;https://github.com/rharter/android-gesture-detectors&gt;，里面包含很多的手势检测。对应的博文是：&lt;http://code.almeros.com/android-multitouch-gesture-detectors#.VibzzhArJXg&gt;那面上面两个类就是我偷学了的~ 哈 ## &lt;a name=&quot;t4&quot;&gt;&lt;/a&gt;四、测试 {#四测试} 测试其实没撒好说的了，就是把我们的LargeImageView放入布局文件，然后Activity里面去设置inputstream了。 ``` `&lt;span class=&ldquo;hljs-tag&rdquo;&gt;&lt;&lt;span class=&ldquo;hljs-title&rdquo;&gt;RelativeLayout&lt;/span&gt; &lt;span class=&ldquo;hljs-attribute&rdquo;&gt;xmlns:android&lt;/span&gt;=&lt;span class=&ldquo;hljs-value&rdquo;&gt;&ldquo;http://schemas.android.com/apk/res/android&quot;&amp;lt;/span&gt; &lt;span class=&ldquo;hljs-attribute&rdquo;&gt;xmlns:tools&lt;/span&gt;=&lt;span class=&ldquo;hljs-value&rdquo;&gt;&ldquo;http://schemas.android.com/tools&quot;&amp;lt;/span&gt; &lt;span class=&ldquo;hljs-attribute&rdquo;&gt;android:layout_width&lt;/span&gt;=&lt;span class=&ldquo;hljs-value&rdquo;&gt;&ldquo;match_parent&rdquo;&lt;/span&gt; &lt;span class=&ldquo;hljs-attribute&rdquo;&gt;android:layout_height&lt;/span&gt;=&lt;span class=&ldquo;hljs-value&rdquo;&gt;&ldquo;match_parent&rdquo;&lt;/span&gt;&gt;&lt;/span&gt;
&amp;lt;span class=&quot;hljs-tag&quot;&gt;&amp;lt;&amp;lt;span class=&quot;hljs-title&quot;&gt;com.zhy.blogcodes.largeImage.view.LargeImageView &lt;/span&gt; &lt;span class=&ldquo;hljs-attribute&rdquo;&gt;android:id&lt;/span&gt;=&lt;span class=&ldquo;hljs-value&rdquo;&gt;&rdquo;@+id/id_largetImageview&rdquo;&lt;/span&gt; &lt;span class=&ldquo;hljs-attribute&rdquo;&gt;android:layout_width&lt;/span&gt;=&lt;span class=&ldquo;hljs-value&rdquo;&gt;&ldquo;match_parent&rdquo;&lt;/span&gt; &lt;span class=&ldquo;hljs-attribute&rdquo;&gt;android:layout_height&lt;/span&gt;=&lt;span class=&ldquo;hljs-value&rdquo;&gt;&ldquo;match_parent&rdquo;&lt;/span&gt;/&gt;&lt;/span&gt;
&lt;span class=&ldquo;hljs-tag&rdquo;&gt;&lt;/&lt;span class=&ldquo;hljs-title&rdquo;&gt;RelativeLayout&lt;/span&gt;&gt;&lt;/span&gt;`
然后在Activity里面去设置图片： ``` `&amp;lt;span class=&#34;hljs-keyword&#34;&gt;package&amp;lt;/span&gt; com.zhy.blogcodes.largeImage; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;import&amp;lt;/span&gt; android.os.Bundle; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;import&amp;lt;/span&gt; android.support.v7.app.AppCompatActivity; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;import&amp;lt;/span&gt; com.zhy.blogcodes.R; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;import&amp;lt;/span&gt; com.zhy.blogcodes.largeImage.view.LargeImageView; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;import&amp;lt;/span&gt; java.io.IOException; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;import&amp;lt;/span&gt; java.io.InputStream; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;public&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-class&#34;&gt;&amp;lt;span class=&#34;hljs-keyword&#34;&gt;class&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;LargeImageViewActivity&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;extends&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;AppCompatActivity&amp;lt;/span&gt; {&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;private&amp;lt;/span&gt; LargeImageView mLargeImageView; &amp;lt;span class=&#34;hljs-annotation&#34;&gt;@Override&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;protected&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-keyword&#34;&gt;void&amp;lt;/span&gt; &amp;lt;span class=&#34;hljs-title&#34;&gt;onCreate&amp;lt;/span&gt;(Bundle savedInstanceState) { &amp;lt;span class=&#34;hljs-keyword&#34;&gt;super&amp;lt;/span&gt;.onCreate(savedInstanceState); setContentView(R.layout.activity_large_image_view); mLargeImageView = (LargeImageView) findViewById(R.id.id_largetImageview); &amp;lt;span class=&#34;hljs-keyword&#34;&gt;try&amp;lt;/span&gt; { InputStream inputStream = getAssets().open(&amp;lt;span class=&#34;hljs-string&#34;&gt;&#34;world.jpg&#34;&amp;lt;/span&gt;); mLargeImageView.setInputStream(inputStream); } &amp;lt;span class=&#34;hljs-keyword&#34;&gt;catch&amp;lt;/span&gt; (IOException e) { e.printStackTrace(); } } }` 效果图： ok，那么到此，显示巨图的方案以及详细的代码就描述完成了，总体还是非常简单的。 但是，在实际的项目中，可能会有更多的需求，比如增加放大、缩小；增加快滑手势等等，那么大家可以去参考这个库：&lt;https://github.com/johnnylambada/WorldMap&gt;，该库基本实现了绝大多数的需求，大家根据本文这个思路再去看这个库，也会简单很多，定制起来也容易。我这个地图的图就是该库里面提供的。 哈，掌握了这个，以后面试过程中也可以悄悄的装一把了，当你优雅的答完android加载图片的方案以后，然后接一句，其实还有一种情况，就是高清显示巨图，那么我们应该…相信面试官对你的印象会好很多~ have a nice day ~ [源码点击下载][1] * * * ## &lt;a name=&quot;t5&quot;&gt;&lt;/a&gt;参考链接 {#参考链接} * &lt;http://code.almeros.com/android-multitouch-gesture-detectors#.VibzzhArJXg&gt; * &lt;https://github.com/rharter/android-gesture-detectors&gt; * &lt;https://github.com/johnnylambada/WorldMap&gt;

 ======================================================== 作者：qiujuer 博客：blog.csdn.net/qiujuer 网站：www.qiujuer.net 开源库：github.com/qiujuer/Genius-Android 转载请注明出处：http://blog.csdn.net/qiujuer/article/details/44195131 ——学之开源，用于开源；初学者的心态，与君共勉！
======================================================== 有一个好的库想与世界的伙伴分享，于是共享到GitHub上，于是有人看到了，但是要使用却发现配置非常难。但是发现别人的库只需要一行代码却能使用；于是我想知道为什么能这么简单。 在这篇文章中将带你了解如何发布你的库到远程仓库Maven中，又如何使用。
# &lt;a name=&quot;t0&quot;&gt;&lt;/a&gt;准备 开始之前我们有一定的准备工作，如果准备好了那么后面将会非常顺畅。 - [注册 https://issues.sonatype.org 账户](http://blog.csdn.net/qiujuer/article/details/44195199)，并创建你的 Group Id - 学会GPGTools的使用，并生成你的密钥对；见：[使用GPG对文件进行签名加密](http://blog.csdn.net/qiujuer/article/details/44173611) - 编写你的库，并准备好发布，工具：[Android-Studio](http://blog.csdn.net/qiujuer/article/details/41843095) - 添加发布Maven的Gradle文件 - 添加你的个人信息，如你的发布地址、库版本信息等 - 开发发布快照、以及正式版本，审核 # &lt;a name=&quot;t1&quot;&gt;&lt;/a&gt;开始 前面的两项工作由于篇幅较大，单独开篇了，欢迎大家去看~~，我们从第三的地方开始。 ## &lt;a name=&quot;t2&quot;&gt;&lt;/a&gt;编写Lib 编写库，这里我采用的是Android-Studio；至于其使用建立过程以及简单使用大家可见：[环境配置之正式版Android Studio 1.0](http://blog.csdn.net/qiujuer/article/details/41843095) 在这里我使用 [Genius-Android](https://github.com/qiujuer/Genius-Android) 开源库进行演示。 在本次项目中我们尝试发布 UI 部分，图中圈起来部分为我们需要的文件。
## &lt;a name=&quot;t3&quot;&gt;&lt;/a&gt;编写发布文件 发布文件就是其中的 **maven_push.gradle** 。由于代码较长就不贴代码了，大家可以去GitHub上查看。 代码已经发布到 BeFoot 开源项目中. 该代码运行在 Gradle 中，作用是按照配置进行打包代码文件，然后签名文件，最后发布你的文件到仓库。
在该代码中可以看见许多的方法与参数，如： ``` def isReleaseBuild() { &amp;lt;span class=&quot;hljs-keyword&quot;&gt;return&amp;lt;/span&gt; VERSION_NAME.contains(&amp;lt;span class=&quot;hljs-string&quot;&gt;&quot;SNAPSHOT&quot;&amp;lt;/span&gt;) == &amp;lt;span class=&quot;hljs-keyword&quot;&gt;false&amp;lt;/span&gt; }
- 1 - 2 - 3 这个方法的作用是判断版本名称是否含有 **“SNAPSHOT”**字段，也就是判断当前是否发布的是快照版本，以便传输到不同的服务器地址。 但是其中的 **“VERSION_NAME”** 哪里来的呢？往下看~~ ## &lt;a name=&#34;t4&#34;&gt;&lt;/a&gt;gradle.properties 在 **“maven_push”** 文件中所有的字段都是访问的你的 **“gradle.properties”** 文件。 ![这里写图片描述](http://img.blog.csdn.net/20150311174414025) 可以看见我们的项目中有两个这样的文件，两个文件中的内容都可以全部写到一个文件中。之所以写出两个，下面那个代表的是本项目中的全局变量，至于 UILib 中的那个则只局限于 UILib 中使用。 现在我们分别打开看看，首先打开下面那个全局的文件。 ![这里写图片描述](http://img.blog.csdn.net/20150311174954526) 在这里我们需要更改的地方有如下几个地方： ![这里写图片描述](http://img.blog.csdn.net/20150311182302469) 再来看看库中的文件： ![这里写图片描述](http://img.blog.csdn.net/20150311175830185) ** 这里相对简单的多了，无非就是名称，ID，类型，版本等信息。 有必要说明的是，上面的&lt;strong&gt;POM_GROUP_ID+POM_ARTIFACT_ID+VERSION_NAME** 将会得到如下的使用方式： &lt;/blockquote&gt; ``` `dependencies &amp;lt;span class=&#34;hljs-cell&#34;&gt;{ compile &amp;lt;span class=&#34;hljs-string&#34;&gt;&#39;com.github.qiujuer:genius-ui:3.0.0-SNAPSHOT&#39;&amp;lt;/span&gt; }&amp;lt;/span&gt;` - 1 - 2 - 3 完了？没~还有一个至关重要的地方，在”Maven_Push”的代码中我们会找到： 以及其中的 signing 部分，但是你会发现你找遍了上面的所有的文件都没有发现这些字段，那么这些字段在哪里呢？
很简单，在[Android-Studio 缓存文件夹配置](http://blog.csdn.net/qiujuer/article/details/44160127) 中有讲解**“.gradle”**目录对吧？那么现在我们去看看 这个目录中有什么。 可以看见其中也有一个 “gradle.properties”文件，这个文件不在项目中，但是在项目中却可以访问，这是一个全局的文件，任何项目都可以访问该文件，如果你没有，那么可以自己创建一个就OK。
** 为什么要存储到这里？我们都知道项目中的 &lt;strong&gt;“gradle.properties”** 文件一般来说都是会提交到 Git 上面去的，所以项目中的文件不应该包含私密的东西，比如密钥对，密钥密码，以及你的 Maven 的账户信息。 &lt;/blockquote&gt; 打开该文件我们能看见： - 密钥的相关东西请见：[使用GPG对文件进行签名加密](http://blog.csdn.net/qiujuer/article/details/44173611) - Sonatype 用户名密码详见：[注册 Maven 仓库 sonatype.org 账户](http://blog.csdn.net/qiujuer/article/details/44195199) ## &lt;a name=&quot;t5&quot;&gt;&lt;/a&gt;build.gradle 现在还需要修改你的项目中的 build 文件，需要更改的地方如下： ``` android { &amp;lt;span class=&quot;hljs-built_in&quot;&gt;source&amp;lt;/span&gt;Sets { main { manifest.srcFile &amp;lt;span class=&quot;hljs-string&quot;&gt;'src/main/AndroidManifest.xml'&amp;lt;/span&gt; java.srcDirs = [&amp;lt;span class=&quot;hljs-string&quot;&gt;'src/main/java'&amp;lt;/span&gt;] res.srcDirs = [&amp;lt;span class=&quot;hljs-string&quot;&gt;'src/main/res'&amp;lt;/span&gt;] } } lintOptions { abortOnError &amp;lt;span class=&quot;hljs-literal&quot;&gt;false&amp;lt;/span&gt; } } apply from: &amp;lt;span class=&quot;hljs-string&quot;&gt;'https://raw.github.com/qiujuer/BeFoot/master/blog/gradle-mvn-push/gradle-mvn-push.gradle'&amp;lt;/span&gt;
