t;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;else&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;if&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;skipMethodVerificationForClasses&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;containsKey&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;clazz&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;))&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;continue&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;else&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;throw&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;new&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;nf&quot;&gt;EventBusException&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;s&quot;&gt;&amp;lt;span class=&quot;hljs-string&quot;&gt;&quot;Illegal onEvent method, check &quot;&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;+&amp;lt;/span&gt; &amp;lt;span class=&quot;s&quot;&gt;&amp;lt;span class=&quot;hljs-string&quot;&gt;&quot;for typos: &quot;&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;+&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;method&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;Class&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;?&amp;gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;eventType&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;=&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;parameterTypes&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;[&amp;lt;/span&gt;&amp;lt;span class=&quot;mi&quot;&gt;&amp;lt;span class=&quot;hljs-number&quot;&gt;0&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;];&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;methodKeyBuilder&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;setLength&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;mi&quot;&gt;&amp;lt;span class=&quot;hljs-number&quot;&gt;0&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;methodKeyBuilder&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;append&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;methodName&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;methodKeyBuilder&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;append&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;sc&quot;&gt;&amp;lt;span class=&quot;hljs-string&quot;&gt;'&amp;gt;'&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;).&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;append&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;eventType&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;getName&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;());&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;String&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;methodKey&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;=&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;methodKeyBuilder&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;toString&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;();&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;if&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;eventTypesFound&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;add&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;methodKey&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;))&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;c1&quot;&gt;&amp;lt;span class=&quot;hljs-comment&quot;&gt;// 方法名,工作在哪个线程,事件类型&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;subscriberMethods&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;add&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;new&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;nf&quot;&gt;SubscriberMethod&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;method&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;threadMode&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;eventType&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;));&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt;
&lt;/div&gt; 还是反射，拿到这个方法的全部参数集合，如果是只有一个参数，再去根据不同的方法名赋予不同的线程模式(其实也就是最后响应的方法是工作在哪个线程)。 这里我们看到，其实`EventBus`不仅仅支持`onEvent()`的回调，它还支持`onEventMainThread()`、`onEventBackgroundThread()`、`onEventAsync()`这三个方法的回调。 一直到最后，我们看到这个方法把所有的方法名集合作为value，类名作为key存入了 methodCache 这个全局静态变量中。意味着，整个库在运行期间所有遍历的方法都会存在这个 map 中，而不必每次都去做耗时的反射取方法了。 &lt;div class=&#34;highlight&#34;&gt; &amp;lt;span class=&quot;kd&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;synchronized&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;methodCache&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;)&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;methodCache&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;put&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;key&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;subscriberMethods&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;return&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;subscriberMethods&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;;&amp;lt;/span&gt;
&lt;/div&gt; 看了这么久，我们再回到 `EventBus#register()` 方法。这回可以看懂了，就是拿到指定类名的全部订阅方法(以 onEvent 开头的方法)，并对每一个方法调用`subscribe()`。那么再看`subscribe()`方法。 ## 事件的处理与发送subscribe() {#subscribe-1} subscribe()方法接受四个参数，分别为：订阅者封装的对象、响应方法名封装的对象、是否为粘滞事件(可理解为广播)、这条事件的优先级。 &lt;div class=&#34;highlight&#34;&gt; `&lt;span class=&ldquo;c1&rdquo;&gt;&lt;span class=&ldquo;hljs-comment&rdquo;&gt;//根据传入的响应方法名获取到响应事件(参数类型)&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;Class&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;&lt;?&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;eventType&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;=&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscriberMethod&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;eventType&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;Subscription&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;newSubscription&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;=&lt;/span&gt; &lt;span class=&ldquo;k&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;new&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;nf&rdquo;&gt;Subscription&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;subscriber&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;,&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscriberMethod&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;,&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;priority&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;);&lt;/span&gt; &lt;span class=&ldquo;c1&rdquo;&gt;&lt;span class=&ldquo;hljs-comment&rdquo;&gt;//通过响应事件作为key,并取得这个事件类型将会响应的全部订阅者&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;c1&rdquo;&gt;&lt;span class=&ldquo;hljs-comment&rdquo;&gt;//没个订阅者至少会订阅一个事件,多个订阅者可能订阅同一个事件(多对多)&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;c1&rdquo;&gt;&lt;span class=&ldquo;hljs-comment&rdquo;&gt;//key:订阅的事件,value:订阅这个事件的所有订阅者集合&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;CopyOnWriteArrayList&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;&lt;&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;Subscription&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscriptions&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;=&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscriptionsByEventType&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;get&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;eventType&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;);&lt;/span&gt;
&lt;span class=&ldquo;c1&rdquo;&gt;&lt;span class=&ldquo;hljs-comment&rdquo;&gt;//根据优先级插入到订阅者集合中&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;kt&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;int&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;size&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;=&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscriptions&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;size&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;();&lt;/span&gt; &lt;span class=&ldquo;k&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;for&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;kt&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;int&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;i&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;=&lt;/span&gt; &lt;span class=&ldquo;mi&rdquo;&gt;&lt;span class=&ldquo;hljs-number&rdquo;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;i&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;&lt;=&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;size&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;i&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;++)&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;{&lt;/span&gt; &lt;span class=&ldquo;k&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;if&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;i&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;==&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;size&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;||&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;newSubscription&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;priority&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscriptions&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;get&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;i&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;).&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;priority&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;)&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;{&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscriptions&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;add&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;i&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;,&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;newSubscription&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;);&lt;/span&gt; &lt;span class=&ldquo;k&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;break&lt;/span&gt;&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;;&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;}&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;}&lt;/span&gt;
&lt;span class=&ldquo;c1&rdquo;&gt;&lt;span class=&ldquo;hljs-comment&rdquo;&gt;//当前订阅者订阅了哪些事件&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;List&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;&lt;&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;Class&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;&lt;?&gt;&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscribedEvents&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;=&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;typesBySubscriber&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;get&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;subscriber&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;);&lt;/span&gt; &lt;span class=&ldquo;k&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;if&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;subscribedEvents&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;==&lt;/span&gt; &lt;span class=&ldquo;kc&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;null&lt;/span&gt;&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;)&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;{&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscribedEvents&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;=&lt;/span&gt; &lt;span class=&ldquo;k&rdquo;&gt;&lt;span class=&ldquo;hljs-keyword&rdquo;&gt;new&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;ArrayList&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;&lt;&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;Class&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;&lt;?&gt;&gt;();&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;typesBySubscriber&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;put&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;subscriber&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;,&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscribedEvents&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;);&lt;/span&gt; &lt;span class=&ldquo;o&rdquo;&gt;}&lt;/span&gt; &lt;span class=&ldquo;c1&rdquo;&gt;&lt;span class=&ldquo;hljs-comment&rdquo;&gt;//key:订阅者对象,value:这个订阅者订阅的事件集合&lt;/span&gt;&lt;/span&gt; &lt;span class=&ldquo;n&rdquo;&gt;subscribedEvents&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;.&lt;/span&gt;&lt;span class=&ldquo;na&rdquo;&gt;add&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;(&lt;/span&gt;&lt;span class=&ldquo;n&rdquo;&gt;eventType&lt;/span&gt;&lt;span class=&ldquo;o&rdquo;&gt;);&lt;/span&gt;`
&lt;/div&gt; 跳过一些初始化的局部变量(逻辑看注释就够了) 如果传入的事件是有优先级之分的，则会根据优先级，将事件插入所有订阅了事件`eventType`的类的集合`subscriptions`中去。看逻辑我们发现，这里并没有对优先级的大小做限制，默认的优先级是0，priority越大，优先级越高。 每个订阅者是可以有多个重载的`onEvent()`方法的，所以这里多做了一步，将所有订阅者的响应方法保存到`subscribedEvents`中。 至此，我们就知道了 EventBus 中那几个map的全部含义。同时也回答了上一篇中问的为什么如果EventBus.defaultInstance不为null以后程序要抛出异常，就是因为这几个 map 不同了。 map 变了以后，订阅的事件就全部变为另一个 EventBus 对象的了，就没办法响应之前那个 EventBus 对象的订阅方法了。 最后又是一个感叹：子事件也可以让响应父事件的 onEvent() 。这个有点绕，举个例子，订阅者的onEvent(CharSequence),如果传一个String类型的值进去，默认情况下是不会响应的，但如果我们在构建的时候设置了 `eventInheritance` 为 true ,那么它就会响应了。 &lt;div class=&#34;highlight&#34;&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;if&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;sticky&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;)&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;if&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;eventInheritance&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;)&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;Set&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;Map&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;Entry&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;Class&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;?&amp;gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;Object&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;gt;&amp;gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;entries&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;=&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;stickyEvents&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;entrySet&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;();&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;for&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;Map&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;Entry&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;Class&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;?&amp;gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;Object&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;entry&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;:&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;entries&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;)&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;Class&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;?&amp;gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;candidateEventType&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;=&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;entry&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;getKey&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;();&amp;lt;/span&gt; &amp;lt;span class=&quot;c1&quot;&gt;&amp;lt;span class=&quot;hljs-comment&quot;&gt;//如果eventtype是candidateEventType同一个类或是其子类&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;if&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;eventType&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;isAssignableFrom&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;candidateEventType&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;))&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;Object&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;stickyEvent&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;=&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;entry&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;getValue&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;();&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;checkPostStickyEventToSubscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;newSubscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;stickyEvent&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;else&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;Object&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;stickyEvent&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;=&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;stickyEvents&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;get&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;eventType&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;checkPostStickyEventToSubscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;newSubscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;stickyEvent&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt;
&lt;/div&gt; 最后是调用`checkPostStickyEventToSubscription()`做一次安全判断，就调用`postToSubscription()`发送事件了。 这里就关联到了我们之前讲的Poster类的作用了。 回答之前的问题：Poster只负责粘滞事件的代码。这里可以回答一部分：如果不是 sticky 事件都直接不执行了，还怎么响应。 &lt;div class=&#34;highlight&#34;&gt; &amp;lt;span class=&quot;kd&quot;&gt;&amp;lt;span class=&quot;hljs-function&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;private&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;kt&quot;&gt;&amp;lt;span class=&quot;hljs-function&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;void&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;nf&quot;&gt;&amp;lt;span class=&quot;hljs-function&quot;&gt;&amp;lt;span class=&quot;hljs-title&quot;&gt;postToSubscription&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;&amp;lt;span class=&quot;hljs-function&quot;&gt;&amp;lt;span class=&quot;hljs-params&quot;&gt;(...)&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;switch&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;threadMode&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;)&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;case&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;nl&quot;&gt;PostThread:&amp;lt;/span&gt; &amp;lt;span class=&quot;c1&quot;&gt;&amp;lt;span class=&quot;hljs-comment&quot;&gt;//直接调用响应方法&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;invokeSubscriber&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;subscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;event&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;break&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;;&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;case&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;nl&quot;&gt;MainThread:&amp;lt;/span&gt; &amp;lt;span class=&quot;c1&quot;&gt;&amp;lt;span class=&quot;hljs-comment&quot;&gt;//如果是主线程则直接调用响应事件,否则使用handle去在主线程响应事件&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;if&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;isMainThread&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;)&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;invokeSubscriber&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;subscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;event&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;else&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;{&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;mainThreadPoster&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;enqueue&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;subscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;event&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;k&quot;&gt;&amp;lt;span class=&quot;hljs-keyword&quot;&gt;break&amp;lt;/span&gt;&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;;&amp;lt;/span&gt; &amp;lt;span class=&quot;c1&quot;&gt;&amp;lt;span class=&quot;hljs-comment&quot;&gt;//。。。&amp;lt;/span&gt;&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt; &amp;lt;span class=&quot;o&quot;&gt;}&amp;lt;/span&gt;
&lt;/div&gt; 最后，还记得我们之前没有讲的那个`invokeSubscriber(subscription, event);`方法吗？ 之前我们不知道`subscriberMethod`是什么，现在我们能看懂了，就是通过反射调用订阅者类`subscriber`的订阅方法`onEventXXX()`，并将`event`作为参数传递进去 &lt;div class=&#34;highlight&#34;&gt; &amp;lt;span class=&quot;n&quot;&gt;subscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;subscriberMethod&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;method&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;invoke&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&quot;n&quot;&gt;subscription&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&quot;na&quot;&gt;subscriber&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&quot;n&quot;&gt;event&amp;lt;/span&gt;&amp;lt;span class=&quot;o&quot;&gt;);&amp;lt;/span&gt;
&lt;/div&gt; ## Register与Poster工作图 {#registerposter} #### 原理图 {#section} ![开源实验室：图6](http://www.kymjs.com/images/blog_image/20151211_6.png) #### 流程图 {#section-1} 完整的注册流程 ![开源实验室：图7](http://www.kymjs.com/images/blog_image/20151211_7.png) 至此，整个EventBus从注册订阅到事件的处理到响应的过程我们都分析完了，最后就只剩下发送流程和取消注册了。

写一个listview容易，写一个adapter容易，自己new一个线程过滤数据也容易，但是如何将过滤的效率发挥到最大化，不得不提一下android自带的filter类。
有同学肯定要问，过滤数据自己写一个完全没问题，为什么要用android自带的filter类？我原来也是自己写线程过滤，然而最近项目中遇到一个低配机，双核0.8GCPU，过滤效果实在是卡顿厉害，优化起见，使用了android内部filter试一下效果，结果真是比自己写的好用，于是认真学习了下源码，从头至尾备忘如下：
![](http://images.cnblogs.com/OutliningIndicators/ExpandedBlockStart.gif) ![复制代码](http://common.cnblogs.com/images/copycode.gif) ``` private static final String LOG_TAG = &ldquo;Filter&rdquo;;
private static final String THREAD_NAME = &quot;Filter&quot;; private static final int FILTER_TOKEN = 0xD0D0F00D; private static final int FINISH_TOKEN = 0xDEADBEEF; private Handler mThreadHandler; private Handler mResultHandler; private Delayer mDelayer; private final Object mLock = new Object(); &lt;div class=&#34;cnblogs_code_toolbar&#34;&gt; &lt;span class=&#34;cnblogs_code_copy&#34;&gt;&lt;a title=&#34;复制代码&#34;&gt;![复制代码](http://common.cnblogs.com/images/copycode.gif)&lt;/a&gt;&lt;/span&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; 其实用到的全局变量只有8个，并且有一半是常量：两个handler，一个delayer，一个对象锁。google开发大牛用这几个变量加上为数不多的几个局部变量就做出来了一个拓展性极佳的过滤器，不得不让人钦佩。 首先看构造方法： &lt;div class=&#34;cnblogs_code&#34;&gt; ![](http://images.cnblogs.com/OutliningIndicators/ExpandedBlockStart.gif) &lt;div id=&#34;cnblogs_code_open_c440c2da-b7c0-476f-bacb-a745b6a72f88&#34; class=&#34;cnblogs_code_hide&#34;&gt; ``` public Filter() { mResultHandler = new ResultsHandler(); } 构造方法中二小强之一——ResultsHandler已经被创建了，顾名思义处理过滤操作结果。我们看看这个类的定义：
![](http://images.cnblogs.com/OutliningIndicators/ExpandedBlockStart.gif) ![复制代码](http://common.cnblogs.com/images/copycode.gif) ``` private class ResultsHandler extends Handler { /** * &lt;p&gt;Messages received from the request handler are processed in the * UI thread. The processing involves calling * {@link Filter#publishResults(CharSequence, * android.widget.Filter.FilterResults)} * to post the results back in the UI and then notifying the listener, * if any.&lt;/p&gt; * * @param msg the filtering results */ @Override public void handleMessage(Message msg) { RequestArguments args = (RequestArguments) msg.obj;
publishResults(args.constraint, args.results); if (args.listener != null) { int count = args.results != null ? args.results.count : -1; args.listener.onFilterComplete(count); } } } /** * &amp;lt;p&amp;gt;Holds the arguments of a filtering request as well as the results * of the request.&amp;lt;/p&amp;gt; */ private static class RequestArguments { /** * &amp;lt;p&amp;gt;The constraint used to filter the data.&amp;lt;/p&amp;gt; */ CharSequence constraint; /** * &amp;lt;p&amp;gt;The listener to notify upon completion. Can be null.&amp;lt;/p&amp;gt; */ FilterListener listener; /** * &amp;lt;p&amp;gt;The results of the filtering operation.&amp;lt;/p&amp;gt; */ FilterResults results; } /** * @hide */ public interface Delayer { /** * @param constraint The constraint passed to {@link Filter#filter(CharSequence)} * @return The delay that should be used for * {@link Handler#sendMessageDelayed(android.os.Message, long)} */ long getPostingDelay(CharSequence constraint); } &lt;div class=&#34;cnblogs_code_toolbar&#34;&gt; &lt;span class=&#34;cnblogs_code_copy&#34;&gt;&lt;a title=&#34;复制代码&#34;&gt;![复制代码](http://common.cnblogs.com/images/copycode.gif)&lt;/a&gt;&lt;/span&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; 注意到主要的操作就是：ResultsHandler接收到消息以后，调用抽象的publishResults()方法供UI线程更新画面。 接下来直接看主力的filter方法： &lt;div class=&#34;cnblogs_code&#34;&gt; ![](http://images.cnblogs.com/OutliningIndicators/ExpandedBlockStart.gif) &lt;div id=&#34;cnblogs_code_open_ee9d504d-96e2-4682-a87a-17ce3e453f0a&#34; class=&#34;cnblogs_code_hide&#34;&gt; &lt;div class=&#34;cnblogs_code_toolbar&#34;&gt; &lt;span class=&#34;cnblogs_code_copy&#34;&gt;&lt;a title=&#34;复制代码&#34;&gt;![复制代码](http://common.cnblogs.com/images/copycode.gif)&lt;/a&gt;&lt;/span&gt; &lt;/div&gt; ``` public final void filter(CharSequence constraint, FilterListener listener) { synchronized (mLock) { if (mThreadHandler == null) { HandlerThread thread = new HandlerThread( THREAD_NAME, android.os.Process.THREAD_PRIORITY_BACKGROUND); thread.start(); mThreadHandler = new RequestHandler(thread.getLooper()); } final long delay = (mDelayer == null) ? 0 : mDelayer.getPostingDelay(constraint); Message message = mThreadHandler.obtainMessage(FILTER_TOKEN); RequestArguments args = new RequestArguments(); // make sure we use an immutable copy of the constraint, so that // it doesn&#39;t change while the filter operation is in progress args.constraint = constraint != null ? constraint.toString() : null; args.listener = listener; message.obj = args; mThreadHandler.removeMessages(FILTER_TOKEN); mThreadHandler.removeMessages(FINISH_TOKEN); mThreadHandler.sendMessageDelayed(message, delay); } } &lt;div class=&quot;cnblogs_code_toolbar&quot;&gt; &lt;span class=&quot;cnblogs_code_copy&quot;&gt;&lt;a title=&quot;复制代码&quot;&gt;![复制代码](http://common.cnblogs.com/images/copycode.gif)&lt;/a&gt;&lt;/span&gt; &lt;/div&gt; 官方文档介绍这个每次调用这个方法将会开启一个异步的过滤操作，调用这个方法会取消之前没有执行的过滤操作，让我们分析一下他们是如何来做的。
首先整个方法都在同步块synchronized (mLock){}中，意图很直接：其他的方法我不管，排队队，吃果果，你一个，我一个，你下一个filter方法调用必须等我这次filter方法调用结束。接着呢，创建了一个HandlerThread，这个HandlerThread大家可以自行查看源码，实际上就是自备一个Handler的维他命——Looper，有了Looper，可以初始化我们的filter二小强之二（处理请求操作）：mThreadHandler = new RequestHandler(thread.getLooper());然后获得一个Message message = mThreadHandler.obtainMessage(FILTER_TOKEN);最后移除掉之前带有FILTER_TOKEN和FINISH_TOKEN的标记（因为后面的操作很有耗时的，你不晓得到底是执行到什么状态了），这样保证了这个方法执行以后，所有执行过滤的操作肯定只有一个message在传递了
这个方法的妙处在，方法本身很简单，几乎不耗时，即使你不断地调用filter（）方法，程序始终能保证只有一个message在做过滤操作。
接下来看看这个RequestHandler类;
![](http://images.cnblogs.com/OutliningIndicators/ExpandedBlockStart.gif) ![复制代码](http://common.cnblogs.com/images/copycode.gif) ``` private class RequestHandler extends Handler { public RequestHandler(Looper looper) { super(looper); }
/** * &amp;lt;p&amp;gt;Handles filtering requests by calling * {@link Filter#performFiltering} and then sending a message * with the results to the results handler.&amp;lt;/p&amp;gt; * * @param msg the filtering request */ public void handleMessage(Message msg) { int what = msg.what; Message message; switch (what) { case FILTER_TOKEN: RequestArguments args = (RequestArguments) msg.obj; try { args.results = performFiltering(args.constraint); } catch (Exception e) { args.results = new FilterResults(); Log.w(LOG_TAG, &quot;An exception occured during performFiltering()!&quot;, e); } finally { message = mResultHandler.obtainMessage(what); message.obj = args; message.sendToTarget(); } synchronized (mLock) { if (mThreadHandler != null) { Message finishMessage = mThreadHandler.obtainMessage(FINISH_TOKEN); mThreadHandler.sendMessageDelayed(finishMessage, 3000); } } break; case FINISH_TOKEN: synchronized (mLock) { if (mThreadHandler != null) { mThreadHandler.getLooper().quit(); mThreadHandler = null; } } break; } } } &lt;div class=&#34;cnblogs_code_toolbar&#34;&gt; &lt;span class=&#34;cnblogs_code_copy&#34;&gt;&lt;a title=&#34;复制代码&#34;&gt;![复制代码](http://common.cnblogs.com/images/copycode.gif)&lt;/a&gt;&lt;/span&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; 其实除了filter方法，主要的高端逻辑都在这里，试想一个场景，如果我连续调用了五次filter，这5个msg的第1个已经被remove掉了，但是由它调用的performFiltering()耗时任务还在进行，2，3，4肯定排队过程中就被第5个msg干掉了，然后第1个msg过滤操作完成，给ResultsHandler发送消息更新UI，然后给RequestHandler发一个三秒延时消息， 接着执行msg5，这时候再调用一次filter，msg1和msg5就被干掉了，然后同样是执行完由msg5调用的performFiltering()再执行msg6，然后是msg5和msg6最终都生成一个延时消息，msg5生成的延时消息把mThreadHandler销毁了，msg6生成的延时消息到的时候，不做任何操作。 前面我们在filter（）中看到过一次synchronized (mLock){}，而在这个handler中有两个同步代码块，case FINISH\_TOKEN中的同步代码块保证了，如果刚刚在filter中创建了mThreadHandler（这是UI线程的操作），会立刻移除所有之前的延迟消息，从而不会在此处去销毁掉mThreadHandler导致空指针异常。 case FILTER\_TOKEN中的同步代码块的作用，目前还是想不出来到底有什么用，因为case FILTER\_TOKEN和case FINISH\_TOKEN本来就是队列执行，不存在争用锁的情况，所以不会存在线程间的时空差导致的空指针，有高手能看出作用还望不吝赐教。 好了，来总结一下吧，其实作者就是利用了looper中messageQueue排队队的特性，又有两处对象同步锁的妙用，保证了UI线程和HandlerThread不冲突，而过滤过程中的一些冗余msg都被新msg创建时候给干掉了，一个线程有序进行，大哉大牛！ &amp;nbsp; &amp;nbsp; _Demo原文_ [http://blog.csdn.net/lfdfhl/article/details/18897401][1]{.cut.cut70} MainActivity如下: package cc.testfilterable;
import java.util.ArrayList; import java.util.HashMap; import android.os.Bundle; import android.widget.ListView; import android.app.Activity; import android.content.Context; /**
Demo描述: 利用Filter过滤数据 可用于AutoCompleteTextView筛选数据等功能 备注说明: 该Demo只表述原理,代码逻辑较简单,有一些小的bug. 完整的应用请参见以下资料. 参考资料: 1 http://gundumw100.iteye.com/blog/1446507 2 http://blog.csdn.net/ssstudio/article/details/7579089 3 http://blog.csdn.net/jiahui524/article/details/7802033 */ public class MainActivity extends Activity { private Context mContext; private ListView mListView; private ListViewAdapter mListViewAdapter; private ArrayList&lt;String&gt; mArrayList; private HashMap&lt;String, String&gt; mHashMap; @Override protected void onCreate(Bundle savedInstanceState) { super.onCreate(savedInstanceState); setContentView(R.layout.main); init(); }
