ListViewAdapter如下: &lt;div id=&#34;nei&#34; class=&#34;article_body&#34;&gt; &lt;div&gt; ``` &lt;span class=&#34;keyword&#34;&gt;package&lt;/span&gt; cc.testfilterable; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; java.util.ArrayList; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; java.util.Iterator; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; java.util.List; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.content.Context; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.LayoutInflater; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.View; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.ViewGroup; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.BaseAdapter; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.Filter; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.TextView; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;class&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;ListViewAdapter&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;extends&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;BaseAdapter&lt;/span&gt; {&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; NameFilter mNameFilter; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; List&amp;lt;String&amp;gt; mArrayList; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; List&amp;lt;String&amp;gt; mFilteredArrayList; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; LayoutInflater mLayoutInflater; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; ListViewAdapter(Context context,List&amp;lt;String&amp;gt; arrayList) { mArrayList = arrayList; mLayoutInflater=LayoutInflater.from(context); mFilteredArrayList=&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; ArrayList&amp;lt;String&amp;gt;(); } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; getCount() { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (mArrayList == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; (mArrayList.size()); } } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; Object getItem(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; position) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (mArrayList == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; mArrayList.get(position); } } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;long&lt;/span&gt; getItemId(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; position) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; position; } &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; Filter getFilter() { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (mNameFilter == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { mNameFilter = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; NameFilter(); } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; mNameFilter; } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; View getView(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; position, View convertView, ViewGroup parent) { View itemView = &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; itemView = convertView; ViewHolder viewHolder = &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemView == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { itemView = mLayoutInflater.inflate(R.layout.listviewitem, &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;); viewHolder = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; ViewHolder(); viewHolder.textView = (TextView) itemView.findViewById(R.id.textView); itemView.setTag(viewHolder); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { viewHolder = (ViewHolder) itemView.getTag(); } &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (mArrayList != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (viewHolder.textView != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { viewHolder.textView.setText((mArrayList.get(position))); } } convertView = itemView; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; convertView; } &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;class&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;ViewHolder&lt;/span&gt; {&lt;/span&gt; TextView textView; } &lt;span class=&#34;comment&#34;&gt;//过滤数据&lt;/span&gt; &lt;span class=&#34;class&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;NameFilter&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;extends&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;Filter&lt;/span&gt; {&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;//执行筛选&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; FilterResults performFiltering(CharSequence charSequence) { FilterResults filterResults = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; FilterResults(); &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (Iterator&amp;lt;String&amp;gt; iterator = mArrayList.iterator(); iterator.hasNext();) { String name = iterator.next(); System.out.println(&lt;span class=&#34;string&#34;&gt;&#34;---&amp;gt; name=&#34;&lt;/span&gt; + name); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (name.contains(charSequence)) { mFilteredArrayList.add(name); } } filterResults.values = mFilteredArrayList; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; filterResults; } &lt;span class=&#34;comment&#34;&gt;//筛选结果&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; publishResults(CharSequence arg0, FilterResults results) { mArrayList = (List&amp;lt;String&amp;gt;) results.values; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (results.count &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { notifyDataSetChanged(); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { notifyDataSetInvalidated(); } }} } ``` &lt;RelativeLayout xmlns:android=&ldquo;http://schemas.android.com/apk/res/android&quot; xmlns:tools=&ldquo;http://schemas.android.com/tools&quot; android:layout_width=&ldquo;match_parent&rdquo; android:layout_height=&ldquo;match_parent&rdquo; &gt;
