ter *	要设置的适配器 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setAdapter(WheelAdapter adapter) { &lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;.adapter = adapter; invalidateLayouts(); invalidate(); } &lt;span class=&#34;javadoc&#34;&gt;/** * 设置 Scroll 的插入器 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; interpolator *	the interpolator */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setInterpolator(Interpolator interpolator) { &lt;span class=&#34;comment&#34;&gt;//强制停止滚动&lt;/span&gt; scroller.forceFinished(&lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;); &lt;span class=&#34;comment&#34;&gt;//创建一个 Scroll 对象&lt;/span&gt; scroller = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; Scroller(getContext(), interpolator); } &lt;span class=&#34;javadoc&#34;&gt;/** * 获取课件条目数 * * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; the count of visible items */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; getVisibleItems() { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; visibleItems; } &lt;span class=&#34;javadoc&#34;&gt;/** * 设置可见条目数 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; count *	the new count */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setVisibleItems(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; count) { visibleItems = count; invalidate(); } &lt;span class=&#34;javadoc&#34;&gt;/** * 获取标签 * * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; the label */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; String getLabel() { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; label; } &lt;span class=&#34;javadoc&#34;&gt;/** * 设置标签 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; newLabel *	the label to set */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setLabel(String newLabel) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (label == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; || !label.equals(newLabel)) { label = newLabel; labelLayout = &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; invalidate(); } } &lt;span class=&#34;javadoc&#34;&gt;/** * 添加 WheelView 选择的元素改变监听器 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; listener *	the listener */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; addChangingListener(OnWheelChangedListener listener) { changingListeners.add(listener); } &lt;span class=&#34;javadoc&#34;&gt;/** * 移除 WheelView 元素改变监听器 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; listener *	the listener */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; removeChangingListener(OnWheelChangedListener listener) { changingListeners.remove(listener); } &lt;span class=&#34;javadoc&#34;&gt;/** * 回调元素改变监听器集合的元素改变监听器元素的元素改变方法 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; oldValue *	旧的 WheelView选中的值 * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; newValue *	新的 WheelView选中的值 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; notifyChangingListeners(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; oldValue, &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; newValue) { &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (OnWheelChangedListener listener : changingListeners) { listener.onChanged(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;, oldValue, newValue); } } &lt;span class=&#34;javadoc&#34;&gt;/** * 添加 WheelView 滚动监听器 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; listener *	the listener */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; addScrollingListener(OnWheelScrollListener listener) { scrollingListeners.add(listener); } &lt;span class=&#34;javadoc&#34;&gt;/** * 移除 WheelView 滚动监听器 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; listener *	the listener */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; removeScrollingListener(OnWheelScrollListener listener) { scrollingListeners.remove(listener); } &lt;span class=&#34;javadoc&#34;&gt;/** * 通知监听器开始滚动 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; notifyScrollingListenersAboutStart() { &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (OnWheelScrollListener listener : scrollingListeners) { &lt;span class=&#34;comment&#34;&gt;//回调开始滚动方法&lt;/span&gt; listener.onScrollingStarted(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); } } &lt;span class=&#34;javadoc&#34;&gt;/** * 通知监听器结束滚动 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; notifyScrollingListenersAboutEnd() { &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (OnWheelScrollListener listener : scrollingListeners) { &lt;span class=&#34;comment&#34;&gt;//回调滚动结束方法&lt;/span&gt; listener.onScrollingFinished(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); } } &lt;span class=&#34;javadoc&#34;&gt;/** * 获取当前选中元素的索引 * * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; * 当前元素索引 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; getCurrentItem() { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; currentItem; } &lt;span class=&#34;javadoc&#34;&gt;/** * 设置当前元素的位置, 如果索引是错误的 不进行任何操作 * -- 需要考虑该 WheelView 是否能循环 * -- 根据是否需要滚动动画来确定是 ①滚动到目的位置 还是 ②晴空所有条目然后重绘 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; index *	要设置的元素索引值 * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; animated *	动画标志位 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setCurrentItem(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; index, &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; animated) { &lt;span class=&#34;comment&#34;&gt;//如果没有适配器或者元素个数为0 直接返回&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (adapter == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; || adapter.getItemsCount() == &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;// throw?&lt;/span&gt; } &lt;span class=&#34;comment&#34;&gt;//目标索引小于 0 或者大于 元素索引最大值(个数 -1)&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (index &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt; || index &amp;gt;= adapter.getItemsCount()) { &lt;span class=&#34;comment&#34;&gt;//入股WheelView 可循环, 修正索引值, 如果不可循环直接返回&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (isCyclic) { &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; (index &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { index += adapter.getItemsCount(); } index %= adapter.getItemsCount(); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;// throw?&lt;/span&gt; } } &lt;span class=&#34;comment&#34;&gt;//如果当前的索引不是传入的 索引&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (index != currentItem) { &lt;span class=&#34;comment&#34;&gt;/* * 如果需要动画, 就滚动到目标位置 * 如果不需要动画, 重新设置布局 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (animated) { &lt;span class=&#34;comment&#34;&gt;/* * 开始滚动, 每个元素滚动间隔 400 ms, 滚动次数是 目标索引值 减去 当前索引值, 这是滚动的真实方法 */&lt;/span&gt; scroll(index - currentItem, SCROLLING_DURATION); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;//所有布局设置为 null, 滚动位置设置为 0&lt;/span&gt; invalidateLayouts(); &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; old = currentItem; currentItem = index; &lt;span class=&#34;comment&#34;&gt;//便利回调元素改变监听器集合中的监听器元素中的元素改变方法&lt;/span&gt; notifyChangingListeners(old, currentItem); &lt;span class=&#34;comment&#34;&gt;//重绘&lt;/span&gt; invalidate(); } } } &lt;span class=&#34;javadoc&#34;&gt;/** * 设置当前选中的条目, 没有动画, 当索引出错不做任何操作 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; index *	要设置的索引 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setCurrentItem(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; index) { setCurrentItem(index, &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;); } &lt;span class=&#34;javadoc&#34;&gt;/** * 获取 WheelView 是否可以循环 * -- 如果可循环 : 第一个之前是最后一个, 最后一个之后是第一个; * -- 如果不可循环 : 到第一个就不能上翻, 最后一个不能下翻 * * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; isCyclic() { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; isCyclic; } &lt;span class=&#34;javadoc&#34;&gt;/** * 设置 WheelView 循环标志 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; isCyclic *	the flag to set */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setCyclic(&lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; isCyclic) { &lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;.isCyclic = isCyclic; invalidate(); invalidateLayouts(); } &lt;span class=&#34;javadoc&#34;&gt;/** * 使布局无效 * 将 选中条目 和 普通条目设置为 null, 滚动位置设置为0 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; invalidateLayouts() { itemsLayout = &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; valueLayout = &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; scrollingOffset = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;javadoc&#34;&gt;/** * 初始化资源 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; initResourcesIfNecessary() { &lt;span class=&#34;comment&#34;&gt;/* * 设置绘制普通条目的画笔, 允许抗拒齿, 允许 fake-bold * 设置文字大小为 24 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemsPaint == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { itemsPaint = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; TextPaint(Paint.ANTI_ALIAS_FLAG | Paint.FAKE_BOLD_TEXT_FLAG); itemsPaint.setTextSize(TEXT_SIZE); } &lt;span class=&#34;comment&#34;&gt;/* * 设置绘制选中条目的画笔 * 设置文字大小 24 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (valuePaint == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { valuePaint = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; TextPaint(Paint.ANTI_ALIAS_FLAG | Paint.FAKE_BOLD_TEXT_FLAG | Paint.DITHER_FLAG); valuePaint.setTextSize(TEXT_SIZE); valuePaint.setShadowLayer(&lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;f, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;f, &lt;span class=&#34;number&#34;&gt;0xFFC0C0C0&lt;/span&gt;); } &lt;span class=&#34;comment&#34;&gt;//选中的条目背景&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (centerDrawable == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { centerDrawable = getContext().getResources().getDrawable(R.drawable.wheel_val); } &lt;span class=&#34;comment&#34;&gt;//创建顶部阴影图片&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (topShadow == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;comment&#34;&gt;/* * 构造方法中传入颜色渐变方向 * 阴影颜色 */&lt;/span&gt; topShadow = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; GradientDrawable(Orientation.TOP_BOTTOM, SHADOWS_COLORS); } &lt;span class=&#34;comment&#34;&gt;//创建底部阴影图片&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (bottomShadow == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { bottomShadow = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; GradientDrawable(Orientation.BOTTOM_TOP, SHADOWS_COLORS); } &lt;span class=&#34;comment&#34;&gt;/* * 设置 View 组件的背景 */&lt;/span&gt; setBackgroundResource(R.drawable.wheel_bg); } &lt;span class=&#34;javadoc&#34;&gt;/** * 计算布局期望的高度 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; layout *	组件的布局的 * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; * 布局需要的高度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; getDesiredHeight(Layout layout) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (layout == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;/* * 布局需要的高度是 条目个数 * 可见条目数 减去 顶部和底部隐藏的一部份 减去 额外的条目高度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; desired = getItemHeight() * visibleItems - ITEM_OFFSET * &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; - ADDITIONAL_ITEM_HEIGHT; &lt;span class=&#34;comment&#34;&gt;// 将计算的布局高度 与 最小高度比较, 取最大值&lt;/span&gt; desired = Math.max(desired, getSuggestedMinimumHeight()); &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; desired; } &lt;span class=&#34;javadoc&#34;&gt;/** * 根据条目获取字符串 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; index *	条目索引 * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; * 条目显示的字符串 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; String getTextItem(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; index) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (adapter == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; || adapter.getItemsCount() == &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;//适配器显示的字符串个数&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; count = adapter.getItemsCount(); &lt;span class=&#34;comment&#34;&gt;//考虑 index 小于 0 的情况&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; ((index &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt; || index &amp;gt;= count) &amp;&amp; !isCyclic) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; (index &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { index = count + index; } } &lt;span class=&#34;comment&#34;&gt;//index 大于 0&lt;/span&gt; index %= count; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; adapter.getItem(index); } &lt;span class=&#34;javadoc&#34;&gt;/** * 根据当前值创建 字符串 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; useCurrentValue * 是否在滚动 * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; the text * 生成的字符串 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; String buildText(&lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; useCurrentValue) { &lt;span class=&#34;comment&#34;&gt;//创建字符串容器&lt;/span&gt; StringBuilder itemsText = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; StringBuilder(); &lt;span class=&#34;comment&#34;&gt;//计算出显示的条目相对位置, 例如显示 5个, 第 3 个是正中见选中的布局&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; addItems = visibleItems / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;/* * 遍历显示的条目 * 获取当前显示条目 上下 各 addItems 个文本, 将该文本添加到显示文本中去 * 如果不是最后一个 都加上回车 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; i = currentItem - addItems; i &amp;lt;= currentItem + addItems; i++) { &lt;span class=&#34;comment&#34;&gt;//如果在滚动&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (useCurrentValue || i != currentItem) { String text = getTextItem(i); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (text != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { itemsText.append(text); } } &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (i &amp;lt; currentItem + addItems) { itemsText.append(&lt;span class=&#34;string&#34;&gt;&#34;\n&#34;&lt;/span&gt;); } } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; itemsText.toString(); } &lt;span class=&#34;javadoc&#34;&gt;/** * 返回 条目的字符串 * * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; * 条目最大宽度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; getMaxTextLength() { WheelAdapter adapter = getAdapter(); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (adapter == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;//如果获取的最大条目宽度不为 -1, 可以直接返回该条目宽度&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; adapterLength = adapter.getMaximumLength(); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (adapterLength &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; adapterLength; } String maxText = &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; addItems = visibleItems / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;/* * 遍历当前显示的条目, 获取字符串长度最长的那个, 返回这个最长的字符串长度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; i = Math.max(currentItem - addItems, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;); i &amp;lt; Math.min(currentItem + visibleItems, adapter.getItemsCount()); i++) { String text = adapter.getItem(i); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (text != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; &amp;&amp; (maxText == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; || maxText.length() &amp;lt; text.length())) { maxText = text; } } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; maxText != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; ? maxText.length() : &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;javadoc&#34;&gt;/** * 获取每个条目的高度 * * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; * 条目的高度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; getItemHeight() { &lt;span class=&#34;comment&#34;&gt;//如果条目高度不为 0, 直接返回&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemHeight != &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; itemHeight; &lt;span class=&#34;comment&#34;&gt;//如果条目的高度为 0, 并且普通条目布局不为null, 条目个数大于 2 &lt;/span&gt; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemsLayout != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; &amp;&amp; itemsLayout.getLineCount() &amp;gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;) { &lt;span class=&#34;comment&#34;&gt;/* * itemsLayout.getLineTop(2) : 获取顶部第二行上面的垂直(y轴)位置, 如果行数等于 */&lt;/span&gt; itemHeight = itemsLayout.getLineTop(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;) - itemsLayout.getLineTop(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;); &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; itemHeight; } &lt;span class=&#34;comment&#34;&gt;//如果上面都不符合, 使用整体高度处以 显示条目数&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; getHeight() / visibleItems; } &lt;span class=&#34;javadoc&#34;&gt;/** * 计算宽度并创建文字布局 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; widthSize *	输入的布局宽度 * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; mode *	布局模式 * &lt;span class=&#34;javadoctag&#34;&gt;@return&lt;/span&gt; * 计算的宽度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; calculateLayoutWidth(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; widthSize, &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; mode) { initResourcesIfNecessary(); &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; width = widthSize; &lt;span class=&#34;comment&#34;&gt;//获取最长的条目显示字符串字符个数&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; maxLength = getMaxTextLength(); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (maxLength &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;comment&#34;&gt;/* * 使用方法 FloatMath.ceil() 方法有以下警告 * Use java.lang.Math#ceil instead of android.util.FloatMath#ceil() since it is faster as of API 8 */&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;//float textWidth = FloatMath.ceil(Layout.getDesiredWidth(&#34;0&#34;, itemsPaint));&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;//向上取整 计算一个字符串宽度&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; textWidth = (&lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt;) Math.ceil(Layout.getDesiredWidth(&lt;span class=&#34;string&#34;&gt;&#34;0&#34;&lt;/span&gt;, itemsPaint)); &lt;span class=&#34;comment&#34;&gt;//获取字符串总的宽度&lt;/span&gt; itemsWidth = (&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt;) (maxLength * textWidth); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { itemsWidth = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;//总宽度加上一些间距&lt;/span&gt; itemsWidth += ADDITIONAL_ITEMS_SPACE; &lt;span class=&#34;comment&#34;&gt;// make it some more&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;//计算 label 的长度&lt;/span&gt; labelWidth = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (label != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; &amp;&amp; label.length() &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { labelWidth = (&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt;) Math.ceil(Layout.getDesiredWidth(label, valuePaint)); &lt;span class=&#34;comment&#34;&gt;//labelWidth = (int) FloatMath.ceil(Layout.getDesiredWidth(label, valuePaint));&lt;/span&gt; } &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; recalculate = &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;//精准模式&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (mode == MeasureSpec.EXACTLY) { &lt;span class=&#34;comment&#34;&gt;//精准模式下, 宽度就是给定的宽度&lt;/span&gt; width = widthSize; recalculate = &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;//未定义模式&lt;/span&gt; width = itemsWidth + labelWidth + &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; * PADDING; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (labelWidth &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { width += LABEL_OFFSET; } &lt;span class=&#34;comment&#34;&gt;// 获取 ( 计算出来的宽度 与 最小宽度的 ) 最大值&lt;/span&gt; width = Math.max(width, getSuggestedMinimumWidth()); &lt;span class=&#34;comment&#34;&gt;//最大模式 如果 给定的宽度 小于 计算出来的宽度, 那么使用最小的宽度 ( 给定宽度 | 计算出来的宽度 )&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (mode == MeasureSpec.AT_MOST &amp;&amp; widthSize &amp;lt; width) { width = widthSize; recalculate = &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } } &lt;span class=&#34;comment&#34;&gt;/* * 重新计算宽度 , 如果宽度是给定的宽度, 不是我们计算出来的宽度, 需要重新进行计算 * 重新计算的宽度是用于 * * 计算 itemsWidth , 这个与返回的 宽度无关, 与创建布局有关 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (recalculate) { &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; pureWidth = width - LABEL_OFFSET - &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; * PADDING; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (pureWidth &amp;lt;= &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { itemsWidth = labelWidth = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (labelWidth &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;double&lt;/span&gt; newWidthItems = (&lt;span class=&#34;keyword&#34;&gt;double&lt;/span&gt;) itemsWidth * pureWidth / (itemsWidth + labelWidth); itemsWidth = (&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt;) newWidthItems; labelWidth = pureWidth - itemsWidth; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { itemsWidth = pureWidth + LABEL_OFFSET; &lt;span class=&#34;comment&#34;&gt;// no label&lt;/span&gt; } } &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemsWidth &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;comment&#34;&gt;//创建布局&lt;/span&gt; createLayouts(itemsWidth, labelWidth); } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; width; } &lt;span class=&#34;javadoc&#34;&gt;/** * 创建布局 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; widthItems *	布局条目宽度 * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; widthLabel *	label 宽度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; createLayouts(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; widthItems, &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; widthLabel) { &lt;span class=&#34;comment&#34;&gt;/* * 创建普通条目布局 * 如果 普通条目布局 为 null 或者 普通条目布局的宽度 大于 传入的宽度, 这时需要重新创建布局 * 如果 普通条目布局存在, 并且其宽度小于传入的宽度, 此时需要将 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemsLayout == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; || itemsLayout.getWidth() &amp;gt; widthItems) { &lt;span class=&#34;comment&#34;&gt;/* * android.text.StaticLayout.StaticLayout( * CharSequence source, TextPaint paint, * int width, Alignment align, * float spacingmult, float spacingadd, boolean includepad) * 传入参数介绍 : * CharSequence source : 需要分行显示的字符串 * TextPaint paint : 绘制字符串的画笔 * int width : 条目的宽度 * Alignment align : Layout 的对齐方式, ALIGN_CENTER 居中对齐, ALIGN_NORMAL 左对齐, Alignment.ALIGN_OPPOSITE 右对齐 * float spacingmult : 行间距, 1.5f 代表 1.5 倍字体高度 * float spacingadd : 基础行距上增加多少 , 真实行间距 等于 spacingmult 和 spacingadd 的和 * boolean includepad : */&lt;/span&gt; itemsLayout = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; StaticLayout(buildText(isScrollingPerformed), itemsPaint, widthItems, widthLabel &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt; ? Layout.Alignment.ALIGN_OPPOSITE : Layout.Alignment.ALIGN_CENTER, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, ADDITIONAL_ITEM_HEIGHT, &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;//调用 Layout 内置的方法 increaseWidthTo 将宽度提升到指定的宽度&lt;/span&gt; itemsLayout.increaseWidthTo(widthItems); } &lt;span class=&#34;comment&#34;&gt;/* * 创建选中条目 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (!isScrollingPerformed &amp;&amp; (valueLayout == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; || valueLayout.getWidth() &amp;gt; widthItems)) { String text = getAdapter() != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; ? getAdapter().getItem(currentItem) : &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; valueLayout = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; StaticLayout(text != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; ? text : &lt;span class=&#34;string&#34;&gt;&#34;&#34;&lt;/span&gt;, valuePaint, widthItems, widthLabel &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt; ? Layout.Alignment.ALIGN_OPPOSITE : Layout.Alignment.ALIGN_CENTER, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, ADDITIONAL_ITEM_HEIGHT, &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (isScrollingPerformed) { valueLayout = &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { valueLayout.increaseWidthTo(widthItems); } &lt;span class=&#34;comment&#34;&gt;/* * 创建标签条目 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (widthLabel &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (labelLayout == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt; || labelLayout.getWidth() &amp;gt; widthLabel) { labelLayout = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; StaticLayout(label, valuePaint, widthLabel, Layout.Alignment.ALIGN_NORMAL, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, ADDITIONAL_ITEM_HEIGHT, &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { labelLayout.increaseWidthTo(widthLabel); } } } &lt;span class=&#34;comment&#34;&gt;/* * 测量组件大小 * (non-Javadoc) * @see android.view.View#onMeasure(int, int) */&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onMeasure(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; widthMeasureSpec, &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; heightMeasureSpec) { &lt;span class=&#34;comment&#34;&gt;//获取宽度 和 高度的模式 和 大小&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; widthMode = MeasureSpec.getMode(widthMeasureSpec); &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; heightMode = MeasureSpec.getMode(heightMeasureSpec); &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; widthSize = MeasureSpec.getSize(widthMeasureSpec); &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; heightSize = MeasureSpec.getSize(heightMeasureSpec); &lt;span class=&#34;comment&#34;&gt;//宽度就是 计算的布局的宽度&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; width = calculateLayoutWidth(widthSize, widthMode); &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; height; &lt;span class=&#34;comment&#34;&gt;/* * 精准模式 * 精准模式下 高度就是精确的高度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (heightMode == MeasureSpec.EXACTLY) { height = heightSize; &lt;span class=&#34;comment&#34;&gt;//未定义模式 和 最大模式&lt;/span&gt; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;//未定义模式下 获取布局需要的高度&lt;/span&gt; height = getDesiredHeight(itemsLayout); &lt;span class=&#34;comment&#34;&gt;//最大模式下 获取 布局高度 和 布局所需高度的最小值&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (heightMode == MeasureSpec.AT_MOST) { height = Math.min(height, heightSize); } } &lt;span class=&#34;comment&#34;&gt;//设置组件的宽和高&lt;/span&gt; setMeasuredDimension(width, height); } &lt;span class=&#34;comment&#34;&gt;/* * 绘制组件 * (non-Javadoc) * @see android.view.View#onDraw(android.graphics.Canvas) */&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onDraw(Canvas canvas) { &lt;span class=&#34;keyword&#34;&gt;super&lt;/span&gt;.onDraw(canvas); &lt;span class=&#34;comment&#34;&gt;//如果条目布局为 null, 就创建该布局&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemsLayout == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;comment&#34;&gt;/* * 如果 条目宽度为0, 说明该宽度没有计算, 先计算, 计算完之后会创建布局 * 如果 条目宽度 大于 0, 说明已经计算过宽度了, 直接创建布局 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemsWidth == &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { calculateLayoutWidth(getWidth(), MeasureSpec.EXACTLY); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;//创建普通条目布局, 选中条目布局, 标签条目布局&lt;/span&gt; createLayouts(itemsWidth, labelWidth); } } &lt;span class=&#34;comment&#34;&gt;//如果条目宽度大于0&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (itemsWidth &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { canvas.save(); &lt;span class=&#34;comment&#34;&gt;// 使用平移方法忽略 填充的空间 和 顶部底部隐藏的一部份条目&lt;/span&gt; canvas.translate(PADDING, -ITEM_OFFSET); &lt;span class=&#34;comment&#34;&gt;//绘制普通条目&lt;/span&gt; drawItems(canvas); &lt;span class=&#34;comment&#34;&gt;//绘制选中条目&lt;/span&gt; drawValue(canvas); canvas.restore(); } &lt;span class=&#34;comment&#34;&gt;//在中心位置绘制&lt;/span&gt; drawCenterRect(canvas); &lt;span class=&#34;comment&#34;&gt;//绘制阴影&lt;/span&gt; drawShadows(canvas); } &lt;span class=&#34;javadoc&#34;&gt;/** * Draws shadows on top and bottom of control * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; canvas *	the canvas for drawing */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; drawShadows(Canvas canvas) { topShadow.setBounds(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, getWidth(), getHeight() / visibleItems); topShadow.draw(canvas); bottomShadow.setBounds(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, getHeight() - getHeight() / visibleItems, getWidth(), getHeight()); bottomShadow.draw(canvas); } &lt;span class=&#34;javadoc&#34;&gt;/** * 绘制选中条目 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; canvas *	画布 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; drawValue(Canvas canvas) { valuePaint.setColor(VALUE_TEXT_COLOR); &lt;span class=&#34;comment&#34;&gt;//将当前 View 状态属性值 转为整型集合, 赋值给 普通条目布局的绘制属性&lt;/span&gt; valuePaint.drawableState = getDrawableState(); Rect bounds = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; Rect(); &lt;span class=&#34;comment&#34;&gt;//获取选中条目布局的边界&lt;/span&gt; itemsLayout.getLineBounds(visibleItems / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, bounds); &lt;span class=&#34;comment&#34;&gt;// 绘制标签&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (labelLayout != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { canvas.save(); canvas.translate(itemsLayout.getWidth() + LABEL_OFFSET, bounds.top); labelLayout.draw(canvas); canvas.restore(); } &lt;span class=&#34;comment&#34;&gt;// 绘制选中条目&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (valueLayout != &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { canvas.save(); canvas.translate(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, bounds.top + scrollingOffset); valueLayout.draw(canvas); canvas.restore(); } } &lt;span class=&#34;javadoc&#34;&gt;/** * 绘制普通条目 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; canvas *	画布 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; drawItems(Canvas canvas) { canvas.save(); &lt;span class=&#34;comment&#34;&gt;//获取 y 轴 定点高度&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; top = itemsLayout.getLineTop(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;); canvas.translate(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, -top + scrollingOffset); &lt;span class=&#34;comment&#34;&gt;//设置画笔颜色&lt;/span&gt; itemsPaint.setColor(ITEMS_TEXT_COLOR); &lt;span class=&#34;comment&#34;&gt;//将当前 View 状态属性值 转为整型集合, 赋值给 普通条目布局的绘制属性&lt;/span&gt; itemsPaint.drawableState = getDrawableState(); &lt;span class=&#34;comment&#34;&gt;//将布局绘制到画布上&lt;/span&gt; itemsLayout.draw(canvas); canvas.restore(); } &lt;span class=&#34;javadoc&#34;&gt;/** * 绘制当前选中条目的背景图片 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; canvas *	画布 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; drawCenterRect(Canvas canvas) { &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; center = getHeight() / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; offset = getItemHeight() / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;; centerDrawable.setBounds(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, center - offset, getWidth(), center + offset); centerDrawable.draw(canvas); } &lt;span class=&#34;comment&#34;&gt;/* * 继承自 View 的触摸事件, 当出现触摸事件的时候, 就会回调该方法 * (non-Javadoc) * @see android.view.View#onTouchEvent(android.view.MotionEvent) */&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onTouchEvent(MotionEvent event) { &lt;span class=&#34;comment&#34;&gt;//获取适配器&lt;/span&gt; WheelAdapter adapter = getAdapter(); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (adapter == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;/* * gestureDetector.onTouchEvent(event) : 分析给定的动作, 如果可用, 调用 手势检测器的 onTouchEvent 方法 * -- 参数解析 : ev , 触摸事件 * -- 返回值 : 如果手势监听器成功执行了该方法, 返回true, 如果执行出现意外 返回 false; */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (!gestureDetector.onTouchEvent(event) &amp;&amp; event.getAction() == MotionEvent.ACTION_UP) { justify(); } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;javadoc&#34;&gt;/** * 滚动 WheelView * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; delta *	滚动的值 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; doScroll(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; delta) { scrollingOffset += delta; &lt;span class=&#34;comment&#34;&gt;//计算滚动的条目数, 使用滚动的值 处于 单个条目高度, 注意计算整数值&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; count = scrollingOffset / getItemHeight(); &lt;span class=&#34;comment&#34;&gt;/* * pos 是滚动后的目标元素索引 * 计算当前位置, 当前条目数 减去 滚动的条目数 * 注意 滚动条目数可正 可负 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; pos = currentItem - count; &lt;span class=&#34;comment&#34;&gt;//如果是可循环的, 并且条目数大于0&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (isCyclic &amp;&amp; adapter.getItemsCount() &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;comment&#34;&gt;//设置循环, 如果位置小于0, 那么该位置就显示最后一个元素&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; (pos &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { pos += adapter.getItemsCount(); } &lt;span class=&#34;comment&#34;&gt;//如果位置正无限大, 模条目数 取余&lt;/span&gt; pos %= adapter.getItemsCount(); &lt;span class=&#34;comment&#34;&gt;// (前提 : 不可循环 条目数大于0, 可循环 条目数小于0, 条目数小于0, 不可循环) , 如果滚动在执行&lt;/span&gt; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (isScrollingPerformed) { &lt;span class=&#34;comment&#34;&gt;//位置一旦小于0, 计算的位置就赋值为 0, 条目滚动数为0&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (pos &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { count = currentItem; pos = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;//位置大于条目数的时候, 当前位置等于(条目数 - 1), 条目滚动数等于 当前位置 减去 (条目数 - 1)&lt;/span&gt; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (pos &amp;gt;= adapter.getItemsCount()) { count = currentItem - adapter.getItemsCount() + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;; pos = adapter.getItemsCount() - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;; } } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;// fix position&lt;/span&gt; pos = Math.max(pos, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;); pos = Math.min(pos, adapter.getItemsCount() - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;); } &lt;span class=&#34;comment&#34;&gt;//滚动的高度&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; offset = scrollingOffset; &lt;span class=&#34;comment&#34;&gt;/* * 如果当前位置不是滚动后的目标位置, 就将当前位置设置为目标位置 * 否则就重绘组件 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (pos != currentItem) { setCurrentItem(pos, &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;//重绘组件&lt;/span&gt; invalidate(); } &lt;span class=&#34;comment&#34;&gt;// 将滚动后剩余的小数部分保存&lt;/span&gt; scrollingOffset = offset - count * getItemHeight(); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (scrollingOffset &amp;gt; getHeight()) { scrollingOffset = scrollingOffset % getHeight() + getHeight(); } } &lt;span class=&#34;javadoc&#34;&gt;/** * 手势监听器 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; SimpleOnGestureListener gestureListener = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; SimpleOnGestureListener() { &lt;span class=&#34;comment&#34;&gt;//按下操作&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onDown(MotionEvent e) { &lt;span class=&#34;comment&#34;&gt;//如果滚动在执行&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (isScrollingPerformed) { &lt;span class=&#34;comment&#34;&gt;//滚动强制停止, 按下的时候不能继续滚动&lt;/span&gt; scroller.forceFinished(&lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;); &lt;span class=&#34;comment&#34;&gt;//清理信息&lt;/span&gt; clearMessages(); &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;/* * 手势监听器监听到 滚动操作后回调 * * 参数解析 : * MotionEvent e1 : 触发滚动时第一次按下的事件 * MotionEvent e2 : 触发当前滚动的移动事件 * float distanceX : 自从上一次调用 该方法 到这一次 x 轴滚动的距离, * 注意不是 e1 到 e2 的距离, e1 到 e2 的距离是从开始滚动到现在的滚动距离 * float distanceY : 自从上一次回调该方法到这一次 y 轴滚动的距离 * * 返回值 : 如果事件成功触发, 执行完了方法中的操作, 返回true, 否则返回 false * (non-Javadoc) * @see android.view.GestureDetector.SimpleOnGestureListener#onScroll(android.view.MotionEvent, android.view.MotionEvent, float, float) */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onScroll(MotionEvent e1, MotionEvent e2, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; distanceX, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; distanceY) { &lt;span class=&#34;comment&#34;&gt;//开始滚动, 并回调滚动监听器集合中监听器的 开始滚动方法&lt;/span&gt; startScrolling(); doScroll((&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt;) -distanceY); &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;/* * 当一个急冲手势发生后 回调该方法, 会计算出该手势在 x 轴 y 轴的速率 * * 参数解析 : * -- MotionEvent e1 : 急冲动作的第一次触摸事件; * -- MotionEvent e2 : 急冲动作的移动发生的时候的触摸事件; * -- float velocityX : x 轴的速率 * -- float velocityY : y 轴的速率 * * 返回值 : 如果执行完毕返回 true, 否则返回false, 这个就是自己定义的 * * (non-Javadoc) * @see android.view.GestureDetector.SimpleOnGestureListener#onFling(android.view.MotionEvent, android.view.MotionEvent, float, float) */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onFling(MotionEvent e1, MotionEvent e2, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; velocityX, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; velocityY) { &lt;span class=&#34;comment&#34;&gt;//计算上一次的 y 轴位置, 当前的条目高度 加上 剩余的 不够一行高度的那部分&lt;/span&gt; lastScrollY = currentItem * getItemHeight() + scrollingOffset; &lt;span class=&#34;comment&#34;&gt;//如果可以循环最大值是无限大, 不能循环就是条目数的高度值&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; maxY = isCyclic ? &lt;span class=&#34;number&#34;&gt;0x7FFFFFFF&lt;/span&gt; : adapter.getItemsCount() * getItemHeight(); &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; minY = isCyclic ? -maxY : &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;/* * Scroll 开始根据一个急冲手势滚动, 滚动的距离与初速度有关 * 参数介绍 : * -- int startX : 开始时的 X轴位置 * -- int startY : 开始时的 y轴位置 * -- int velocityX : 急冲手势的 x 轴的初速度, 单位 px/s * -- int velocityY : 急冲手势的 y 轴的初速度, 单位 px/s * -- int minX : x 轴滚动的最小值 * -- int maxX : x 轴滚动的最大值 * -- int minY : y 轴滚动的最小值 * -- int maxY : y 轴滚动的最大值 */&lt;/span&gt; scroller.fling(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, lastScrollY, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, (&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt;) -velocityY / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, minY, maxY); setNextMessage(MESSAGE_SCROLL); &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } }; &lt;span class=&#34;comment&#34;&gt;// Handler 中的 Message 信息&lt;/span&gt; &lt;span class=&#34;javadoc&#34;&gt;/** 滚动信息 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;final&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; MESSAGE_SCROLL = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;javadoc&#34;&gt;/** 调整信息 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;final&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; MESSAGE_JUSTIFY = &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;; &lt;span class=&#34;javadoc&#34;&gt;/** * 清空之前的 Handler 队列, 发送下一个消息到 Handler 中 * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; message *	要发送的消息 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; setNextMessage(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; message) { &lt;span class=&#34;comment&#34;&gt;//清空 Handler 队列中的 what 消息&lt;/span&gt; clearMessages(); &lt;span class=&#34;comment&#34;&gt;//发送消息到 Handler 中&lt;/span&gt; animationHandler.sendEmptyMessage(message); } &lt;span class=&#34;javadoc&#34;&gt;/** * 清空队列中的信息 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; clearMessages() { &lt;span class=&#34;comment&#34;&gt;//删除 Handler 执行队列中的滚动操作&lt;/span&gt; animationHandler.removeMessages(MESSAGE_SCROLL); animationHandler.removeMessages(MESSAGE_JUSTIFY); } &lt;span class=&#34;javadoc&#34;&gt;/** * 动画控制器 * animation handler * * 可能会造成内存泄露 : 添加注解 HandlerLeak * Handler 类应该应该为static类型，否则有可能造成泄露。 * 在程序消息队列中排队的消息保持了对目标Handler类的应用。 * 如果Handler是个内部类，那 么它也会保持它所在的外部类的引用。 * 为了避免泄露这个外部类，应该将Handler声明为static嵌套类，并且使用对外部类的弱应用。 */&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@SuppressLint&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&#34;HandlerLeak&#34;&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; Handler animationHandler = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; Handler() { &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; handleMessage(Message msg) { &lt;span class=&#34;comment&#34;&gt;//回调该方法获取当前位置, 如果返回true, 说明动画还没有执行完毕&lt;/span&gt; scroller.computeScrollOffset(); &lt;span class=&#34;comment&#34;&gt;//获取当前 y 位置&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; currY = scroller.getCurrY(); &lt;span class=&#34;comment&#34;&gt;//获取已经滚动了的位置, 使用上一次位置 减去 当前位置&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; delta = lastScrollY - currY; lastScrollY = currY; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (delta != &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;comment&#34;&gt;//改变值不为 0 , 继续滚动&lt;/span&gt; doScroll(delta); } &lt;span class=&#34;comment&#34;&gt;/* * 如果滚动到了指定的位置, 滚动还没有停止 * 这时需要强制停止 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (Math.abs(currY - scroller.getFinalY()) &amp;lt; MIN_DELTA_FOR_SCROLLING) { currY = scroller.getFinalY(); scroller.forceFinished(&lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;); } &lt;span class=&#34;comment&#34;&gt;/* * 如果滚动没有停止 * 再向 Handler 发送一个停止 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (!scroller.isFinished()) { animationHandler.sendEmptyMessage(msg.what); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (msg.what == MESSAGE_SCROLL) { justify(); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { finishScrolling(); } } }; &lt;span class=&#34;javadoc&#34;&gt;/** * 调整 WheelView */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; justify() { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (adapter == &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;//上一次的 y 轴的位置为 0&lt;/span&gt; lastScrollY = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; offset = scrollingOffset; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; itemHeight = getItemHeight(); &lt;span class=&#34;comment&#34;&gt;/* * 当滚动补偿 大于 0, 说明还有没有滚动的部分, needToIncrease 是 当前条目是否小于条目数 * 如果 滚动补偿不大于 0, needToIncrease 是当前条目是否大于 0 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; needToIncrease = offset &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt; ? currentItem &amp;lt; adapter.getItemsCount() : currentItem &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; ((isCyclic || needToIncrease) &amp;&amp; Math.abs((&lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt;) offset) &amp;gt; (&lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt;) itemHeight / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (offset &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) offset += itemHeight + MIN_DELTA_FOR_SCROLLING; &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; offset -= itemHeight + MIN_DELTA_FOR_SCROLLING; } &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (Math.abs(offset) &amp;gt; MIN_DELTA_FOR_SCROLLING) { scroller.startScroll(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, offset, SCROLLING_DURATION); setNextMessage(MESSAGE_JUSTIFY); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { finishScrolling(); } } &lt;span class=&#34;javadoc&#34;&gt;/** * WheelView 开始滚动 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; startScrolling() { &lt;span class=&#34;comment&#34;&gt;//如果没有滚动, 将滚动状态 isScrollingPerformed 设为 true&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (!isScrollingPerformed) { isScrollingPerformed = &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;//通知监听器开始滚动 回调所有的 滚动监听集合中 的 开始滚动方法&lt;/span&gt; notifyScrollingListenersAboutStart(); } } &lt;span class=&#34;javadoc&#34;&gt;/** * 结束滚动 * 设置滚动状态为 false, 回调滚动监听器的停止滚动方法 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; finishScrolling() { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (isScrollingPerformed) { notifyScrollingListenersAboutEnd(); isScrollingPerformed = &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; } &lt;span class=&#34;comment&#34;&gt;//设置布局无效&lt;/span&gt; invalidateLayouts(); &lt;span class=&#34;comment&#34;&gt;//重绘布局&lt;/span&gt; invalidate(); } &lt;span class=&#34;javadoc&#34;&gt;/** * 滚动 WheelView * * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; itemsToSkip *	滚动的元素个数 * &lt;span class=&#34;javadoctag&#34;&gt;@param&lt;/span&gt; time *	每次滚动的间隔 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; scroll(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; itemsToScroll, &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; time) { &lt;span class=&#34;comment&#34;&gt;//如果有滚动强制停止&lt;/span&gt; scroller.forceFinished(&lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;); lastScrollY = scrollingOffset; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; offset = itemsToScroll * getItemHeight(); &lt;span class=&#34;comment&#34;&gt;/* * 给定 一个开始点, 滚动距离, 滚动间隔, 开始滚动 * * 参数解析 : * 1. 开始的 x 轴位置 * 2. 开始的 y 轴位置 * 3. 要滚动 x 轴距离 * 4. 要滚动 y 轴距离 * 5. 滚动花费的时间 */&lt;/span&gt; scroller.startScroll(&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, lastScrollY, &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;, offset - lastScrollY, time); setNextMessage(MESSAGE_SCROLL); &lt;span class=&#34;comment&#34;&gt;//设置开始滚动状态, 并回调滚动监听器方法&lt;/span&gt; startScrolling(); } } ## 7. Activity 主界面 ``` package cn.org.octopus.wheelview;
