动是否结束。&lt;/span&gt; 举例说明，自定义一个CustomView，使用Scroller实现滚动：
Java代码 &lt;embed src=&quot;http://ipjmc.iteye.com/javascripts/syntaxhighlighter/clipboard_new.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;14&quot; height=&quot;15&quot;&gt; &lt;/embed&gt; &lt;a title=&quot;收藏这段代码&quot;&gt;![收藏代码](http://ipjmc.iteye.com/images/icon_star.png)&lt;/a&gt; &lt;/div&gt; - &lt;span class=&quot;keyword&quot;&gt;import&lt;/span&gt; android.content.Context; - &lt;span class=&quot;keyword&quot;&gt;import&lt;/span&gt; android.util.AttributeSet; - &lt;span class=&quot;keyword&quot;&gt;import&lt;/span&gt; android.util.Log; - &lt;span class=&quot;keyword&quot;&gt;import&lt;/span&gt; android.view.View; - &lt;span class=&quot;keyword&quot;&gt;import&lt;/span&gt; android.widget.LinearLayout; - &lt;span class=&quot;keyword&quot;&gt;import&lt;/span&gt; android.widget.Scroller; - - &lt;span class=&quot;keyword&quot;&gt;public&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;class&lt;/span&gt; CustomView &lt;span class=&quot;keyword&quot;&gt;extends&lt;/span&gt; LinearLayout { - - &lt;span class=&quot;keyword&quot;&gt;private&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;static&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;final&lt;/span&gt; String TAG = &lt;span class=&quot;string&quot;&gt;&amp;#8220;Scroller&amp;#8221;&lt;/span&gt;; - - &lt;span class=&quot;keyword&quot;&gt;private&lt;/span&gt; Scroller mScroller; - - &lt;span class=&quot;keyword&quot;&gt;public&lt;/span&gt; CustomView(Context context, AttributeSet attrs) { - &lt;span class=&quot;keyword&quot;&gt;super&lt;/span&gt;(context, attrs); - mScroller = &lt;span class=&quot;keyword&quot;&gt;new&lt;/span&gt; Scroller(context); - } - - &lt;span class=&quot;comment&quot;&gt;//调用此方法滚动到目标位置&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;public&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; smoothScrollTo(&lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; fx, &lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; fy) { - &lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; dx = fx &amp;#8211; mScroller.getFinalX(); - &lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; dy = fy &amp;#8211; mScroller.getFinalY(); - smoothScrollBy(dx, dy); - } - - &lt;span class=&quot;comment&quot;&gt;//调用此方法设置滚动的相对偏移&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;public&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; smoothScrollBy(&lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; dx, &lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; dy) { - - &lt;span class=&quot;comment&quot;&gt;//设置mScroller的滚动偏移量&lt;/span&gt; - mScroller.startScroll(mScroller.getFinalX(), mScroller.getFinalY(), dx, dy); - invalidate();&lt;span class=&quot;comment&quot;&gt;//这里必须调用invalidate()才能保证computeScroll()会被调用，否则不一定会刷新界面，看不到滚动效果&lt;/span&gt; - } - - &lt;span class=&quot;annotation&quot;&gt;@Override&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;public&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; computeScroll() { - - &lt;span class=&quot;comment&quot;&gt;//先判断mScroller滚动是否完成&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;if&lt;/span&gt; (mScroller.computeScrollOffset()) { - - &lt;span class=&quot;comment&quot;&gt;//这里调用View的scrollTo()完成实际的滚动&lt;/span&gt; - scrollTo(mScroller.getCurrX(), mScroller.getCurrY()); - - &lt;span class=&quot;comment&quot;&gt;//必须调用该方法，否则不一定能看到滚动效果&lt;/span&gt; - postInvalidate(); - } - &lt;span class=&quot;keyword&quot;&gt;super&lt;/span&gt;.computeScroll(); - } - } - 转自：http://ipjmc.iteye.com/blog/1615828 &amp;nbsp; public class CustomView extends LinearLayout { private static final String TAG = CustomView.class.getName(); // 定义一个滑动 private Scroller mScroller; //手势 private GestureDetector mGestureDetector;
public CustomView(Context context, AttributeSet attrs, int defStyle) { super(context, attrs, defStyle); mScroller = new Scroller(context); mGestureDetector = new GestureDetector(context, new CustomGestureListener()); }
public CustomView(Context context, AttributeSet attrs) { super(context, attrs); mScroller = new Scroller(context); mGestureDetector = new GestureDetector(context, new CustomGestureListener()); }
public CustomView(Context context) { super(context); mScroller = new Scroller(context); mGestureDetector = new GestureDetector(context, new CustomGestureListener()); // setClickable(true); // setLongClickable(true); }
// 调用此方法滚动到目标位置 public void smoothScrollTo(int fx, int fy) { int dx = fx – mScroller.getFinalX(); int dy = fy – mScroller.getFinalY(); smoothScrollBy(dx, dy); }
// 调用此方法设置滚动的相对偏移 public void smoothScrollBy(int dx, int dy) { // 设置mScroller的滚动偏移量 mScroller.startScroll(mScroller.getFinalX(), mScroller.getFinalY(), dx, dy); invalidate();// 这里必须调用invalidate()才能保证computeScroll()会被调用，否则不一定会刷新界面，看不到滚动效果 }
/** 完成实际的滚动 */ @Override public void computeScroll() { // 判断Scroll是否滚动完成 if (mScroller.computeScrollOffset()) { // 调用View 的scrollto完成实际的滚动 scrollTo(mScroller.getCurrX(), mScroller.getCurrY()); //必须调用该方法，否则不一定能看到滚动效果 postInvalidate(); } super.computeScroll(); }
