/**
将32位的int值放到4字节的里 @param num @return
*/
public static byte[] int2byteArray(int num) {
byte[] result = new byte[4];
result[0] = (byte) (num &raquo;&gt; 24);// 取最高8位放到0下标
result[1] = (byte) (num &raquo;&gt; 16);// 取次高8为放到1下标
result[2] = (byte) (num &raquo;&gt; 8); // 取次低8位放到2下标
result[3] = (byte) (num); // 取最低8位放到3下标
return result;
} /**
将4字节的byte数组转成一个int值 @param b @return
*/
public static int byteArray2int(byte[] b) {
byte[] a = new byte[4];
int i = a.length – 1, j = b.length – 1;
for (; i &gt;= 0; i–, j–) {// 从b的尾部(即int值的低位)开始copy数据
if (j &gt;= 0)
a[i] = b[j];
else
a[i] = 0;// 如果b.length不足4,则将高位补0
}
int v0 = (a[0] &amp; 0xff) &laquo; 24;// &amp;0xff将byte值无差异转成int,避免Java自动类型提升后,会保留高位的符号位
int v1 = (a[1] &amp; 0xff) &laquo; 16;
int v2 = (a[2] &amp; 0xff) &laquo; 8;
int v3 = (a[3] &amp; 0xff);
return v0 + v1 + v2 + v3;
} /**
转换short为byte @param b @param s 需要转换的short @param index
*/
public static void putShort(byte b[], short s, int index) {
b[index + 0] = (byte) (s &raquo; 8);
b[index + 1] = (byte) (s &raquo; 0);
} /**
通过byte数组取到short @param b @param index 第几位开始取 @return
*/
public static short getShort(byte[] b, int index) {
return (short) (((b[index + 1] &laquo; 8) | b[index + 0] &amp; 0xff));
} /**
字符到字节转换 @param ch @return
*/
public static void putChar(byte[] bb, char ch, int index) {
int temp = (int) ch;
// byte[] b = new byte[2];
for (int i = 0; i &lt; 2; i++) {
// 将最高位保存在最低位
bb[index + i] = new Integer(temp &amp; 0xff).byteValue();
temp = temp &raquo; 8; // 向右移8位
}
} /**
字节到字符转换 @param b @return
*/
public static char getChar(byte[] b, int index) {
int s = 0;
if (b[index + 1] &gt; 0)
s += b[index + 1];
else
s += 256 + b[index + 0];
s *= 256;
if (b[index + 0] &gt; 0)
s += b[index + 1];
else
s += 256 + b[index + 0];
char ch = (char) s;
return ch;
} /**
float转换byte @param bb @param x @param index
*/
public static void putFloat(byte[] bb, float x, int index) {
// byte[] b = new byte[4];
int l = Float.floatToIntBits(x);
for (int i = 0; i &lt; 4; i++) {
bb[index + i] = new Integer(l).byteValue();
l = l &raquo; 8;
}
} /**
通过byte数组取得float @param bb @param index @return
*/
public static float getFloat(byte[] b, int index) {
int l;
l = b[index + 0];
l &amp;= 0xff;
l |= ((long) b[index + 1] &laquo; 8);
l &amp;= 0xffff;
l |= ((long) b[index + 2] &laquo; 16);
l &amp;= 0xffffff;
l |= ((long) b[index + 3] &laquo; 24);
return Float.intBitsToFloat(l);
} /**
double转换byte @param bb @param x @param index
*/
public static void putDouble(byte[] bb, double x, int index) {
// byte[] b = new byte[8];
long l = Double.doubleToLongBits(x);
for (int i = 0; i &lt; 4; i++) {
bb[index + i] = new Long(l).byteValue();
l = l &raquo; 8;
}
} /**
通过byte数组取得double @param bb @param index @return
*/
public static double getDouble(byte[] b, int index) {
long l;
l = b[0];
l &amp;= 0xff;
l |= ((long) b[1] &laquo; 8);
l &amp;= 0xffff;
l |= ((long) b[2] &laquo; 16);
l &amp;= 0xffffff;
l |= ((long) b[3] &laquo; 24);
l &amp;= 0xffffffffl;
l |= ((long) b[4] &laquo; 32);
l &amp;= 0xffffffffffl;
l |= ((long) b[5] &laquo; 40);
l &amp;= 0xffffffffffffl;
l |= ((long) b[6] &laquo; 48);
l &amp;= 0xffffffffffffffl;
l |= ((long) b[7] &laquo; 56);
return Double.longBitsToDouble(l);
}

 Java代码 &lt;embed src=&quot;http://androidbin.iteye.com/javascripts/syntaxhighlighter/clipboard_new.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;14&quot; height=&quot;15&quot;&gt; &lt;/embed&gt; &lt;a title=&quot;收藏这段代码&quot;&gt;![收藏代码](http://androidbin.iteye.com/images/icon_star.png)&lt;/a&gt; &lt;/div&gt; - Paint p = &lt;span class=&quot;keyword&quot;&gt;new&lt;/span&gt; Paint(Paint.ANTI_ALIAS_FLAG); - p.setStyle(Style.STROKE); - p.setColor(Color.WHITE); - p.setStrokeWidth(&lt;span class=&quot;number&quot;&gt;1&lt;/span&gt;); - PathEffect effects = &lt;span class=&quot;keyword&quot;&gt;new&lt;/span&gt; DashPathEffect(&lt;span class=&quot;keyword&quot;&gt;new&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;float&lt;/span&gt;[] { &lt;span class=&quot;number&quot;&gt;1&lt;/span&gt;, &lt;span class=&quot;number&quot;&gt;2&lt;/span&gt;, &lt;span class=&quot;number&quot;&gt;4&lt;/span&gt;, &lt;span class=&quot;number&quot;&gt;8&lt;/span&gt;}, &lt;span class=&quot;number&quot;&gt;1&lt;/span&gt;); - p.setPathEffect(effects); - canvas.drawLine(&lt;span class=&quot;number&quot;&gt;&lt;/span&gt;, &lt;span class=&quot;number&quot;&gt;40&lt;/span&gt;, mWidth, &lt;span class=&quot;number&quot;&gt;40&lt;/span&gt;, p); DashPathEffect是PathEffect类的一个子类,可以使paint画出类似虚线的样子,并且可以任意指定虚实的排列方式.
代码中的float数组,必须是偶数长度,且&gt;=2,指定了多少长度的实线之后再画多少长度的空白.
如本代码中,绘制长度1的实线,再绘制长度2的空白,再绘制长度4的实线,再绘制长度8的空白,依次重复.1是偏移量,可以不用理会.
效果如下:
简单介绍下 PathEffect类:
PathEffect是用来控制绘制轮廓(线条)的方式。
PathEffect对于绘制Path基本图形特别有用，但是它们也可以应用到任何Paint中从而影响线条绘制的方式。
使用PathEffect，可以改变一个形状的边角的外观并且控制轮廓的外表。
Android包含了多个PathEffect，包括：
CornerPathEffect 可以使用圆角来代替尖锐的角从而对基本图形的形状尖锐的边角进行平滑。
DashPathEffect 可以使用DashPathEffect来创建一个虚线的轮廓(短横线/小圆点)，而不是使用实线。你还可以指定任意的虚/实线段的重复模式。
DiscretePathEffect 与DashPathEffect相似，但是添加了随机性。当绘制它的时候，需要指定每一段的长度和与原始路径的偏离度。
PathDashPathEffect 这种效果可以定义一个新的形状(路径)并将其用作原始路径的轮廓标记。
下面的效果可以在一个Paint中组合使用多个Path Effect。
SumPathEffect 顺序地在一条路径中添加两种效果，这样每一种效果都可以应用到原始路径中，而且两种结果可以结合起来。
ComposePathEffect 将两种效果组合起来应用，先使用第一种效果，然后在这种效果的基础上应用第二种效果。
对象形状的PathEffect的改变会影响到形状的区域。这就能够保证应用到相同形状的填充效果将会绘制到新的边界中。
例如：只要修改相关属性相信就可以满足你的要求
public class DashedLineView extends View {
public DashedLineView(Context context, AttributeSet attrs,
int defStyleAttr, int defStyleRes) {
this(context, attrs, defStyleAttr);
}
public DashedLineView(Context context, AttributeSet attrs, int defStyleAttr) {
super(context, attrs, defStyleAttr);
}
public DashedLineView(Context context, AttributeSet attrs) {
super(context, attrs);
}
public DashedLineView(Context context) {
super(context);
}
@SuppressLint(“DrawAllocation”)
@Override
protected void onDraw(Canvas canvas) {
// TODO Auto-generated method stub
super.onDraw(canvas);
Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
paint.setStyle(Paint.Style.STROKE);
paint.setColor(Color.BLACK);
paint.setStrokeWidth(0.5f);
Path path = new Path();
path.moveTo(0, 10);
path.lineTo(getWidth(), 10);
PathEffect effects = new DashPathEffect(new float[] { 5, 5, 5, 5 }, 1);
paint.setPathEffect(effects);
canvas.drawPath(path, paint);
}
}

 github上类似项目 https://github.com/jfeinstein10/SlidingMenu https://github.com/yueyueniao2012/SlidingMenu *转自：* [http://blog.csdn.net/jj120522/article/details/8075249](http://blog.csdn.net/jj120522/article/details/8075249?utm_source=tuicool) 首先我们看下面视图： ![](http://img1.tuicool.com/yyqeQv.png) ![](http://img0.tuicool.com/mYVFFr.png) 这种效果大家都不陌生，网上好多都说是仿人人网的，估计人家牛逼出来的早吧，我也参考了一一些例子，实现起来有三种方法，我下面简单介绍下： 方法一： 其实就是对GestureDetector手势的应用及布局文件的设计 . 布局文件main.xml 采用RelativeLayout布局. ``` &lt;?xml version=&ldquo;1.0&rdquo; encoding=&ldquo;utf-8&rdquo;?&gt; &lt;RelativeLayout xmlns:android=&ldquo;http://schemas.android.com/apk/res/android&quot; android:layout_width=&ldquo;fill_parent&rdquo; android:layout_height=&ldquo;fill_parent&rdquo; android:orientation=&ldquo;vertical&rdquo; &gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;LinearLayout android:id=&rdquo;@+id/layout_right&quot; android:layout_width=&ldquo;fill_parent&rdquo; android:layout_height=&ldquo;fill_parent&rdquo; android:layout_marginLeft=&ldquo;50dp&rdquo; android:orientation=&ldquo;vertical&rdquo; &gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;AbsoluteLayout android:layout_width=&ldquo;fill_parent&rdquo; android:layout_height=&ldquo;wrap_content&rdquo; android:background=&quot;@color/grey21&quot; android:padding=&ldquo;10dp&rdquo; &gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;TextView android:layout_width=&ldquo;wrap_content&rdquo; android:layout_height=&ldquo;wrap_content&rdquo; android:text=&ldquo;设置&rdquo; android:textColor=&quot;@android:color/background_light&quot; android:textSize=&ldquo;20sp&rdquo; /&gt; &lt;/AbsoluteLayout&gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;ListView android:id=&quot;@+id/lv_set&quot; android:layout_width=&ldquo;fill_parent&rdquo; android:layout_height=&ldquo;fill_parent&rdquo; android:layout_weight=&ldquo;1&rdquo; &gt; &lt;/ListView&gt; &lt;/LinearLayout&gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;LinearLayout android:id=&quot;@+id/layout_left&quot; android:layout_width=&ldquo;fill_parent&rdquo; android:layout_height=&ldquo;fill_parent&rdquo; android:background=&quot;@color/white&quot; android:orientation=&ldquo;vertical&rdquo; &gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;RelativeLayout android:layout_width=&ldquo;fill_parent&rdquo; android:layout_height=&ldquo;wrap_content&rdquo; android:background=&quot;@drawable/nav_bg&quot; &gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;ImageView android:id=&quot;@+id/iv_set&quot; android:layout_width=&ldquo;wrap_content&rdquo; android:layout_height=&ldquo;wrap_content&rdquo; android:layout_alignParentRight=&ldquo;true&rdquo; android:layout_alignParentTop=&ldquo;true&rdquo; android:src=&quot;@drawable/nav_setting&quot; /&gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;TextView android:layout_width=&ldquo;wrap_content&rdquo; android:layout_height=&ldquo;wrap_content&rdquo; android:layout_centerInParent=&ldquo;true&rdquo; android:text=&ldquo;我&rdquo; android:textColor=&quot;@android:color/background_light&quot; android:textSize=&ldquo;20sp&rdquo; /&gt; &lt;/RelativeLayout&gt;
&lt;span class=&quot;tag&quot;&gt;&amp;lt;&lt;span class=&quot;title&quot;&gt;ImageView android:id=&quot;@+id/iv_set&quot; android:layout_width=&ldquo;fill_parent&rdquo; android:layout_height=&ldquo;fill_parent&rdquo; android:scaleType=&ldquo;fitXY&rdquo; android:src=&quot;@drawable/bg_guide_5&quot; /&gt; &lt;/LinearLayout&gt;
&lt;/RelativeLayout&gt;
![](http://img0.tuicool.com/QfYjYf.png)layout_right ：这个大布局文件， layout_left:距离左边50dp像素.(我们要移动的是 layout_left ). 看到这个图我想大家都很清晰了吧，其实: 我们就是把layout_left这个布局控件整理向左移动，至于移动多少，就要看layout_right有多宽了。layout_left移动到距离左边的边距就是layout_right的宽及-MAX_WIDTH.相信大家都理解. 布局文件就介绍到这里，下面看代码. ``` &lt;span class=&#34;javadoc&#34;&gt;/*** * 初始化view */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; InitView() { layout_left = (LinearLayout) findViewById(R.id.layout_left); layout_right = (LinearLayout) findViewById(R.id.layout_right); iv_set = (ImageView) findViewById(R.id.iv_set); lv_set = (ListView) findViewById(R.id.lv_set); lv_set.setAdapter(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; ArrayAdapter&amp;lt;String&amp;gt;(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;, R.layout.item, R.id.tv_item, title)); lv_set.setOnItemClickListener(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; OnItemClickListener() { &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onItemClick(AdapterView&amp;lt;?&amp;gt; parent, View view, &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; position, &lt;span class=&#34;keyword&#34;&gt;long&lt;/span&gt; id) { Toast.makeText(MainActivity.&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;, title[position], &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;).show(); } }); layout_left.setOnTouchListener(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); iv_set.setOnTouchListener(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); mGestureDetector = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; GestureDetector(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); &lt;span class=&#34;comment&#34;&gt;// 禁用长按监听&lt;/span&gt; mGestureDetector.setIsLongpressEnabled(&lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;); getMAX_WIDTH(); } 这里要对手势进行监听，我想大家都知道怎么做，在这里我要说明一个方法： ``` /***
获取移动距离 移动的距离其实就是layout_left的宽度 */ void getMAX_WIDTH() { ViewTreeObserver viewTreeObserver = layout_left.getViewTreeObserver(); // 获取控件宽度 viewTreeObserver.addOnPreDrawListener(new OnPreDrawListener() { @Override public boolean onPreDraw() { if (!hasMeasured) { window_width = getWindowManager().getDefaultDisplay() .getWidth(); RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams) layout_left .getLayoutParams(); layoutParams.width = window_width; layout_left.setLayoutParams(layoutParams); MAX_WIDTH = layout_right.getWidth(); Log.v(TAG, &ldquo;MAX_WIDTH=&quot; + MAX_WIDTH + &ldquo;width=&quot; + window_width); hasMeasured = true; } return true; } }); }
在这里我们要获取屏幕的宽度，并将屏幕宽度设置给layout_left这个控件，为什么要这么做呢 ， 因为如果不把该控件宽度写死的话，那么系统将认为layout_left会根据不同环境宽度自动适应，也就是说我们通过layout_left.getLayoutParams动态移动该控件的时候，该控件会伸缩而不是移动。 描述的有点模糊，大家请看下面示意图就明白了. 我们不为 layout_left定义死宽度效果： ![](http://img1.tuicool.com/ziAjIr.png) ![](http://img0.tuicool.com/VrqI32.png) getLayoutParams可以很清楚看到， layout_left被向左拉伸了，并不是我们要的效果. 还有一种解决办法就是我们在配置文件中直接把 layout_left宽度写死，不过这样不利于开发，因为分辨率的问题.因此就用 ViewTreeObserver进行对 layout_left设置宽度. ViewTreeObserver,这个类主要用于对布局文件的监听.强烈建议同学们参考这篇文章 [android ViewTreeObserver详细讲解](http://blog.csdn.net/jj120522/article/details/8097133)，相信让你对ViewTreeObserver有更一步的了解.其他的就是对 GestureDetector手势的应用，下面我把代码贴出来： ``` &lt;span class=&#34;keyword&#34;&gt;package&lt;/span&gt; com.jj.slidingmenu; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.app.Activity; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.os.AsyncTask; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.os.Bundle; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.util.Log; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.GestureDetector; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.KeyEvent; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.MotionEvent; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.View; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.ViewTreeObserver; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.ViewTreeObserver.OnPreDrawListener; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.Window; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.view.View.OnTouchListener; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.AdapterView; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.AdapterView.OnItemClickListener; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.ArrayAdapter; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.ImageView; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.LinearLayout; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.ListView; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.RelativeLayout; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.Toast; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; android.widget.LinearLayout.LayoutParams; &lt;span class=&#34;javadoc&#34;&gt;/*** * 滑动菜单 * * &lt;span class=&#34;javadoctag&#34;&gt;@author&lt;/span&gt; jjhappyforever... * */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;class&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;MainActivity&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;extends&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;Activity&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;implements&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;OnTouchListener&lt;/span&gt;, &lt;span class=&#34;title&#34;&gt;GestureDetector&lt;/span&gt;.&lt;span class=&#34;title&#34;&gt;OnGestureListener&lt;/span&gt; {&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; hasMeasured = &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;;&lt;span class=&#34;comment&#34;&gt;// 是否Measured.&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; LinearLayout layout_left; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; LinearLayout layout_right; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; ImageView iv_set; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; ListView lv_set; &lt;span class=&#34;javadoc&#34;&gt;/** 每次自动展开/收缩的范围 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; MAX_WIDTH = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;javadoc&#34;&gt;/** 每次自动展开/收缩的速度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;final&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;static&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; SPEED = &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; GestureDetector mGestureDetector;&lt;span class=&#34;comment&#34;&gt;// 手势&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; isScrolling = &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; mScrollX; &lt;span class=&#34;comment&#34;&gt;// 滑块滑动距离&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; window_width;&lt;span class=&#34;comment&#34;&gt;// 屏幕的宽度&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; String TAG = &lt;span class=&#34;string&#34;&gt;&#34;jj&#34;&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; String title[] = { &lt;span class=&#34;string&#34;&gt;&#34;待发送队列&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;同步分享设置&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;编辑我的资料&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;找朋友&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;告诉朋友&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;节省流量&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;推送设置&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;版本更新&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;意见反馈&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;积分兑换&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;精品应用&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;常见问题&#34;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#34;退出当前帐号&#34;&lt;/span&gt; }; &lt;span class=&#34;javadoc&#34;&gt;/*** * 初始化view */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; InitView() { layout_left = (LinearLayout) findViewById(R.id.layout_left); layout_right = (LinearLayout) findViewById(R.id.layout_right); iv_set = (ImageView) findViewById(R.id.iv_set); lv_set = (ListView) findViewById(R.id.lv_set); lv_set.setAdapter(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; ArrayAdapter&amp;lt;String&amp;gt;(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;, R.layout.item, R.id.tv_item, title)); lv_set.setOnItemClickListener(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; OnItemClickListener() { &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onItemClick(AdapterView&amp;lt;?&amp;gt; parent, View view, &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; position, &lt;span class=&#34;keyword&#34;&gt;long&lt;/span&gt; id) { Toast.makeText(MainActivity.&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;, title[position], &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;).show(); } }); layout_left.setOnTouchListener(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); iv_set.setOnTouchListener(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); mGestureDetector = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; GestureDetector(&lt;span class=&#34;keyword&#34;&gt;this&lt;/span&gt;); &lt;span class=&#34;comment&#34;&gt;// 禁用长按监听&lt;/span&gt; mGestureDetector.setIsLongpressEnabled(&lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;); getMAX_WIDTH(); } &lt;span class=&#34;javadoc&#34;&gt;/*** * 获取移动距离 移动的距离其实就是layout_left的宽度 */&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; getMAX_WIDTH() { ViewTreeObserver viewTreeObserver = layout_left.getViewTreeObserver(); &lt;span class=&#34;comment&#34;&gt;// 获取控件宽度&lt;/span&gt; viewTreeObserver.addOnPreDrawListener(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; OnPreDrawListener() { &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onPreDraw() { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (!hasMeasured) { window_width = getWindowManager().getDefaultDisplay() .getWidth(); RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams) layout_left .getLayoutParams(); &lt;span class=&#34;comment&#34;&gt;// layoutParams.width = window_width;&lt;/span&gt; layout_left.setLayoutParams(layoutParams); MAX_WIDTH = layout_right.getWidth(); Log.v(TAG, &lt;span class=&#34;string&#34;&gt;&#34;MAX_WIDTH=&#34;&lt;/span&gt; + MAX_WIDTH + &lt;span class=&#34;string&#34;&gt;&#34;width=&#34;&lt;/span&gt; + window_width); hasMeasured = &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } }); } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onCreate(Bundle savedInstanceState) { &lt;span class=&#34;keyword&#34;&gt;super&lt;/span&gt;.onCreate(savedInstanceState); requestWindowFeature(Window.FEATURE_NO_TITLE); setContentView(R.layout.main); InitView(); } &lt;span class=&#34;comment&#34;&gt;// 返回键&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onKeyDown(&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; keyCode, KeyEvent event) { &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (KeyEvent.KEYCODE_BACK == keyCode &amp;&amp; event.getRepeatCount() == &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams) layout_left .getLayoutParams(); &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (layoutParams.leftMargin &amp;lt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; AsynMove().execute(SPEED); &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; } } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;super&lt;/span&gt;.onKeyDown(keyCode, event); } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onTouch(View v, MotionEvent event) { &lt;span class=&#34;comment&#34;&gt;// 松开的时候要判断，如果不到半屏幕位子则缩回去，&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (MotionEvent.ACTION_UP == event.getAction() &amp;&amp; isScrolling == &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;) { RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams) layout_left .getLayoutParams(); &lt;span class=&#34;comment&#34;&gt;// 缩回去&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (layoutParams.leftMargin &amp;lt; -window_width / &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; AsynMove().execute(-SPEED); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; AsynMove().execute(SPEED); } } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; mGestureDetector.onTouchEvent(event); } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onDown(MotionEvent e) { mScrollX = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; isScrolling = &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;// 将之改为true，不然事件不会向下传递.&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onShowPress(MotionEvent e) { } &lt;span class=&#34;javadoc&#34;&gt;/*** * 点击松开执行 */&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onSingleTapUp(MotionEvent e) { RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams) layout_left .getLayoutParams(); &lt;span class=&#34;comment&#34;&gt;// 左移动&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (layoutParams.leftMargin &amp;gt;= &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; AsynMove().execute(-SPEED); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;// 右移动&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; AsynMove().execute(SPEED); } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; } &lt;span class=&#34;javadoc&#34;&gt;/*** * e1 是起点，e2是终点，如果distanceX=e1.x-e2.x&amp;gt;0说明向左滑动。反之亦如此. */&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onScroll(MotionEvent e1, MotionEvent e2, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; distanceX, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; distanceY) { isScrolling = &lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;; mScrollX += distanceX;&lt;span class=&#34;comment&#34;&gt;// distanceX:向左为正，右为负&lt;/span&gt; RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams) layout_left .getLayoutParams(); layoutParams.leftMargin -= mScrollX; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (layoutParams.leftMargin &amp;gt;= &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { isScrolling = &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;;&lt;span class=&#34;comment&#34;&gt;// 拖过头了不需要再执行AsynMove了&lt;/span&gt; layoutParams.leftMargin = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (layoutParams.leftMargin &amp;lt;= -MAX_WIDTH) { &lt;span class=&#34;comment&#34;&gt;// 拖过头了不需要再执行AsynMove了&lt;/span&gt; isScrolling = &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; layoutParams.leftMargin = -MAX_WIDTH; } layout_left.setLayoutParams(layoutParams); &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onLongPress(MotionEvent e) { } &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;boolean&lt;/span&gt; onFling(MotionEvent e1, MotionEvent e2, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; velocityX, &lt;span class=&#34;keyword&#34;&gt;float&lt;/span&gt; velocityY) { &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;false&lt;/span&gt;; } &lt;span class=&#34;class&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;AsynMove&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;extends&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;AsyncTask&lt;/span&gt;&amp;lt;&lt;span class=&#34;title&#34;&gt;Integer&lt;/span&gt;, &lt;span class=&#34;title&#34;&gt;Integer&lt;/span&gt;, &lt;span class=&#34;title&#34;&gt;Void&lt;/span&gt;&amp;gt; {&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; Void doInBackground(Integer... params) { &lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; times = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (MAX_WIDTH % Math.abs(params[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;]) == &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;)&lt;span class=&#34;comment&#34;&gt;// 整除&lt;/span&gt; times = MAX_WIDTH / Math.abs(params[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;]); &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; times = MAX_WIDTH / Math.abs(params[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;]) + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;;&lt;span class=&#34;comment&#34;&gt;// 有余数&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (&lt;span class=&#34;keyword&#34;&gt;int&lt;/span&gt; i = &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;; i &amp;lt; times; i++) { publishProgress(params[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;]); &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; { Thread.sleep(Math.abs(params[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;])); } &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (InterruptedException e) { e.printStackTrace(); } } &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;; } &lt;span class=&#34;javadoc&#34;&gt;/** * update UI */&lt;/span&gt; &lt;span class=&#34;annotation&#34;&gt;@Override&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;protected&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; onProgressUpdate(Integer... values) { RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams) layout_left .getLayoutParams(); &lt;span class=&#34;comment&#34;&gt;// 右移动&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (values[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;] &amp;gt; &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;) { layoutParams.leftMargin = Math.min(layoutParams.leftMargin + values[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;], &lt;span class=&#34;number&#34;&gt;&lt;/span&gt;); Log.v(TAG, &lt;span class=&#34;string&#34;&gt;&#34;移动右&#34;&lt;/span&gt; + layoutParams.rightMargin); } &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; { &lt;span class=&#34;comment&#34;&gt;// 左移动&lt;/span&gt; layoutParams.leftMargin = Math.max(layoutParams.leftMargin + values[&lt;span class=&#34;number&#34;&gt;&lt;/span&gt;], -MAX_WIDTH); Log.v(TAG, &lt;span class=&#34;string&#34;&gt;&#34;移动左&#34;&lt;/span&gt; + layoutParams.rightMargin); } layout_left.setLayoutParams(layoutParams); } } } 上面代码注释已经很明确，相信大家都看的明白，我就不过多解释了。效果图： 截屏出来有点卡，不过在手机虚拟机上是不卡的. ![](http://img0.tuicool.com/ziuuUn.gif) [源码下载](http://download.csdn.net/detail/jj120522/4670568) 怎么样，看着还行吧，我们在看下面一个示例： ![](http://img1.tuicool.com/vaYRbe.png) 简单说明一下，当你滑动的时候左边会跟着右边一起滑动，这个效果比上面那个酷吧，上面那个有点死板，其实实现起来也比较容易，只需要把我们上面那个稍微修改下，对layout_right也进行时时更新，这样就实现了这个效果了，如果上面那个理解了，这个很轻松就解决了，在这里我又遇到一个问题： 此时的listview的item监听不到手势，意思就是我左右滑动listview他没有进行滑动。 本人对touch众多事件监听拦截等熟悉度不够，因此这里我用到自己写的方法，也许比较麻烦，如果有更好的解决办法，请大家一定要分享哦，再次 thanks for you 了. 具体解决办法：我们重写listview,对此listview进行手势监听， 我们自定义一个接口来实现 ，具体代码如下： ``` package com.jj.slidingmenu;
import android.content.Context; import android.util.AttributeSet; import android.util.Log; import android.view.GestureDetector; import android.view.MotionEvent; import android.view.GestureDetector.OnGestureListener; import android.view.View; import android.widget.ListView; import android.widget.Toast;
public class MyListView extends ListView implements OnGestureListener {
private GestureDetector gd; // 事件状态 public static final char FLING_CLICK = ; public static final char FLING_LEFT = 1; public static final char FLING_RIGHT = 2; public static char flingState = FLING_CLICK;
private float distanceX;// 水平滑动的距离
private MyListViewFling myListViewFling;
public static boolean isClick = false;// 是否可以点击
public void setMyListViewFling(MyListViewFling myListViewFling) { this.myListViewFling = myListViewFling; }
public float getDistanceX() { return distanceX; }
public char getFlingState() { return flingState; }
private Context context;
public MyListView(Context context) { super(context);
}
public MyListView(Context context, AttributeSet attrs) { super(context, attrs); this.context = context; gd = new GestureDetector(this); }
/**
覆写此方法，以解决ListView滑动被屏蔽问题 */ @Override public boolean dispatchTouchEvent(MotionEvent event) { myListViewFling.doFlingOver(event);// 回调执行完毕. this.gd.onTouchEvent(event); &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;super&lt;/span&gt;.dispatchTouchEvent(event); }
@Override public boolean onTouchEvent(MotionEvent ev) { /*** * 当移动的时候 */ if (ev.getAction() == MotionEvent.ACTION_DOWN) isClick = true; if (ev.getAction() == MotionEvent.ACTION_MOVE) isClick = false; return super.onTouchEvent(ev); }
@Override public boolean onDown(MotionEvent e) { int position = pointToPosition((int) e.getX(), (int) e.getY()); if (position != ListView.INVALID_POSITION) { View child = getChildAt(position - getFirstVisiblePosition()); } return true; }
@Override public void onShowPress(MotionEvent e) {
}
@Override public boolean onSingleTapUp(MotionEvent e) {
&lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;false&lt;/span&gt;; }
@Override public boolean onScroll(MotionEvent e1, MotionEvent e2, float distanceX, float distanceY) { // 左滑动 if (distanceX &gt; ) { flingState = FLING_RIGHT; Log.v(&ldquo;jj&rdquo;, &ldquo;左distanceX=&quot; + distanceX); myListViewFling.doFlingLeft(distanceX);// 回调 // 右滑动. } else if (distanceX &lt; ) { flingState = FLING_LEFT; Log.v(&ldquo;jj&rdquo;, &ldquo;右distanceX=&quot; + distanceX); myListViewFling.doFlingRight(distanceX);// 回调 }
&lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;false&lt;/span&gt;; }
/***
上下文菜单 */ @Override public void onLongPress(MotionEvent e) { // System.out.println(&ldquo;Listview long press&rdquo;); // int position = pointToPosition((int) e.getX(), (int) e.getY()); // if (position != ListView.INVALID_POSITION) { // View child = getChildAt(position - getFirstVisiblePosition()); // if (child != null) { // showContextMenuForChild(child); // this.requestFocusFromTouch(); // } // // } } @Override public boolean onFling(MotionEvent e1, MotionEvent e2, float velocityX, float velocityY) {
&lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;false&lt;/span&gt;; }
/***
回调接口 @author jjhappyforever&hellip; */ interface MyListViewFling { void doFlingLeft(float distanceX);// 左滑动执行
&lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; doFlingRight(&lt;span class=&quot;keyword&quot;&gt;float&lt;/span&gt; distanceX);&lt;span class=&quot;comment&quot;&gt;// 右滑动执行&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; doFlingOver(MotionEvent event);&lt;span class=&quot;comment&quot;&gt;// 拖拽松开时执行&lt;/span&gt; }
