//创建聊天室
muc.create(“newroom2”);
//获得聊天室的配置表单
Form form=muc.getConfigurationForm();
//根据原始表单穿件一个要提交的新表单
Form submitForm=form.createAnswerForm();
//向要提交的表单添加默认答复
for(Interator fields=form.getFields();fields.hasNext()){
FormField field=(FormField) fields.next();
if(!FormField.TYPE_HIDDEN.equals(fields.getType())&amp;&amp;field.getVariable()!=null){
//设置默认值作为答复
submitForm.setDefaultAnswer(field.getVariable());
}
}
//设置聊天室的新拥有者
List oweners=new ArrayList();
oweners.add(“NewUser@stonechen”);
submitForm.setAnswer(“muc#foomconfig_roomowners”,oweners);
//发送已完成的表单（有默认值）到服务器来配置聊天室
muc.sendConfigurationForm(submitForm);
}catch(XMPPException e){
}
