//检测SipManager对象是否为空
if(mSipManager==null){//如果为空，则不进行热乎操作，直接返回
return;
}else{
try{
//不为空的情况
if(mSipProfile!=null){
//关闭相关对象
mSipManager.close(mSipProfile.getUriString());
}
}catch(Exception e){
}
}
}
