public final class IOUtil{
public staic final void readWrite(final InputStream remoteInput,final OutputStream remoteOutput,final InputStream localInput,final OutputStream localOutput){
//定义读写的线程
Thread read,writer;
//定义读线程的具体操作
reader=new Thread(){
@Override
public void run(){
int ch;
try{
//判断没被中断的时候
while(!interrupred()&amp;&amp;(ch=localInput.read())!=-1){
//写自己到远程输入里面
remoteOutput.write(ch);
//刷新发送
remoteOutput.flush();
}
}catch(IOException e){
}
}
};
//定义写线程的具体操作
reader=new Thread(){
@Override
public void run(){
int ch;
try{
//把数据从输入流复制到输出流
Util.copyStream(remoteInput,localOutput);
}catch(IOException e){
System.exit(1);
}
}
};
//设置Writer线程
writer.setPriority(Thread.currentThread().getPriority()+1);
//启动writer线程
writer.start();
//设置reader为后台运行
reader.setDaemon(true);
//启动readre线程
reader.start();
try{
//使得writer线程完成run（）方法后，在执行join（）方法后的代码
writer.join();
//中断reader线程
reader.interrupt();
}catch(InterruptedException e){
}
};
}

