t;/span&gt;); - jchar (*CallCharMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jshort (*CallShortMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jshort (*CallShortMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jshort (*CallShortMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jint (*CallIntMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jint (*CallIntMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jint (*CallIntMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jlong (*CallLongMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jlong (*CallLongMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jbooleanArray (*NewBooleanArray)(JNIEnv*, jsize); - jbyteArray (*NewByteArray)(JNIEnv*, jsize); - jcharArray (*NewCharArray)(JNIEnv*, jsize); - jshortArray (*NewShortArray)(JNIEnv*, jsize); - jintArray (*NewIntArray)(JNIEnv*, jsize); - jlongArray (*NewLongArray)(JNIEnv*, jsize); - jfloatArray (*NewFloatArray)(JNIEnv*, jsize); - jdoubleArray (*NewDoubleArray)(JNIEnv*, jsize); &lt;/div&gt; &lt;/div&gt; ## &lt;a name=&quot;t41&quot;&gt;&lt;/a&gt;2. JNI在Java和C语言之间传递int类型 &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **Java中定义的方法** : &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_java&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[java]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_21&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_21&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;comment&quot;&gt;//将Java中的两个int值 传给C语言, 进行相加后, 返回java语言 shuliang.han.ndkparameterpassing.DataProvider&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;public&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;native&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; add(&lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; x, &lt;span class=&quot;keyword&quot;&gt;int&lt;/span&gt; y); &lt;/div&gt; **C语言中定义的方法** :&lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_22&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_22&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#include &lt;jni.h&gt;&lt;/span&gt; - - &lt;span class=&quot;comment&quot;&gt;//方法签名, Java环境 和 调用native方法的类 必不可少, 后面的参数就是native方法的参数&lt;/span&gt; - jint Java_shuliang_han_ndkparameterpassing_DataProvider_add(JNIEnv * env, jobject obj, jint x, jint y) - { - &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; x + y; - } &lt;/div&gt; **使用NDK工具变异该c类库** :&lt;/div&gt; &lt;div&gt; 在cygwin中进入cygdrive, 然后**进入windows中相应的目录**, 执行 **/android-ndk-r9c/ndk-build** 命令, 即可完成编译; &lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140206151254187) &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## &lt;a name=&quot;t42&quot;&gt;&lt;/a&gt;3. NDK中C代码使用LogCat &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ### &lt;a name=&quot;t43&quot;&gt;&lt;/a&gt;(1) 引入头文件 &lt;div&gt; &lt;/div&gt; &lt;div&gt; **NDK中断点调试** : 断点调试在NDK中实现极其困难, 因此在这里我们一般都是打印日志; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **引入头文件** : 在C代码中引入下面的头文件; &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_23&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_23&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#include &lt;android/log.h&gt;&lt;/span&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#define LOG_TAG &amp;#8220;System.out&amp;#8221;&lt;/span&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#define LOGD(&amp;#8230;) __android_log_print(ANDROID_LOG_DEBUG, LOG_TAG, __VA_ARGS__)&lt;/span&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#define LOGI(&amp;#8230;) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)&lt;/span&gt; &lt;/div&gt; **头文件介绍** : log.h 是关于调用 LogCat日志文件;&lt;/div&gt; &lt;div&gt; &amp;#8212; **log.h头文件路径** : android-ndk-r9c\platforms\android-9\arch-arm\usr\include\android\log.h; &lt;/div&gt; &lt;div&gt; &amp;#8212; **主要方法** : __android_log_write, 下面有该方法的解析, 传入参数 日志等级 日志标签 日志内容; &lt;/div&gt; &lt;div&gt; &amp;#8212; **宏定义** : __android_log_write 方法太麻烦, 这里做出一个映射, LOGD(&amp;#8230;) 输出debug级别的日志, LOGI(&amp;#8230;) 输出Info级别的日志; &lt;/div&gt; &lt;div&gt; &amp;#8212;**LogCat日志级别** : verbose &lt; debug &lt; info &lt; warn &lt; error &lt; assert; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **使用到的log.h文件内容解析** : __android_log_write 方法中的日志等级参数就使用 枚举中的内容 &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_24&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_24&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;comment&quot;&gt;/*&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; * Android log priority values, in ascending priority order. 日志等级&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; */&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;typedef&lt;/span&gt; &lt;span class=&quot;keyword&quot;&gt;enum&lt;/span&gt; android_LogPriority { - ANDROID_LOG_UNKNOWN = 0, - ANDROID_LOG_DEFAULT, &lt;span class=&quot;comment&quot;&gt;/* only for SetMinPriority() */&lt;/span&gt; - ANDROID_LOG_VERBOSE, - ANDROID_LOG_DEBUG, - ANDROID_LOG_INFO, - ANDROID_LOG_WARN, - ANDROID_LOG_ERROR, - ANDROID_LOG_FATAL, - ANDROID_LOG_SILENT, &lt;span class=&quot;comment&quot;&gt;/* only for SetMinPriority(); must be last */&lt;/span&gt; - } android_LogPriority; - - &lt;span class=&quot;comment&quot;&gt;/*&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; * Send a simple string to the log. 向LogCat中输出日志 &lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; 参数介绍: 日志优先级 , 日志标签 , 日志内容&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; */&lt;/span&gt; - &lt;span class=&quot;datatypes&quot;&gt;int&lt;/span&gt; __android_log_write(&lt;span class=&quot;datatypes&quot;&gt;int&lt;/span&gt; prio, &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt; *tag, &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt; *text); &lt;/div&gt; **C语言中输入输出函数占位符介绍** :&lt;/div&gt; &lt;div&gt; &lt;table border=&quot;1&quot; width=&quot;200&quot; cellspacing=&quot;1&quot; cellpadding=&quot;1&quot;&gt; &lt;tr&gt; &lt;td&gt; 占位符 &lt;/td&gt; &lt;td&gt; 数据类型 &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; %d &lt;/td&gt; &lt;td&gt; int &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; %ld &lt;/td&gt; &lt;td&gt; long int &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; %c &lt;/td&gt; &lt;td&gt; char &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; %f &lt;/td&gt; &lt;td&gt; float &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; &amp;lf &lt;/td&gt; &lt;td&gt; double &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; %x &lt;/td&gt; &lt;td&gt; 十六进制 &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; %O &lt;/td&gt; &lt;td&gt; 八进制 &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt; %s &lt;/td&gt; &lt;td&gt; 字符串 &lt;/td&gt; &lt;/tr&gt; &lt;/table&gt; &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ### &lt;a name=&quot;t44&quot;&gt;&lt;/a&gt;(2) Android.mk增加liblog.so动态库 &lt;div&gt; &lt;/div&gt; &lt;div&gt; **在该make配置文件中, 增加一行** : LOCAL_LDLIBS += -llog , 该语句添加在 LOCAL_SRC_FILES 语句下面一行; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **完整的Android.mk文件** : &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_plain&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[plain]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_25&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_25&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - LOCAL_PATH := $(call my-dir) - - include $(CLEAR_VARS) - - LOCAL_MODULE := DataProvider - LOCAL_SRC_FILES := DataProvider.c - #增加log函数对应的函数库 liblog.so libthread_db.a - LOCAL_LDLIBS += -llog -lthread_db - include $(BUILD_SHARED_LIBRARY) &lt;/div&gt; &lt;/div&gt; &lt;div&gt; **函数库位置** : android-ndk-r9c\platforms\android-9\arch-arm\usr\lib; &lt;/div&gt; &lt;div&gt; **函数库截图** : 从该目录下的 liglog.so可以看出, 存在该库; &lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140206154355906) &lt;/div&gt; &lt;div&gt; **引入函数库方法** : 使用 LOCAL_LDLIBS += -l函数库名, 注意**函数库名不带lib前缀** 和**.so 后缀**, 同时可以添加多个库, 使用 -l库1 -l库2 -库3 ; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ### &lt;a name=&quot;t45&quot;&gt;&lt;/a&gt;(3) 编译执行 &lt;div&gt; &lt;/div&gt; &lt;div&gt; **根据(1) 中的占位符, 编写打印日志代码**: &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_26&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_26&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;comment&quot;&gt;//Java中的int对应的是C语言中的long类型, 对应JNI中的jint类型, C语言中&lt;/span&gt; - LOGI(&lt;span class=&quot;string&quot;&gt;&amp;#8220;JNI_日志 : x = %ld , y = %ld&amp;#8221;&lt;/span&gt; , x , y); &lt;/div&gt; **最终的包含打印日志的完整代码** : 注意, 这里有一处可能错误, 如果是32位机器, int类型占位符使用 %d 即可;&lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_27&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_27&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#include &lt;jni.h&gt;&lt;/span&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#include &lt;android/log.h&gt;&lt;/span&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#define LOG_TAG &amp;#8220;System.out&amp;#8221;&lt;/span&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#define LOGD(&amp;#8230;) __android_log_print(ANDROID_LOG_DEBUG, LOG_TAG, __VA_ARGS__)&lt;/span&gt; - &lt;span class=&quot;preprocessor&quot;&gt;#define LOGI(&amp;#8230;) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)&lt;/span&gt; - - - &lt;span class=&quot;comment&quot;&gt;//方法签名, Java环境 和 调用native方法的类 必不可少, 后面的参数就是native方法的参数&lt;/span&gt; - jint Java_shuliang_han_ndkparameterpassing_DataProvider_add(JNIEnv * env, jobject obj, jint x, jint y) - { - &lt;span class=&quot;comment&quot;&gt;//Java中的int对应的是C语言中的long类型, 对应JNI中的jint类型, C语言中&lt;/span&gt; - LOGI(&lt;span class=&quot;string&quot;&gt;&amp;#8220;JNI_日志 : x = %ld , y = %ld&amp;#8221;&lt;/span&gt; , x , y); - &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; x + y; - } &lt;/div&gt; **重新编译C文件** : 执行 **/android-ndk-r9c/ndk-build**命令;&lt;/div&gt; &lt;div&gt; &amp;#8212; **第一次编译** : 出现警告, long int占位符行不通, 注意区分机器位长, 64位 与 32位不同, 这样编译出现的结果就不会打印日志; &lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140206155158937) &lt;/div&gt; &lt;div&gt; &amp;#8212; **第二次编译** : 将占位符改为 %d ; &lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140206160147875) &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **执行按钮之后打印的日志** : 虽然有乱码, 不过显示出来了; &lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140206160218625) &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140206184130671) &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## &lt;a name=&quot;t46&quot;&gt;&lt;/a&gt;4. 字符串处理 &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **Java中的String转为C语言中的char字符串** : 下面的工具方法可以在C程序中解决这个问题; &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.c