 class=&quot;comment&quot;&gt;// String .getByte(&amp;#8220;GB2312&amp;#8221;);&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;comment&quot;&gt;//获取数组的长度&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;jsize alen = (*env)-&gt;GetArrayLength(env, barr); - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;comment&quot;&gt;//获取数组中的所有的元素 , 存放在 jbyte*数组中&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;jbyte* ba = (*env)-&gt;GetByteArrayElements(env, barr, JNI_FALSE); - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;comment&quot;&gt;//将Java数组中所有元素拷贝到C的char*数组中, 注意C语言数组结尾要加一个 &amp;#8216;\0&amp;#8217;&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;keyword&quot;&gt;if&lt;/span&gt; (alen &gt; 0) { - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;rtn = (&lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;*) malloc(alen + 1); &lt;span class=&quot;comment&quot;&gt;//new char[alen+1]; &amp;#8220;\0&amp;#8221;&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;memcpy(rtn, ba, alen); - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;rtn[alen] = 0; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;} - &lt;span style=