/span&gt; * 获取String中定义的方法 getBytes(), 该方法的参数是 String类型的, 返回值是 byte[]数组&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt;&lt;span style=&amp;#8221;white-space:pre&amp;#8221;&gt; &lt;/span&gt; * &amp;#8220;(Ljava/lang/String;)[B&amp;#8221; 方法前面解析 :&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt;&lt;span style=&amp;#8221;white-space:pre&amp;#8221;&gt; &lt;/span&gt; * &amp;#8212; Ljava/lang/String; 表示参数是String字符串&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt;&lt;span style=&amp;#8221;white-space:pre&amp;#8221;&gt; &lt;/span&gt; * &amp;#8212; [B : 中括号表示这是一个数组, B代表byte类型, 返回值是一个byte数组&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt;&lt;span style=&amp;#8221;white-space:pre&amp;#8221;&gt; &lt;/span&gt; */&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;jmethodID mid = (*env)-&gt;GetMethodID(env, clsstring, &lt;span class=&quot;string&quot;&gt;&amp;#8220;getBytes&amp;#8221;&lt;/span&gt;, - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;string&quot;&gt;&amp;#8220;(Ljava/lang/String;)[B&amp;#8221;&lt;/span&gt;); - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;comment&quot;&gt;//调用Java中的getBytes方法, 传入参数介绍 参数②表示调用该方法的对象, 参数③表示方法id , 参数④表示方法参数&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;jbyteArray barr = (jbyteArray)(*env)-&gt;CallObjectMethod(env, jstr, mid, - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;strencode); &lt;span class=&quot;comment&quot;&gt;// String .getByte(&amp;#8220;GB2312&amp;#8221;);&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;comment&quot;&gt;//获取数组的长度&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;jsize alen = (*env)-&gt;GetArrayLength(env, barr); - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;comment&quot;&gt;//获取数组中的所有的元素 , 存放在 jbyte*数组中&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;jbyte* ba = (*env)-&gt;GetByteArrayElements(env, barr, JNI_FALSE); - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;comment&quot;&gt;//将Java数组中所有元素拷贝到C的char*数组中, 注意C语言数组结尾要加一个 &amp;#8216;\0&amp;#8217;&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;&lt;span class=&quot;keyword&quot;&gt;if&lt;/span&gt; (alen &gt; 0) { - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;rtn = (&lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;*) malloc(alen + 1); &lt;span class=&quot;comment&quot;&gt;//new char[alen+1]; &amp;#8220;\0&amp;#8221;&lt;/span&gt; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;memcpy(rtn, ba, alen); - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;rtn[alen] = 0; - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;} - &lt;span style=&lt;span class=&quot;string&quot;&gt;&amp;#8220;white-space:pre&amp;#8221;&lt;/span&gt;&gt; &lt;/span&gt;(*env)-&gt;ReleaseByteArrayElements(env, barr, ba, 0); &lt;span class=&quot;comment&quot;&gt;//释