n&gt;, len); - - &lt;span class=&quot;comment&quot;&gt;//如果长度为0, 返回arr&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;if&lt;/span&gt;(len == 0) - &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; arr; - - &lt;span class=&quot;comment&quot;&gt;//如果长度大于0, 那么获取数组中的每个元素&lt;/span&gt; - jint* p = (*env)-&gt;GetIntArrayElements(env, arr, 0); - - &lt;span class=&quot;comment&quot;&gt;//打印出数组中每个元素的值&lt;/span&gt; - &lt;span class=&quot;datatypes&quot;&gt;int&lt;/span&gt; i = 0; - &lt;span class=&quot;keyword&quot;&gt;for&lt;/span&gt;(; i &lt; len; i ++) - { - LOGI(&lt;span class=&quot;string&quot;&gt;&amp;#8220;arr[%d] = %d&amp;#8221;&lt;/span&gt;, i, *(p + i)); - } - - &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; arr; - - } &lt;/div&gt; &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; ## &lt;a name=&quot;t50&quot;&gt;&lt;/a&gt;8. 上传代码到GitHub **创建新项目** : han1202012/NDKParameterPassing ; — SSH地址 : git@github.com:han1202012/NDKParameterPassing.git ; — HTTP地址 : https://github.com/han1202012/NDKParameterPassing.git ;
&lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; # &lt;a name=&quot;t51&quot;&gt;&lt;/a&gt;五. C语言代码回调Java方法 &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **C语言回调Java方法场景** : &lt;/div&gt; &lt;div&gt; &amp;#8212; **复用方法** : 使用Java对象, 复用Java中的方法; &lt;/div&gt; &lt;div&gt; &amp;#8212; **激活Java** : C程序后台运行, 该后台程序一直运行, 某个时间出发后需要启动Java服务, 激活Android中的某个界面, 例如使用Intent启动一个Activity; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## &lt;a name=&quot;t52&quot;&gt;&lt;/a&gt;1. C代码回调Java方法的流程 &lt;div&gt; &lt;/div&gt; ### &lt;a name=&quot;t53&quot;&gt;&lt;/a&gt;(1) 找到java对应的Class &lt;div&gt; &lt;/div&gt; &lt;div&gt; 创建一个char*数组, 然后使用jni.h中提供的FindClass方法获取jclass返回值; &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_47&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_47&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;comment&quot;&gt;//DataProvider完整类名 shulaing.han.ndk_callback.DataProvider&lt;/span&gt; - &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;* classname = &lt;span class=&quot;string&quot;&gt;&amp;#8220;shulaing/han/ndk_callback/DataProvider&amp;#8221;&lt;/span&gt;; - - - jclass dpclazz = (*env)-&gt;FindClass(env, classname); &lt;/div&gt; ### &lt;a name=&quot;t54&quot;&gt;&lt;/a&gt;(2) 找到要调用的方法的methodID &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; 使用jni.h中提供的GetMethodID方法, 获取jmethodID, 传入参数 ①JNIEnv指针 ②Class对象 ③ 方法名 ④方法签名, 在这里方法名和方法签名确定一个方法, 方法签名就是方法的返回值 与 参数的唯一标示; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_48&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_48&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;comment&quot;&gt;//参数介绍 : 第二个参数是Class对象, 第三个参数是方法名,第四个参数是方法的签名, 获取到调用的method&lt;/span&gt; - jmethodID methodID = (*env)-&gt;GetMethodID(env, dpclazz, &lt;span class=&quot;string&quot;&gt;&amp;#8220;Add&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;(II)I&amp;#8221;&lt;/span&gt;); &lt;/div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **找到静态方法** : 如果方法是静态的, 就使用GetStaticMethod方法获取 &lt;/div&gt; &lt;div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_49&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_49&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - jmethodID GetStaticMethodID(jclass clazz, &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;* name, &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;* sig) - { &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; functions-&gt;GetStaticMethodID(&lt;span class=&quot;keyword&quot;&gt;this&lt;/span&gt;, clazz, name, sig); } &lt;/div&gt; &lt;/div&gt; ### &lt;a name=&quot;t55&quot;&gt;&lt;/a&gt;(3) 在C语言中调用相应方法 &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **普通方法** : CallTypeMethod , 其中的Type随着返回值类型的不同而改变; &lt;/div&gt; &lt;div&gt; **参数介绍** : ① JNIEnv指针 ②调用该native方法的对象 ③方法的methodID ④⑤&amp;#8230; 后面是可变参数, 这些参数是 &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_50&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_50&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - jmethodID (*GetMethodID)(JNIEnv*, jclass, &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;*, &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;*); - - jobject (*CallObjectMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jobject (*CallObjectMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jobject (*CallObjectMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jboolean (*CallBooleanMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jboolean (*CallBooleanMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jboolean (*CallBooleanMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jbyte (*CallByteMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jbyte (*CallByteMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jbyte (*CallByteMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jchar (*CallCharMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jchar (*CallCharMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jchar (*CallCharMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jshort (*CallShortMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jshort (*CallShortMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jshort (*CallShortMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jint (*CallIntMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jint (*CallIntMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jint (*CallIntMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jlong (*CallLongMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - jlong (*CallLongMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - jlong (*CallLongMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); - jfloat (*CallFloatMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;) __NDK_FPABI__; - jfloat (*CallFloatMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;) __NDK_FPABI__; - jfloat (*CallFloatMethodA)(JNIEnv*, jobject, jmethodID, jvalue*) __NDK_FPABI__; - jdouble (*CallDoubleMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;) __NDK_FPABI__; - jdouble (*CallDoubleMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;) __NDK_FPABI__; - jdouble (*CallDoubleMethodA)(JNIEnv*, jobject, jmethodID, jvalue*) __NDK_FPABI__; - &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; (*CallVoidMethod)(JNIEnv*, jobject, jmethodID, &amp;#8230;); - &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; (*CallVoidMethodV)(JNIEnv*, jobject, jmethodID, &lt;span class=&quot;datatypes&quot;&gt;va_list&lt;/span&gt;); - &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt; (*CallVoidMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); &lt;/div&gt; **静态方法** : CallStaticTypeMethod, 其中的Type随着返回值类型不同而改变;&lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## &lt;a name=&quot;t56&quot;&gt;&lt;/a&gt;2. 一些基本代码编写 &lt;div&gt; &lt;/div&gt; &lt;div&gt; **Java代码** : 定义**一个callCcode本地方法**, 以及**三个Java方法**, 在jni中使用本地方法调用Java中的方法; &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_java&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[java]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_51&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;appli