;struct&lt;/span&gt; { - &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;* name; &lt;span class=&quot;comment&quot;&gt;//Java层Native函数方法名&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;const&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;char&lt;/span&gt;* signature; &lt;span class=&quot;comment&quot;&gt;//Java层Native函数的签名&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt;* fnPtr; &lt;span class=&quot;comment&quot;&gt;//JNI层实现的方法&lt;/span&gt; - } JNINativeMethod; &lt;/div&gt; . &lt;/div&gt; &lt;div&gt; **JNINativeMethod类型数据** : 在android_util_Log.cpp 中定义了一个该类型的数组 : &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_76&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_76&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;comment&quot;&gt;/*&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; * JNI registration.&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; */&lt;/span&gt; - &lt;span class=&quot;keyword&quot;&gt;static&lt;/span&gt; JNINativeMethod gMethods[] = { - &lt;span class=&quot;comment&quot;&gt;/* name, signature, funcPtr */&lt;/span&gt; - { &lt;span class=&quot;string&quot;&gt;&amp;#8220;isLoggable&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;(Ljava/lang/String;I)Z&amp;#8221;&lt;/span&gt;, (&lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt;*) android_util_Log_isLoggable }, - { &lt;span class=&quot;string&quot;&gt;&amp;#8220;println_native&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;(IILjava/lang/String;Ljava/lang/String;)I&amp;#8221;&lt;/span&gt;, (&lt;span class=&quot;keyword&quot;&gt;void&lt;/span&gt;*) android_util_Log_println_native }, - }; &lt;/div&gt; **JNINativeMethod结构体作用** : JNINativeMethod是一个结构体类型, 声明了Native方法 与 JNI方法 的映射关系;&lt;/div&gt; &lt;div&gt; &amp;#8212; **解析上面的数组中的元素** : &lt;/div&gt; &lt;div&gt; &amp;#8212; **Native方法** : &amp;#8220;isLoggable&amp;#8221; 是Java中声明的Native方法; &lt;/div&gt; &lt;div&gt; &amp;#8212; **方法签名** : &amp;#8220;(Ljava/lang/String;I)Z&amp;#8221; 表示该方法的签名, 参数是String类型 和 int类型, Z 表示 boolean类型; &lt;/div&gt; &lt;div&gt; &amp;#8212; **JNI方法** : (void*) android_util_Log_isLoggable 表示JNI层实现的方法指针; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## &lt;a name=&quot;t67&quot;&gt;&lt;/a&gt;4. 注册JNI方法到虚拟机中 &lt;div&gt; **映射关系体现到虚拟机中** : 在android_util_Log.cpp 中存在这样的方法 : &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_77&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_77&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;datatypes&quot;&gt;int&lt;/span&gt; register_android_util_Log(JNIEnv* env) - { - jclass clazz = env-&gt;FindClass(&lt;span class=&quot;string&quot;&gt;&amp;#8220;android/util/Log&amp;#8221;&lt;/span&gt;); - - &lt;span class=&quot;keyword&quot;&gt;if&lt;/span&gt; (clazz == NULL) { - LOGE(&lt;span class=&quot;string&quot;&gt;&amp;#8220;Can&amp;#8217;t find android/util/Log&amp;#8221;&lt;/span&gt;); - &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; -1; - } - - levels.verbose = env-&gt;GetStaticIntField(clazz, env-&gt;GetStaticFieldID(clazz, &lt;span class=&quot;string&quot;&gt;&amp;#8220;VERBOSE&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;I&amp;#8221;&lt;/span&gt;)); - levels.debug = env-&gt;GetStaticIntField(clazz, env-&gt;GetStaticFieldID(clazz, &lt;span class=&quot;string&quot;&gt;&amp;#8220;DEBUG&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;I&amp;#8221;&lt;/span&gt;)); - levels.info = env-&gt;GetStaticIntField(clazz, env-&gt;GetStaticFieldID(clazz, &lt;span class=&quot;string&quot;&gt;&amp;#8220;INFO&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;I&amp;#8221;&lt;/span&gt;)); - levels.warn = env-&gt;GetStaticIntField(clazz, env-&gt;GetStaticFieldID(clazz, &lt;span class=&quot;string&quot;&gt;&amp;#8220;WARN&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;I&amp;#8221;&lt;/span&gt;)); - levels.error = env-&gt;GetStaticIntField(clazz, env-&gt;GetStaticFieldID(clazz, &lt;span class=&quot;string&quot;&gt;&amp;#8220;ERROR&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;I&amp;#8221;&lt;/span&gt;)); - levels.assert = env-&gt;GetStaticIntField(clazz, env-&gt;GetStaticFieldID(clazz, &lt;span class=&quot;string&quot;&gt;&amp;#8220;ASSERT&amp;#8221;&lt;/span&gt;, &lt;span class=&quot;string&quot;&gt;&amp;#8220;I&amp;#8221;&lt;/span&gt;)); - - &lt;span class=&quot;keyword&quot;&gt;return&lt;/span&gt; AndroidRuntime::registerNativeMethods(env, &lt;span class=&quot;string&quot;&gt;&amp;#8220;android/util/Log&amp;#8221;&lt;/span&gt;, gMethods, NELEM(gMethods)); - } - - }; &lt;span class=&quot;comment&quot;&gt;// namespace android&lt;/span&gt; &lt;/div&gt; **核心方法** : 该函数调用了 AndroidRuntime::registerNativeMethods(env, &amp;#8220;android/util/Log&amp;#8221;, gMethods, NELEM(gMethods)) 方法注册JNI方法;&lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **register_android_util_Log调用时机** : 该函数是在Android系统启动的时候, 通过AndroidRuntime.cpp中的register_jni_proocs方法执行, 执行该方法的时候会将 Native方法 与 JNI方法 的函数映射关系注册给 Dalvik 虚拟机; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## &lt;a name=&quot;t68&quot;&gt;&lt;/a&gt;5. 解析registerNativeMethod函数 &lt;div&gt; &lt;/div&gt; &lt;div&gt; **该函数定义在AndroidRuntime.cpp中** : 该文件的路径在 \frameworks\base\core\jni\AndroidRuntime.cpp ; &lt;/div&gt; &lt;div&gt; &lt;div class=&quot;dp-highlighter bg_cpp&quot;&gt; &lt;div class=&quot;bar&quot;&gt; &lt;div class=&quot;tools&quot;&gt; **[cpp]** [view plain](http://blog.csdn.net/shulianghan/article/details/18964835#)[copy](http://blog.csdn.net/shulianghan/article/details/18964835#)[![在CODE上查看代码片](https://code.csdn.net/assets/CODE_ico.png)](https://code.csdn.net/snippets/181707)[![派生到我的代码片](https://code.csdn.net/assets/ico_fork.svg)](https://code.csdn.net/snippets/181707/fork) &lt;div&gt; &lt;embed id=&quot;ZeroClipboardMovie_78&quot; src=&quot;http://static.blog.csdn.net/scripts/ZeroClipboard/ZeroClipboard.swf&quot; type=&quot;application/x-shockwave-flash&quot; width=&quot;18&quot; height=&quot;18&quot; align=&quot;middle&quot; name=&quot;ZeroClipboardMovie_78&quot;&gt; &lt;/embed&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span class=&quot;comment&quot;&gt;/*&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; * Register native methods using JNI.&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt; */&lt;/span&gt; - &lt;span class=&quot;comment&quot;&gt;/*static*/&lt;/span&gt; &lt;span class=&quot;datatypes&quot;&gt;int&lt;/span&gt; AndroidRuntime::register