&amp;#8212;**DataProvider.c 主程序源码** :&lt;/div&gt; &lt;div&gt; ``` #include &amp;lt;jni.h&amp;gt; #include &amp;lt;string.h&amp;gt; #include &amp;lt;android/log.h&amp;gt; #define LOG_TAG &#34;System.out&#34; #define LOGD(...) __android_log_print(ANDROID_LOG_DEBUG, LOG_TAG, __VA_ARGS__) #define LOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__) // java中的jstring, 转化为c的一个字符数组 char* Jstring2CStr(JNIEnv* env, jstring jstr) { //声明了一个字符串变量 rtn char* rtn = NULL; //找到Java中的String的Class对象 jclass clsstring = (*env)-&amp;gt;FindClass(env, &#34;java/lang/String&#34;); //创建一个Java中的字符串 &#34;GB2312&#34; jstring strencode = (*env)-&amp;gt;NewStringUTF(env, &#34;GB2312&#34;); /* * 获取String中定义的方法 getBytes(), 该方法的参数是 String类型的, 返回值是 byte[]数组 * &#34;(Ljava/lang/String;)[B&#34; 方法前面解析 : * -- Ljava/lang/String; 表示参数是String字符串 * -- [B : 中括号表示这是一个数组, B代表byte类型, 返回值是一个byte数组 */ jmethodID mid = (*env)-&amp;gt;GetMethodID(env, clsstring, &#34;getBytes&#34;, &#34;(Ljava/lang/String;)[B&#34;); //调用Java中的getBytes方法, 传入参数介绍 参数②表示调用该方法的对象, 参数③表示方法id , 参数④表示方法参数 jbyteArray barr = (jbyteArray)(*env)-&amp;gt;CallObjectMethod(env, jstr, mid, strencode); // String .getByte(&#34;GB2312&#34;); //获取数组的长度 jsize alen = (*env)-&amp;gt;GetArrayLength(env, barr); //获取数组中的所有的元素 , 存放在 jbyte*数组中 jbyte* ba = (*env)-&amp;gt;GetByteArrayElements(env, barr, JNI_FALSE); //将Java数组中所有元素拷贝到C的char*数组中, 注意C语言数组结尾要加一个 &#39;\0&#39; if (alen &amp;gt; 0) { rtn = (char*) malloc(alen + 1); //new char[alen+1]; &#34;\0&#34; memcpy(rtn, ba, alen); rtn[alen] = 0; } (*env)-&amp;gt;ReleaseByteArrayElements(env, barr, ba, 0); //释放内存 return rtn; } //方法签名, Java环境 和 调用native方法的类 必不可少, 后面的参数就是native方法的参数 jint Java_shuliang_han_ndkparameterpassing_DataProvider_add(JNIEnv * env, jobject obj, jint x, jint y) { //Java中的int对应的是C语言中的long类型, 对应JNI中的jint类型, C语言中 LOGI(&#34;JNI_log : x = %d , y = %d&#34; , x , y); return x + y; } jstring Java_shuliang_han_ndkparameterpassing_DataProvider_sayHelloInc(JNIEnv *env, jobject obj, jstring str) { char *p = (char*)Jstring2CStr(env, str); //打印Java传递过来的数据 LOGI(&#34;Java JNI string parameter is : %s&#34;, p); char *append = &#34;append&#34;; //strcat(dest, source) 函数可以将source字符串 添加到dest字符串后面 return (*env)-&amp;gt;NewStringUTF(env, strcat(p, append)); } jintArray Java_shuliang_han_ndkparameterpassing_DataProvider_intMethod(JNIEnv *env, jobject obj, jintArray arr) { //获取arr大小 int len = (*env)-&amp;gt;GetArrayLength(env, arr); //在LogCat中打印出arr的大小 LOGI(&#34;the length of array is %d&#34;, len); //如果长度为0, 返回arr if(len == 0) return arr; //如果长度大于0, 那么获取数组中的每个元素 jint* p = (*env)-&amp;gt;GetIntArrayElements(env, arr, 0); //打印出数组中每个元素的值 int i = 0; for(; i &amp;lt; len; i ++) { LOGI(&#34;arr[%d] = %d&#34;, i, *(p + i)); } return arr; } &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; ## 8. 上传代码到GitHub **创建新项目** : han1202012/NDKParameterPassing ; — SSH地址 : git@github.com:han1202012/NDKParameterPassing.git ; — HTTP地址 : https://github.com/han1202012/NDKParameterPassing.git ;
&lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; # 五. C语言代码回调Java方法 &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **C语言回调Java方法场景** : &lt;/div&gt; &lt;div&gt; &amp;#8212; **复用方法** : 使用Java对象, 复用Java中的方法; &lt;/div&gt; &lt;div&gt; &amp;#8212; **激活Java** : C程序后台运行, 该后台程序一直运行, 某个时间出发后需要启动Java服务, 激活Android中的某个界面, 例如使用Intent启动一个Activity; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## 1. C代码回调Java方法的流程 &lt;div&gt; &lt;/div&gt; ### (1) 找到java对应的Class &lt;div&gt; &lt;/div&gt; &lt;div&gt; 创建一个char*数组, 然后使用jni.h中提供的FindClass方法获取jclass返回值; &lt;/div&gt; &lt;div&gt; ``` //DataProvider完整类名 shulaing.han.ndk_callback.DataProvider char* classname = &quot;shulaing/han/ndk_callback/DataProvider&quot;; jclass dpclazz = (*env)-&amp;gt;FindClass(env, classname); ### (2) 找到要调用的方法的methodID &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; 使用jni.h中提供的GetMethodID方法, 获取jmethodID, 传入参数 ①JNIEnv指针 ②Class对象 ③ 方法名 ④方法签名, 在这里方法名和方法签名确定一个方法, 方法签名就是方法的返回值 与 参数的唯一标示; ``` //参数介绍 : 第二个参数是Class对象, 第三个参数是方法名,第四个参数是方法的签名, 获取到调用的method jmethodID methodID = (*env)-&amp;gt;GetMethodID(env, dpclazz, &#34;Add&#34;, &#34;(II)I&#34;); &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **找到静态方法** : 如果方法是静态的, 就使用GetStaticMethod方法获取 &lt;/div&gt; &lt;div&gt; &lt;div&gt; ``` jmethodID GetStaticMethodID(jclass clazz, const char* name, const char* sig) { return functions-&gt;GetStaticMethodID(this, clazz, name, sig); }
&lt;/div&gt; ### (3) 在C语言中调用相应方法 &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **普通方法** : CallTypeMethod , 其中的Type随着返回值类型的不同而改变; &lt;/div&gt; &lt;div&gt; **参数介绍** : ① JNIEnv指针 ②调用该native方法的对象 ③方法的methodID ④⑤&amp;#8230; 后面是可变参数, 这些参数是 &lt;/div&gt; &lt;div&gt; ``` jmethodID (*GetMethodID)(JNIEnv*, jclass, const char*, const char*); jobject (*CallObjectMethod)(JNIEnv*, jobject, jmethodID, ...); jobject (*CallObjectMethodV)(JNIEnv*, jobject, jmethodID, va_list); jobject (*CallObjectMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jboolean (*CallBooleanMethod)(JNIEnv*, jobject, jmethodID, ...); jboolean (*CallBooleanMethodV)(JNIEnv*, jobject, jmethodID, va_list); jboolean (*CallBooleanMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jbyte (*CallByteMethod)(JNIEnv*, jobject, jmethodID, ...); jbyte (*CallByteMethodV)(JNIEnv*, jobject, jmethodID, va_list); jbyte (*CallByteMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jchar (*CallCharMethod)(JNIEnv*, jobject, jmethodID, ...); jchar (*CallCharMethodV)(JNIEnv*, jobject, jmethodID, va_list); jchar (*CallCharMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jshort (*CallShortMethod)(JNIEnv*, jobject, jmethodID, ...); jshort (*CallShortMethodV)(JNIEnv*, jobject, jmethodID, va_list); jshort (*CallShortMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jint (*CallIntMethod)(JNIEnv*, jobject, jmethodID, ...); jint (*CallIntMethodV)(JNIEnv*, jobject, jmethodID, va_list); jint (*CallIntMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jlong (*CallLongMethod)(JNIEnv*, jobject, jmethodID, ...); jlong (*CallLongMethodV)(JNIEnv*, jobject, jmethodID, va_list); jlong (*CallLongMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jfloat (*CallFloatMethod)(JNIEnv*, jobject, jmethodID, ...) __NDK_FPABI__; jfloat (*CallFloatMethodV)(JNIEnv*, jobject, jmethodID, va_list) __NDK_FPABI__; jfloat (*CallFloatMethodA)(JNIEnv*, jobject, jmethodID, jvalue*) __NDK_FPABI__; jdouble (*CallDoubleMethod)(JNIEnv*, jobject, jmethodID, ...) __NDK_FPABI__; jdouble (*CallDoubleMethodV)(JNIEnv*, jobject, jmethodID, va_list) __NDK_FPABI__; jdouble (*CallDoubleMethodA)(JNIEnv*, jobject, jmethodID, jvalue*) __NDK_FPABI__; void (*CallVoidMethod)(JNIEnv*, jobject, jmethodID, ...); void (*CallVoidMethodV)(JNIEnv*, jobject, jmethodID, va_list); void (*CallVoidMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); **静态方法** : CallStaticTypeMethod, 其中的Type随着返回值类型不同而改变;&lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; ## 2. 一些基本代码编写 &lt;div&gt; &lt;/div&gt; &lt;div&gt; **Java代码** : 定义**一个callCcode本地方法**, 以及**三个Java方法**, 在jni中使用本地方法调用Java中的方法; &lt;/div&gt; &lt;div&gt; ``` package shulaing.han.ndk_callback;
public class DataProvider {
public native void callCcode(); //C调用java中空方法 shulaing.han.ndk_callback.DataProvider public void helloFromJava(){ System.out.println(&quot;hello from java&quot;); } //C调用java中的带两个int参数的方法 public int Add(int x,int y){ return x + y; } //C调用java中参数为string的方法 public void printString(String s){ System.out.println(s); } }
**生成头文件** : 进入 bin/classed目录, 使用 **javah shulaing.han.ndk_callback.DataProvider** 命令, 可以在bin/classes下生成头文件;&lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140207203856375) &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **头文件内容** : 文件名 : shulaing_han_ndk_callback_DataProvider.h ; &lt;/div&gt; &lt;div&gt; ``` /* DO NOT EDIT THIS FILE - it is machine generated */ #include &amp;lt;jni.h&amp;gt; /* Header for class shulaing_han_ndk_callback_DataProvider */ #ifndef _Included_shulaing_han_ndk_callback_DataProvider #define _Included_shulaing_han_ndk_callback_DataProvider #ifdef __cplusplus extern &#34;C&#34; { #endif /* * Class: shulaing_han_ndk_callback_DataProvider * Method: callCcode * Signature: ()V */ JNIEXPORT void JNICALL Java_shulaing_han_ndk_1callback_DataProvider_callCcode (JNIEnv *, jobject); #ifdef __cplusplus } #endif #endif **编写Android.mk文件** : 注意将LogCat日志输出系统动态库加入;&lt;/div&gt; &lt;div&gt; ``` LOCAL_PATH := (call my-dir)
include(CLEAR_VARS)
LOCAL_MODULE := jni LOCAL_SRC_FILES := jni.c #增加log函数对应的log库 LOCAL_LDLIBS += -llog
