**编写jni的C代码** : 注意加入LogCat相关导入的包;&lt;/div&gt; &lt;div&gt; ``` #include &#34;shulaing_han_ndk_callback_DataProvider.h&#34; #include &amp;lt;string.h&amp;gt; #include &amp;lt;android/log.h&amp;gt; #define LOG_TAG &#34;System.out&#34; #define LOGD(...) __android_log_print(ANDROID_LOG_DEBUG, LOG_TAG, __VA_ARGS__) #define LOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__) &lt;/div&gt; ## 3. C中回调Java的void返回值方法 &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &amp;#8212; **参数介绍** : 第二个参数是类的路径字符串, 如 &amp;#8220;/shuliang/han/ndk_callback/DataProvider&amp;#8221; ; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &amp;#8212; **参数介绍** : 第二个参数是 Java类的Class对象, 第三个参数是方法名, 第四个参数是Java方法的签名; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **方法签名生成工具** : javap , 使用javap -s 命令即可生成方法签名; &lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140207210214562) &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **进入bin/classed目录下** : 执行 javap -s shulaing.han.ndk_callback.DataProvider 命令, 即可显示出每个方法的签名; &lt;/div&gt; &lt;div&gt; ``` $ javap -s shulaing.han.ndk_callback.DataProvider Compiled from &ldquo;DataProvider.java&rdquo; public class shulaing.han.ndk_callback.DataProvider extends java.lang.Object{ public shulaing.han.ndk_callback.DataProvider(); Signature: ()V public native void callCcode(); Signature: ()V public void helloFromJava(); Signature: ()V public int Add(int, int); Signature: (II)I public void printString(java.lang.String); Signature: (Ljava/lang/String;)V }
**截图** :&lt;/div&gt; &lt;div&gt; ![](http://img.blog.csdn.net/20140207210837125) &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **方法签名介绍** : &lt;/div&gt; &lt;div&gt; &amp;#8212; **返回值null, 参数null** : void helloFromJava() 方法的签名是 &amp;#8220;()V&amp;#8221;, 括号里什么都没有代表参数为null, V代表返回值是void; &lt;/div&gt; &lt;div&gt; &amp;#8212; **返回值int, 参数两个int** : int Add(int x,int y) 方法的签名是 &amp;#8220;(II)I&amp;#8221;, 括号中II表示两个int类型参数, 右边括号外的I代表返回值是int类型; &lt;/div&gt; &lt;div&gt; &amp;#8212; **返回值null, 参数String** : void printString(String s) 方法签名是 &amp;#8220;(Ljava/lang/String;)V&amp;#8221;, 括号中的Ljava/lang/String; 表示参数是String类型, V表示返回值是void; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **jni.h中定义的回调Java方法的相关函数** : &lt;/div&gt; &lt;div&gt; ``` jmethodID (*GetMethodID)(JNIEnv*, jclass, const char*, const char*); jobject (*CallObjectMethod)(JNIEnv*, jobject, jmethodID, ...); jobject (*CallObjectMethodV)(JNIEnv*, jobject, jmethodID, va_list); jobject (*CallObjectMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jboolean (*CallBooleanMethod)(JNIEnv*, jobject, jmethodID, ...); jboolean (*CallBooleanMethodV)(JNIEnv*, jobject, jmethodID, va_list); jboolean (*CallBooleanMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jbyte (*CallByteMethod)(JNIEnv*, jobject, jmethodID, ...); jbyte (*CallByteMethodV)(JNIEnv*, jobject, jmethodID, va_list); jbyte (*CallByteMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jchar (*CallCharMethod)(JNIEnv*, jobject, jmethodID, ...); jchar (*CallCharMethodV)(JNIEnv*, jobject, jmethodID, va_list); jchar (*CallCharMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jshort (*CallShortMethod)(JNIEnv*, jobject, jmethodID, ...); jshort (*CallShortMethodV)(JNIEnv*, jobject, jmethodID, va_list); jshort (*CallShortMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jint (*CallIntMethod)(JNIEnv*, jobject, jmethodID, ...); jint (*CallIntMethodV)(JNIEnv*, jobject, jmethodID, va_list); jint (*CallIntMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jlong (*CallLongMethod)(JNIEnv*, jobject, jmethodID, ...); jlong (*CallLongMethodV)(JNIEnv*, jobject, jmethodID, va_list); jlong (*CallLongMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); jfloat (*CallFloatMethod)(JNIEnv*, jobject, jmethodID, ...) __NDK_FPABI__; jfloat (*CallFloatMethodV)(JNIEnv*, jobject, jmethodID, va_list) __NDK_FPABI__; jfloat (*CallFloatMethodA)(JNIEnv*, jobject, jmethodID, jvalue*) __NDK_FPABI__; jdouble (*CallDoubleMethod)(JNIEnv*, jobject, jmethodID, ...) __NDK_FPABI__; jdouble (*CallDoubleMethodV)(JNIEnv*, jobject, jmethodID, va_list) __NDK_FPABI__; jdouble (*CallDoubleMethodA)(JNIEnv*, jobject, jmethodID, jvalue*) __NDK_FPABI__; void (*CallVoidMethod)(JNIEnv*, jobject, jmethodID, ...); void (*CallVoidMethodV)(JNIEnv*, jobject, jmethodID, va_list); void (*CallVoidMethodA)(JNIEnv*, jobject, jmethodID, jvalue*); &lt;div&gt; &lt;/div&gt; **C语言代码** :&lt;/div&gt; &lt;div&gt; ``` #include &ldquo;shulaing_han_ndk_callback_DataProvider.h&rdquo; #include &lt;string.h&gt; #include &lt;android/log.h&gt; #define LOG_TAG &ldquo;System.out&rdquo; #define LOGD(&hellip;) __android_log_print(ANDROID_LOG_DEBUG, LOG_TAG, VA_ARGS) #define LOGI(&hellip;) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, VA_ARGS)
JNIEXPORT void JNICALL Java_shulaing_han_ndk_1callback_DataProvider_callCcode (JNIEnv * env, jobject obj) { //调用DataProvider对象中的helloFromJava()方法 //获取到某个对象, 获取对象中的方法, 调用获取到的方法 LOGI(&ldquo;in code&rdquo;); //DataProvider完整类名 shulaing.han.ndk_callback.DataProvider char* classname = &ldquo;shulaing/han/ndk_callback/DataProvider&rdquo;;
jclass dpclazz = (*env)-&amp;gt;FindClass(env, classname); if(dpclazz == 0) LOGI(&quot;class not find !!!&quot;); else LOGI(&quot;class find !!!&quot;); //参数介绍 : 第二个参数是Class对象, 第三个参数是方法名,第四个参数是方法的签名, 获取到调用的method jmethodID methodID = (*env)-&amp;gt;GetMethodID(env, dpclazz, &quot;helloFromJava&quot;, &quot;()V&quot;); if(methodID == 0) LOGI(&quot;method not find !!!&quot;); else LOGI(&quot;method find !!!&quot;); /* * 调用方法 void (*CallVoidMethod)(JNIEnv*, jobject, jmethodID, ...); * 参数介绍 : 后面的 ... 是可变参数, 如果该返回值void的方法有参数, 就将参数按照次序排列 */ LOGI(&quot;before call method&quot;); (*env)-&amp;gt;CallVoidMethod(env, obj, methodID); LOGI(&quot;after call method&quot;); }
