nv, dpclazz, &#34;printString&#34;, &#34;(Ljava/lang/String;)V&#34;); if(methodID == 0) LOGI(&#34;method not find !!!&#34;); else LOGI(&#34;method find !!!&#34;); /* * 调用方法 void (*CallVoidMethod)(JNIEnv*, jobject, jmethodID, ...); * 参数介绍 : 后面的 ... 是可变参数, 如果该返回值void的方法有参数, 就将参数按照次序排列 */ LOGI(&#34;before call method&#34;); (*env)-&amp;gt;CallVoidMethod(env, obj, methodID, (*env)-&amp;gt;NewStringUTF(env, &#34;printString method callback success!!&#34;)); LOGI(&#34;after call method&#34;); } /* * 实际开发的情况 * C代码工程师给我们 first.h first.c , 我们只需要将first.h引入, 然后就可以使用其中的方法了 */ JNIEXPORT void JNICALL Java_shulaing_han_ndk_1callback_DataProvider_callCcode2 (JNIEnv *env, jobject obj) { //调用DataProvider对象中的helloFromJava()方法 //获取到某个对象, 获取对象中的方法, 调用获取到的方法 LOGI(&#34;in code&#34;); //DataProvider完整类名 shulaing.han.ndk_callback.DataProvider char* classname = &#34;shulaing/han/ndk_callback/DataProvider&#34;; jclass dpclazz = (*env)-&amp;gt;FindClass(env, classname); if(dpclazz == 0) LOGI(&#34;class not find !!!&#34;); else LOGI(&#34;class find !!!&#34;); //参数介绍 : 第二个参数是Class对象, 第三个参数是方法名,第四个参数是方法的签名, 获取到调用的method jmethodID methodID = (*env)-&amp;gt;GetMethodID(env, dpclazz, &#34;Add&#34;, &#34;(II)I&#34;); if(methodID == 0) LOGI(&#34;method not find !!!&#34;); else LOGI(&#34;method find !!!&#34;); /* * 调用方法 void (*CallVoidMethod)(JNIEnv*, jobject, jmethodID, ...); * 参数介绍 : 后面的 ... 是可变参数, 如果该返回值void的方法有参数, 就将参数按照次序排列 */ LOGI(&#34;before call method&#34;); (*env)-&amp;gt;CallIntMethod(env, obj, methodID, 3, 5); LOGI(&#34;after call method&#34;); } &lt;/div&gt; ## 7. 将程序上传到GitHub中 &lt;div&gt; GitHub地址 : &lt;/div&gt; &lt;div&gt; &amp;#8212; SSH : git@github.com:han1202012/NDK_Callback.git &lt;/div&gt; &lt;div&gt; &amp;#8212; HTTP : https://github.com/han1202012/NDK_Callback.git &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; . &lt;/div&gt; &lt;div&gt; &lt;/div&gt; # 六. 实际开发中的环境 &lt;div&gt; &lt;/div&gt; &lt;div&gt; **这里举一个简单的小例子** : &lt;/div&gt; &lt;div&gt; &amp;#8212; **在实际开发中, C工程师会给我们c文件如下** : first.h first.c, 一个C主程序, 一个头文件, 我们只需要将这个头文件引入到jni中的C代码中即可, 在我们自定义生成的签名函数中调用 first.h中的方法; &lt;/div&gt; &lt;div&gt; &lt;/div&gt; &lt;div&gt; **first.h源码** : &lt;/div&gt; &lt;div&gt; ``` #ifndef FIRST_H #define FIRST_H
