gt; ThreadSafeClientConnManager(&lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold;&#34;&gt;params&lt;/span&gt;, schReg); &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold;&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold;&#34;&gt;new&lt;/span&gt; DefaultHttpClient(connMgr, &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold;&#34;&gt;params&lt;/span&gt;); } &lt;/div&gt; 转自：http://www.tuicool.com/articles/6NvEZj &amp;nbsp; # android httpClient 支持HTTPS的2种处理方式 &amp;nbsp; 转自[http://my.oschina.net/blackylin/blog/144136](http://my.oschina.net/blackylin/blog/144136) 参考[http://developer.android.com/training/articles/security-ssl.html#Concepts](http://developer.android.com/training/articles/security-ssl.html#Concepts) [http://www.ibm.com/developerworks/cn/java/j-lo-ssltls/](http://www.ibm.com/developerworks/cn/java/j-lo-ssltls/) &amp;nbsp; # &lt;a style=&quot;color: #336699;&quot; name=&quot;t0&quot;&gt;&lt;/a&gt;问题： 项目中Android https或http请求地址重定向为HTTPS的地址，相信很多人都遇到了这个异常(无终端认证)： javax.net.ssl.SSLPeerUnverifiedException: No peer certificate
# &lt;a style=&quot;color: #336699;&quot; name=&quot;t1&quot;&gt;&lt;/a&gt;解决过程： ## &lt;a style=&quot;color: #336699;&quot; name=&quot;t2&quot;&gt;&lt;/a&gt;1.没遇到过的问题，搜索吧，少年 log里出现这个异常，作者第一次遇到，不知道啥意思。看下字面意思，是ssl协议中没有终端认证。SSL?[![](http://my.oschina.net/js/ke/plugins/emoticons/images/14.gif)](http://my.oschina.net/js/ke/plugins/emoticons/images/14.gif)作者没用到ssl协议呀，只是通过httpClient请求一个重定向https的地址。 好吧，google下，知道了个差不多情况的帖子，http://www.eoeandroid.com/thread-161747-1-1.html。恩恩，一个不错的帖子，给出了个解决方案。照着来试下。添加个继承SSLSocketFactory的 自定义类。并在初始化httpclient支持https时，注册进去。看下面代码：
01 public class HttpClientHelper { 02 03 private static HttpClient httpClient; 04 05 private HttpClientHelper() { 06 } 07 08 public static synchronized HttpClient getHttpClient() { 09 10 if (null == httpClient) { 11 // 初始化工作 12 try { 13 KeyStore trustStore = KeyStore.getInstance(KeyStore 14 .getDefaultType()); 15 trustStore.load(null, null); 16 SSLSocketFactory sf = new SSLSocketFactoryEx(trustStore); 17 sf.setHostnameVerifier(SSLSocketFactory.ALLOW_ALL_HOSTNAME_VERIFIER); //允许所有主机的验证 18 19 HttpParams params = new BasicHttpParams(); 20 21 HttpProtocolParams.setVersion(params, HttpVersion.HTTP_1_1); 22 HttpProtocolParams.setContentCharset(params, 23 HTTP.DEFAULT_CONTENT_CHARSET); 24 HttpProtocolParams.setUseExpectContinue(params, true); 25 26 // 设置连接管理器的超时 27 ConnManagerParams.setTimeout(params, 10000); 28 // 设置连接超时 29 HttpConnectionParams.setConnectionTimeout(params, 10000); 30 // 设置socket超时 31 HttpConnectionParams.setSoTimeout(params, 10000); 32 33 // 设置http https支持 34 SchemeRegistry schReg = new SchemeRegistry(); 35 schReg.register(new Scheme(“http”, PlainSocketFactory 36 .getSocketFactory(), 80)); 37 schReg.register(new Scheme(“https”, sf, 443)); 38 39 ClientConnectionManager conManager = new ThreadSafeClientConnManager( 40 params, schReg); 41 42 httpClient = new DefaultHttpClient(conManager, params); 43 } catch (Exception e) { 44 e.printStackTrace(); 45 return new DefaultHttpClient(); 46 } 47 } 48 return httpClient; 49 } 50 51 } 52 53 class SSLSocketFactoryEx extends SSLSocketFactory { 54 55 SSLContext sslContext = SSLContext.getInstance(“TLS”); 56 57 public SSLSocketFactoryEx(KeyStore truststore) 58 throws NoSuchAlgorithmException, KeyManagementException, 59 KeyStoreException, UnrecoverableKeyException { 60 super(truststore); 61 62 TrustManager tm = new X509TrustManager() { 63 64 @Override 65 public java.security.cert.X509Certificate[] getAcceptedIssuers() { 66 return null; 67 } 68 69 @Override 70 public void checkClientTrusted( 71 java.security.cert.X509Certificate[] chain, String authType) 72 throws java.security.cert.CertificateException { 73 74 } 75 76 @Override 77 public void checkServerTrusted( 78 java.security.cert.X509Certificate[] chain, String authType) 79 throws java.security.cert.CertificateException { 80 81 } 82 }; 83 84 sslContext.init(null, new TrustManager[] { tm }, null); 85 } 86 87 @Override 88 public Socket createSocket(Socket socket, String host, int port, 89 boolean autoClose) throws IOException, UnknownHostException { 90 return sslContext.getSocketFactory().createSocket(socket, host, port, 91 autoClose); 92 } 93 94 @Override 95 public Socket createSocket() throws IOException { 96 return sslContext.getSocketFactory().createSocket(); 97 } 98 }
&lt;div id=&quot;highlighter_796606&quot; class=&quot;syntaxhighlighter &quot;&gt; &lt;div class=&quot;lines&quot;&gt; &lt;div class=&quot;line alt1&quot;&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; ok，run下，狂乱的点到测试按钮，深吸口气，盯着eclipse中的logat。咦？神奇的竟然没有报之前的&lt;span style=&quot;font-weight: 600;&quot;&gt; javax.net.ssl.SSLPeerUnverifiedException: No peer certificate&lt;/span&gt;的异常了。服务端的数据正常返回了。[![](http://my.oschina.net/js/ke/plugins/emoticons/images/13.gif)](http://my.oschina.net/js/ke/plugins/emoticons/images/13.gif),狂喜中&amp;#8230; &amp;nbsp; ## &lt;a style=&quot;color: #336699;&quot; name=&quot;t3&quot;&gt;&lt;/a&gt;2.了解并分析问题 狂喜中，得分析这问题诶。不然老大来问，啥情况？楞半天不知道咋说（[![](http://my.oschina.net/js/ke/plugins/emoticons/images/1.gif)](http://my.oschina.net/js/ke/plugins/emoticons/images/1.gif)作者就经常这样，所以吸取教训。所以的弄懂出现的问题，学习+汇报工作）。 思来想去，就是作者请求的是一个重定向https的地址。好吧，那就学习下https（之前被老大深深的教过，http就是request/response）。继续搜索吧，少年。下面总结下学习到的https知识。
### &lt;a style=&quot;color: #336699;&quot; name=&quot;t4&quot;&gt;&lt;/a&gt;2.1 https &amp;nbsp; HTTPS:超文本安全传输协议，和HTTP相比，多了一个SSL/TSL的认证过程，端口为443。（鄙视下之前说的) ** 作者没用到ssl协议呀，只是通过httpClient请求一个重定向https的地址 &lt;/blockquote&gt; &amp;nbsp; &lt;span style=&quot;font-weight: 600;&quot;&gt;1.peer终端发送一个request，https服务端把支持的加密算法等以证书的形式返回一个身份信息（包含ca颁发机构和加密公钥等）。&lt;/span&gt; &lt;span style=&quot;font-weight: 600;&quot;&gt;2.获取证书之后，验证证书合法性。&lt;/span&gt; &lt;span style=&quot;font-weight: 600;&quot;&gt;3.随机产生一个密钥，并以证书当中的公钥加密。&lt;/span&gt; &lt;span style=&quot;font-weight: 600;&quot;&gt;4.request https服务端，把用公钥加密过的密钥传送给https服务端。&lt;/span&gt; &lt;span style=&quot;font-weight: 600;&quot;&gt;5.https服务端用自己的密钥解密，获取随机值。&lt;/span&gt; &lt;span style=&quot;font-weight: 600;&quot;&gt;6.之后双方传送数据都用此密钥加密后通信。&lt;/span&gt; ``` 看下面一张网上的得来的https的时序图：
&amp;nbsp; [![](http://static.oschina.net/uploads/space/2013/0711/214828_8G6b_587911.png)](http://static.oschina.net/uploads/space/2013/0711/214828_8G6b_587911.png) &amp;nbsp; ### &lt;a style=&#34;color: #336699;&#34; name=&#34;t5&#34;&gt;&lt;/a&gt;2.2分析下出现问题的原因 &amp;nbsp; 好吧，大概的流程知道了。定位已经非常清楚了。在第2步验证证书时，无法验证。为啥无法验证呢？没有添加信任。详细参考下 [http://www.cnblogs.com/P_Chou/archive/2010/12/27/https-ssl-certification.html](http://www.cnblogs.com/P_Chou/archive/2010/12/27/https-ssl-certification.html)讲的非常清楚https-ssl的认证过程，膜拜下该作者[![](http://my.oschina.net/js/ke/plugins/emoticons/images/13.gif)](http://my.oschina.net/js/ke/plugins/emoticons/images/13.gif) &amp;nbsp; 这样想来，上面提供的解决方案就是添加默认信任全部证书。以此来通过接下来的通信。 ## &lt;a style=&#34;color: #336699;&#34; name=&#34;t6&#34;&gt;&lt;/a&gt;3.解决问题 但是，这样问题是解决了。但是觉得还是不带靠谱（信任全部证书[![](http://my.oschina.net/js/ke/plugins/emoticons/images/3.gif)](http://my.oschina.net/js/ke/plugins/emoticons/images/3.gif)有点危险）。继续噼噼啪啪的网上搜索一番。又找到了一种解决方案，其过程大致这样的： &lt;span style=&#34;font-weight: 600;&#34;&gt;1.浏览器访问https地址，保存提示的证书到本地，放到android项目中的assets目录。&lt;/span&gt; &lt;span style=&#34;font-weight: 600;&#34;&gt;2.导入证书，代码如下。&lt;/span&gt; &lt;span style=&#34;font-weight: 600;&#34;&gt;3.把证书添加为信任。&lt;/span&gt; 01 String requestHTTPSPage(String mUrl) { 02 InputStream ins = null; 03 String result = &amp;#8220;&amp;#8221;; 04 try { 05 ins = context.getAssets().open(&amp;#8220;app_pay.cer&amp;#8221;); //下载的证书放到项目中的assets目录中 06 CertificateFactory cerFactory = CertificateFactory 07 .getInstance(&amp;#8220;X.509&amp;#8221;); 08 Certificate cer = cerFactory.generateCertificate(ins); 09 KeyStore keyStore = KeyStore.getInstance(&amp;#8220;PKCS12&amp;#8221;, &amp;#8220;BC&amp;#8221;); 10 keyStore.load(null, null); 11 keyStore.setCertificateEntry(&amp;#8220;trust&amp;#8221;, cer); 12 13 SSLSocketFactory socketFactory = new SSLSocketFactory(keyStore); 14 Scheme sch = new Scheme(&amp;#8220;https&amp;#8221;, socketFactory, 443); 15 HttpClient mHttpClient = new DefaultHttpClient(); 16 mHttpClient.getConnectionManager().getSchemeRegistry() 17 .register(sch); 18 19 BufferedReader reader = null; 20 try { 21 Log.d(TAG, &amp;#8220;executeGet is in,murl:&amp;#8221; + mUrl); 22 HttpGet request = new HttpGet(); 23 request.setURI(new URI(mUrl)); 24 HttpResponse response = mHttpClient.execute(request); 25 if (response.getStatusLine().getStatusCode() != 200) { 26 request.abort(); 27 return result; 28 } 29 30 reader = new BufferedReader(new InputStreamReader(response 31 .getEntity().getContent())); 32 StringBuffer buffer = new StringBuffer(); 33 String line = null; 34 while ((line = reader.readLine()) != null) { 35 buffer.append(line); 36 } 37 result = buffer.toString(); 38 Log.d(TAG, &amp;#8220;mUrl=&amp;#8221; + mUrl + &amp;#8220;\nresult = &amp;#8221; + result); 39 } catch (Exception e) { 40 e.printStackTrace(); 41 } finally { 42 if (reader != null) { 43 reader.close(); 44 } 45 } 46 } catch (Exception e) { 47 // TODO: handle exception 48 } finally { 49 try { 50 if (ins != null) 51 ins.close(); 52 } catch (IOException e) { 53 e.printStackTrace(); 54 } 55 } 56 return result; 57 } 接着，验证下呗。吼吼，稀里糊涂的又可以了。感动的泪流满面。 &amp;nbsp; # &lt;a style=&#34;color: #336699;&#34; name=&#34;t7&#34;&gt;&lt;/a&gt;最后总结： 2种方法都解决了作者遇到的问题，这里记录下。以防下次遇到，希望能给遇到相同问题朋友有所参考帮助。 转自：http://blog.csdn.net/lihenair/article/details/17441169 &amp;nbsp; # &lt;strong&gt;Android 实现 HttpClient 请求Https** 如题，默认下，HttpClient是不能请求Https的，需要自己获取 &lt;div class=&#34;dp-highlighter bg_java&#34; style=&#34;color: #000000;&#34;&gt; &lt;div class=&#34;bar&#34;&gt; &lt;div class=&#34;tools&#34; style=&#34;color: silver;&#34;&gt; **[java]** [view plain](http://blog.csdn.net/heynine/article/details/8279304#)[copy](http://blog.csdn.net/heynine/article/details/8279304#) &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; &lt;/div&gt; - &lt;span style=&#34;color: black;&#34;&gt;&lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;static&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;final&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;int&lt;/span&gt; SET_CONNECTION_TIMEOUT = &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;5&lt;/span&gt; * &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;1000&lt;/span&gt;; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;private&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;static&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;final&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;int&lt;/span&gt; SET_SOCKET_TIMEOUT = &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;20&lt;/span&gt; * &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;1000&lt;/span&gt;; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;static&lt;/span&gt; HttpClient getNewHttpClient() { &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;try&lt;/span&gt; { &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; KeyStore trustStore = KeyStore.getInstance(KeyStore.getDefaultType()); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; trustStore.load(&lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;null&lt;/span&gt;, &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;null&lt;/span&gt;); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; SSLSocketFactory sf = &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;new&lt;/span&gt; MySSLSocketFactory(trustStore); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; sf.setHostnameVerifier(SSLSocketFactory.ALLOW_ALL_HOSTNAME_VERIFIER); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpParams params = &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;new&lt;/span&gt; BasicHttpParams(); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpConnectionParams.setConnectionTimeout(params, &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;10000&lt;/span&gt;); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpConnectionParams.setSoTimeout(params, &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;10000&lt;/span&gt;); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpProtocolParams.setVersion(params, HttpVersion.HTTP_1_1); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpProtocolParams.setContentCharset(params, HTTP.UTF_8); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; SchemeRegistry registry = &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;new&lt;/span&gt; SchemeRegistry(); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; registry.register(&lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;new&lt;/span&gt; Scheme(&lt;span class=&#34;string&#34; style=&#34;color: blue;&#34;&gt;&amp;#8220;http&amp;#8221;&lt;/span&gt;, PlainSocketFactory.getSocketFactory(), &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;80&lt;/span&gt;)); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; registry.register(&lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;new&lt;/span&gt; Scheme(&lt;span class=&#34;string&#34; style=&#34;color: blue;&#34;&gt;&amp;#8220;https&amp;#8221;&lt;/span&gt;, sf, &lt;span class=&#34;number&#34; style=&#34;color: #c00000;&#34;&gt;443&lt;/span&gt;)); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; ClientConnectionManager ccm = &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;new&lt;/span&gt; ThreadSafeClientConnManager(params, registry); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpConnectionParams.setConnectionTimeout(params, SET_CONNECTION_TIMEOUT); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpConnectionParams.setSoTimeout(params, SET_SOCKET_TIMEOUT); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; HttpClient client = &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;new&lt;/span&gt; DefaultHttpClient(ccm, params); &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;return&lt;/span&gt; client; &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; } &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;catch&lt;/span&gt; (Exception e) { &lt;/span&gt; - &lt;span style=&#34;color: black;&#34;&gt; &lt;span class=&#34;keyword&#34; style=&#34;font-weight: bold; color: #006699;&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;