d&quot; style=&quot;color: #859900;&quot;&gt;boolean&lt;/span&gt; &lt;span class=&quot;title&quot; style=&quot;color: #268bd2;&quot;&gt;onLongClick&lt;/span&gt;(View v) { &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; Toast.makeText(getApplicationContext(), &lt;span class=&quot;string&quot; style=&quot;color: #2aa198;&quot;&gt;&amp;#8220;onLongClick&amp;#8221;&lt;/span&gt;, Toast.LENGTH_SHORT).show(); &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; v.setTag(&lt;span class=&quot;string&quot; style=&quot;color: #2aa198;&quot;&gt;&amp;#8220;Test&amp;#8221;&lt;/span&gt;); &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;return&lt;/span&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;true&lt;/span&gt;; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; } &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; }); &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;private&lt;/span&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;static&lt;/span&gt; &lt;span class=&quot;class&quot;&gt;&lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;class&lt;/span&gt; &lt;span class=&quot;title&quot; style=&quot;color: #b58900;&quot;&gt;NonLongClickableUrlSpan&lt;/span&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;extends&lt;/span&gt; &lt;span class=&quot;title&quot; style=&quot;color: #b58900;&quot;&gt;URLSpan&lt;/span&gt; &lt;/span&gt;{ &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;public&lt;/span&gt; &lt;span class=&quot;title&quot; style=&quot;color: #268bd2;&quot;&gt;NonLongClickableUrlSpan&lt;/span&gt;(String url) { &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;super&lt;/span&gt;(url); &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; } &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;annotation&quot;&gt;@Override&lt;/span&gt; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;public&lt;/span&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;void&lt;/span&gt; &lt;span class=&quot;title&quot; style=&quot;color: #268bd2;&quot;&gt;onClick&lt;/span&gt;(View widget) { &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;if&lt;/span&gt; (widget.getTag() != &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;null&lt;/span&gt;) { &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; widget.setTag(&lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;null&lt;/span&gt;); &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;return&lt;/span&gt;; &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; } &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;color: #859900;&quot;&gt;super&lt;/span&gt;.onClick(widget); &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; } &lt;/div&gt; &lt;div class=&quot;line&quot;&gt; } &lt;/div&gt; &lt;/td&gt; 直接通过tag判断，这个TextView的Tag已经用做其他用途了？没事，setTag还有一个重载版本：setTag(int, Object)。
