nnable) { &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;font-weight: bold; color: #7f0055;&quot;&gt;int&lt;/span&gt; end = text.length(); &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; Spannable sp = (Spannable) tv.getText(); &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; URLSpan[] urls = sp.getSpans(&lt;span class=&quot;number&quot; style=&quot;color: #c00000;&quot;&gt;&lt;/span&gt;, end, URLSpan.&lt;span class=&quot;keyword&quot; style=&quot;font-weight: bold; color: #7f0055;&quot;&gt;class&lt;/span&gt;); &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; SpannableStringBuilder style = &lt;span class=&quot;keyword&quot; style=&quot;font-weight: bold; color: #7f0055;&quot;&gt;new&lt;/span&gt; SpannableStringBuilder(text); &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; style.clearSpans();&lt;span class=&quot;comment&quot; style=&quot;color: #008200;&quot;&gt;// should clear old spans&lt;/span&gt; &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; &lt;span class=&quot;keyword&quot; style=&quot;font-weight: bold; color: #7f0055;&quot;&gt;for&lt;/span&gt; (URLSpan url : urls) { &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; MyURLSpan myURLSpan = &lt;span class=&quot;keyword&quot; style=&quot;font-weight: bold; color: #7f0055;&quot;&gt;new&lt;/span&gt; MyURLSpan(url.getURL()); &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; style.setSpan(myURLSpan, sp.getSpanStart(url), sp.getSpanEnd(url), Spannable.SPAN_EXCLUSIVE_INCLUSIVE); &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; } &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; tv.setText(style); &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; } &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; } &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; &lt;/span&gt; - &lt;span style=&quot;color: black;&quot;&gt; &lt;/span&gt