// 获得最近运行的应用
List&lt;ActivityManager.RecentTaskInfo&gt; appList4 = mActivityManager
.getRecentTasks(100, 1);
for (ActivityManager.RecentTaskInfo running : appList4) {
System.out.println(running.origActivity.getClassName());
}
