riendNameView&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&#34;na&#34; style=&#34;color: #81a2be !important;&#34;&gt;getFriendNames&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;();&amp;lt;/span&gt; &amp;lt;/span&gt;&amp;lt;span class=&#34;line&#34;&gt; &amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;Intent&amp;lt;/span&gt; &amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;i&amp;lt;/span&gt; &amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;=&amp;lt;/span&gt; &amp;lt;span class=&#34;k&#34; style=&#34;color: #de935f !important;&#34;&gt;new&amp;lt;/span&gt; &amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;Intent&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;MainActivity&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&#34;na&#34; style=&#34;color: #81a2be !important;&#34;&gt;this&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;FriendCountActivity&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&#34;na&#34; style=&#34;color: #81a2be !important;&#34;&gt;class&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;);&amp;lt;/span&gt; &amp;lt;/span&gt;&amp;lt;span class=&#34;line&#34;&gt; &amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;i&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;.&amp;lt;/span&gt;&amp;lt;span class=&#34;na&#34; style=&#34;color: #81a2be !important;&#34;&gt;putStringArrayListExtra&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&#34;s&#34; style=&#34;color: #8abeb7 !important;&#34;&gt;&#34;names&#34;&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;,&amp;lt;/span&gt; &amp;lt;span class=&#34;k&#34; style=&#34;color: #de935f !important;&#34;&gt;new&amp;lt;/span&gt; &amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;ArrayList&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;&amp;lt;&amp;lt;/span&gt;&amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;String&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;&amp;gt;(&amp;lt;/span&gt;&amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;names&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;));&amp;lt;/span&gt; &amp;lt;/span&gt;&amp;lt;span class=&#34;line&#34;&gt; &amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;startActivity&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;(&amp;lt;/span&gt;&amp;lt;span class=&#34;n&#34; style=&#34;color: #81a2be !important;&#34;&gt;i&amp;lt;/span&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;);&amp;lt;/span&gt; &amp;lt;/span&gt;&amp;lt;span class=&#34;line&#34;&gt; &amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;}&amp;lt;/span&gt; &amp;lt;/span&gt;&amp;lt;span class=&#34;line&#34;&gt;&amp;lt;span class=&#34;o&#34; style=&#34;font-weight: bold !important;&#34;&gt;});&amp;lt;/span&gt; &amp;lt;/span&gt;` &lt;/td&gt; &lt;/tr&gt; &lt;/table&gt; &lt;/div&gt;&lt;/figure&gt; Though this is a contrived example, compound custom views are a great way to encapsulate functionality that would otherwise be strewn throughout your Activities and Fragments. They provide testable, reusable code that makes for more stable apps. I encourage you to see where you can use custom compound views in your apps, and share them with other devs if you can and they would be useful. Get the code for the sample app on [Github](https://github.com/rharter/CompoundViews).

前言 这段时间在研究android平台上的开源项目——StandupTimer，这是由jwood所设计的一个较为简单android应用，用于控制会议时间，类似秒表倒计时。 PreferenceActivity PreferenceActivity是android提供的对系统信息和配置进行自动保存的Activity,它通过[SharedPreference](http://developer.android.com/reference/android/content/SharedPreferences.html)方式将信息保存在XML 文件当中。使用PreferenceActivity不需要我们对SharedPreference进行操作，系统会自动对Activity 的各种View上的改变进行保存（这个真是太赞了！）。 在android项目中添加一个 android xml 文件需要注意的是这次选择的是 Preference。而不是以往的Layout ![](http://pic002.cnblogs.com/img/xinsuhui/201009/2010090109571786.gif) 这个文件是保存在 res /xml 路径下的。 PreferenceScreen xml preference下的View是有限的，只有下面几个： - CheckBoxPreference:CheckBox选择项，对应的值的ture或flase - EditTextPreference:输入编辑框，值为String类型，会弹出对话框供输入。 - ListPreference: 列表选择，弹出对话框供选择。 - Preference：只进行文本显示，需要与其他进行组合使用。 - PreferenceCategory：用于分组。 - RingtonePreference：系统玲声选择 更多关于 PreferenceScreen的介绍可以查看博客园上的一篇文章：[Android之PreferenceActivity](http://www.cnblogs.com/wservices/archive/2010/07/08/1773449.html) ![复制代码](http://common.cnblogs.com/images/copycode.gif) &lt;div&gt; &lt;span style=&quot;color: #0000ff;&quot;&gt;&lt;?&lt;/span&gt;&lt;span style=&quot;color: #ff00ff;&quot;&gt;xml version=&amp;#8221;1.0&amp;#8243; encoding=&amp;#8221;utf-8&amp;#8243;&lt;/span&gt;&lt;span style=&quot;color: #0000ff;&quot;&gt;?&gt;&lt;/span&gt; &laquo;/span&gt;PreferenceScreen xmlns:android=”http://schemas.android.com/apk/res/android”&gt; &laquo;/span&gt;CheckBoxPreference android:key=”sounds” android:title=”@string/play_sounds” android:summary=”@string/play_sounds_summary” android:defaultValue=”true”&gt;&lt;/CheckBoxPreference&gt; &laquo;/span&gt;EditTextPreference android:key=”warning_time” android:title=”@string/warning_time” android:summary=”@string/warning_time_summary” android:defaultValue=”15″ android:inputType=”phone” android:digits=”0123456789″&gt;&lt;/EditTextPreference&gt; &laquo;/span&gt;CheckBoxPreference android:key=”unlimited_participants” android:title=”@string/unlimited_participants” android:summary=”@string/unlimited_participants_summary” android:defaultValue=”false”&gt;&lt;/CheckBoxPreference&gt; &laquo;/span&gt;CheckBoxPreference android:key=”variable_meeting_length” android:title=”@string/variable_meeting_length” android:summary=”@string/variable_meeting_length_summary” android:defaultValue=”false”&gt;&lt;/CheckBoxPreference&gt; &lt;/PreferenceScreen&gt; &lt;div class=&quot;cnblogs_code_toolbar&quot;&gt; &lt;span class=&quot;cnblogs_code_copy&quot;&gt;&lt;a style=&quot;color: green;&quot; title=&quot;复制代码&quot;&gt;![复制代码](http://common.cnblogs.com/images/copycode.gif)&lt;/a&gt;&lt;/span&gt; &lt;/div&gt; &amp;nbsp; android:key 唯一标识符。它对应保存的XML保存的配置文件中的节点的 name属性 android:defaultValue 默认值，对应XML中的Value属性的值。 ![复制代码](http://common.cnblogs.com/images/copycode.gif) &lt;div&gt; /** PreferenceActivity 会自动保存更改 */ @Override protected void onCreate(Bundle savedInstanceState) { super.onCreate(savedInstanceState); this.addPreferencesFromResource(R.xml.setting); }
![复制代码](http://common.cnblogs.com/images/copycode.gif) &amp;nbsp; 当PreferenceActivity上的View有所更改时，系统会自动将对应的值更新到XML配置文件中，该文件可以在android 的 file explorer 中的 data/data/&amp;#8221;yourPageName&amp;#8221;/shared_prefs/&amp;#8221;yourpageName&amp;#8221;_prefenrences.xml中找到。“yourpageName”表示你项目所在的包。 获取配置信息 为了方便的获取配置信息，我们可以在PreferenceActivity里添加一些pulbic 方法来公开配置信息的访问。 ![复制代码](http://common.cnblogs.com/images/copycode.gif) &lt;div&gt; &lt;span style=&quot;color: #008000;&quot;&gt;/**&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt; 获取是否播放声音 */ publicstaticboolean playSounds(Context context) { return PreferenceManager.getDefaultSharedPreferences(context).getBoolean(SOUNDS, SOUNDS_DEFAULT); }
&lt;span style=&quot;color: #008000;&quot;&gt;/**&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt; 设置播放的声音 * @param context 上下文 * @param value 是否播放 */ publicstaticvoid setPlaySounds(Context context, boolean value) { PreferenceManager.getDefaultSharedPreferences(context).edit().putBoolean(SOUNDS, value).commit(); }
&lt;span style=&quot;color: #008000;&quot;&gt;/**&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt; 获取警告时间 * @param context 上下文 * @return 警告时间秒 */ publicstaticint getWarningTime(Context context) { String value=PreferenceManager.getDefaultSharedPreferences(context).getString(WARNING_TIME,Integer.toString(WARNING_TIME_DEFAULT)); try { return Integer.parseInt(value); } catch(NumberFormatException e) { setWarningTime(context, WARNING_TIME_DEFAULT); return WARNING_TIME_DEFAULT; }
} &lt;span style=&quot;color: #008000;&quot;&gt;/**&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt; 设置警告时间 * @param context 上下文 * @param warningTime 警告时间 */ publicstaticvoid setWarningTime(Context context, int warningTime) { PreferenceManager.getDefaultSharedPreferences(context).edit().putString(WARNING_TIME, Integer.toString(warningTime)).commit();
} &lt;span style=&quot;color: #008000;&quot;&gt;/**&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt; 参加人数无限制 * @param context * @return */ publicstaticboolean allowUnlimitedParticipants(Context context) { return PreferenceManager.getDefaultSharedPreferences(context).getBoolean(UNLIMITED_PARTICIPANTS, UNLIMITED_PARTICIPANTS_DEFAULT); }
&lt;span style=&quot;color: #0000ff;&quot;&gt;public&lt;/span&gt;&lt;span style=&quot;color: #0000ff;&quot;&gt;static&lt;/span&gt;&lt;span style=&quot;color: #0000ff;&quot;&gt;void&lt;/span&gt; setAllowUnlimitedParticipants(Context context, &lt;span style=&quot;color: #0000ff;&quot;&gt;boolean&lt;/span&gt; value) { PreferenceManager.getDefaultSharedPreferences(context).edit().putBoolean(UNLIMITED_PARTICIPANTS, value).commit(); }
&lt;span style=&quot;color: #008000;&quot;&gt;/**&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt; 允许编辑会议时间 * @param context * @return */ publicstaticboolean allowVariableMeetingLength(Context context) { return PreferenceManager.getDefaultSharedPreferences(context).getBoolean(VARIABLE_MEETING_LENGTH, VARIABLE_MEETING_LENGTH_DEFAULT); }
&lt;span style=&quot;color: #0000ff;&quot;&gt;public&lt;/span&gt;&lt;span style=&quot;color: #0000ff;&quot;&gt;static&lt;/span&gt;&lt;span style=&quot;color: #0000ff;&quot;&gt;void&lt;/span&gt; setAllowVariableMeetingLength(Context context, &lt;span style=&quot;color: #0000ff;&quot;&gt;boolean&lt;/span&gt; value) { PreferenceManager.getDefaultSharedPreferences(context).edit().putBoolean(VARIABLE_MEETING_LENGTH, value).commit(); }
&lt;div class=&quot;cnblogs_code_toolbar&quot;&gt; &lt;span class=&quot;cnblogs_code_copy&quot;&gt;&lt;a style=&quot;color: green;&quot; title=&quot;复制代码&quot;&gt;![复制代码](http://common.cnblogs.com/images/copycode.gif)&lt;/a&gt;&lt;/span&gt; &lt;/div&gt;&lt;/div&gt; &amp;nbsp; getDefaultSharedPreferences(Context )用来获取preferences.以后的操作就和普通的Sharedpreferences一样了，如果需要修改某项配置的信息，记得最后需要 commit()。 当其他地方需要使用配置时，可以直接调用 setting.getXXX() 方法来获取配置信息。

public class LngLat {
/**
根据经纬度，获取两点间的距离 @author zhijun.wu @param lng1 经度 @param lat1 纬度 @param lng2 @param lat2 @return @date 2011-8-10
*/
public static double distanceByLngLat(double lng1, double lat1, double lng2, double lat2) {
double radLat1 = lat1 * Math.PI / 180;
double radLat2 = lat2 * Math.PI / 180;
double a = radLat1 – radLat2;
double b = lng1 * Math.PI / 180 – lng2 * Math.PI / 180;
double s = 2 * Math.asin(Math.sqrt(Math.pow(Math.sin(a / 2), 2) + Math.cos(radLat1)
* Math.cos(radLat2) * Math.pow(Math.sin(b / 2), 2)));
s = s * 6378137.0;// 取WGS84标准参考椭球中的地球长半径(单位:m)
s = Math.round(s * 10000) / 10000; return s;
}
/**
说明： @author zhijun.wu @param args @throws Exception @date 2008-5-16
*/
public static void main(String[] args) throws Exception {
System.out.println(distanceByLngLat(102.6592, 25.0751, 102.7655, 24.9525));
}
} /**
计算两坐标的距离
*/
public static int distance(double lat1, double lng1, double lat2,
double lng2) {
double dd = Math.PI / 180;
double x1 = lat1 * dd, x2 = lat2 * dd;
double y1 = lng1 * dd, y2 = lng2 * dd;
double R = 6371004;//地球半径
double distance = (2 * R * Math.asin(Math.sqrt(2 – 2 * Math.cos(x1)
* Math.cos(x2) * Math.cos(y1 – y2) – 2 * Math.sin(x1) Math.sin(x2)) / 2));
// km 返回
// return distance*1000;
return (int) distance;
}
